CREATE OR REPLACE FUNCTION public.add_cart_line(p_org_id uuid, p_offer_id uuid, p_quantity_kg numeric, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare v_replay jsonb; v_order_id uuid; v_line_id uuid; v_quantity numeric; v_result jsonb;
begin
  perform public.commerce_assert_buyer_member(p_org_id);
  v_replay := public.commerce_request_begin(p_request_id, 'add_cart_line', p_org_id);
  if v_replay is not null then return v_replay; end if;
  if p_quantity_kg is null or p_quantity_kg <= 0 then raise exception 'requested_quantity_not_available'; end if;
  v_order_id := public.commerce_resolve_cart(p_org_id);
  perform 1 from public.orders where id = v_order_id for update;
  insert into public.order_items (order_id, offer_id, quantity_kg) values (v_order_id, p_offer_id, p_quantity_kg)
  on conflict (order_id, offer_id) do update set quantity_kg = public.order_items.quantity_kg + excluded.quantity_kg
  returning id, quantity_kg into v_line_id, v_quantity;
  v_result := jsonb_build_object('order_id', v_order_id, 'line_id', v_line_id, 'quantity_kg', v_quantity);
  perform public.commerce_request_complete(p_request_id, v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_convert_legacy_draft(p_order_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare v_replay jsonb; v_order public.orders%rowtype; v_result jsonb;
begin
  if not public.is_platform_admin() then raise exception 'forbidden'; end if;
  if not public.mfa_satisfied() then raise exception 'mfa_step_up_required'; end if;
  v_replay := public.commerce_request_begin(p_request_id, 'admin_convert_legacy_draft', p_order_id);
  if v_replay is not null then return v_replay; end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.id is null then raise exception 'order_not_found'; end if;
  if v_order.commerce_flow <> 'LEGACY' or v_order.status <> 'DRAFT'
     or exists (select 1 from public.order_shipments s where s.order_id = p_order_id and s.status <> 'CANCELLED') then
    raise exception 'legacy_draft_not_convertible';
  end if;
  perform set_config('app.internal_transition', 'true', true);
  update public.orders set commerce_flow = 'BANK_TRANSFER_V1' where id = p_order_id;
  perform set_config('app.internal_transition', 'false', true);
  v_result := jsonb_build_object('order_id', p_order_id, 'commerce_flow', 'BANK_TRANSFER_V1');
  insert into public.audit_logs (actor_user_id, entity_type, entity_id, action, old_data, new_data, metadata, correlation_id)
  values (auth.uid(), 'orders', p_order_id, 'CONVERT_LEGACY_DRAFT', jsonb_build_object('commerce_flow', 'LEGACY', 'status', 'DRAFT'),
    jsonb_build_object('commerce_flow', 'BANK_TRANSFER_V1', 'status', 'DRAFT'),
    jsonb_build_object('operation', 'admin_convert_legacy_draft', 'request_id', p_request_id), p_request_id);
  perform public.commerce_request_complete(p_request_id, v_result); return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_delivery_reservation(p_shipment_item_id uuid, p_order_item_id uuid, p_lot_id uuid, p_buyer_organization_id uuid, p_planned_quantity_kg numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_alloc_count int;
  v_alloc public.storage_allocations%rowtype;
  v_position public.inventory_positions%rowtype;
  v_rows int;
begin
  select count(*) into v_alloc_count
  from public.storage_allocations
  where order_item_id = p_order_item_id
    and owner_organization_id = p_buyer_organization_id;
  if v_alloc_count = 0 then
    raise exception 'delivery_reservation_position_missing';
  elsif v_alloc_count > 1 then
    raise exception 'delivery_reservation_position_ambiguous';
  end if;

  select * into v_alloc from public.storage_allocations
  where order_item_id = p_order_item_id
    and owner_organization_id = p_buyer_organization_id
  limit 1;

  select * into v_position from public.inventory_positions ip
  where ip.lot_id = p_lot_id
    and ip.owner_organization_id = p_buyer_organization_id
    and ip.warehouse_id = v_alloc.warehouse_id
    and ip.warehouse_location_id is not distinct from v_alloc.warehouse_location_id
  for update;
  if v_position.id is null
     or (v_position.available_quantity_kg - v_position.reserved_quantity_kg) < p_planned_quantity_kg then
    raise exception 'delivery_reservation_insufficient_inventory';
  end if;

  -- The only permitted child-column mutation is bracketed by this transaction-local marker. It is set
  -- by this SECURITY DEFINER function immediately around an exact guarded UPDATE; clients cannot
  -- supply it through normal table DML, and the child trigger rejects every other changed business
  -- column while the marker is present.
  perform set_config('app.delivery_reservation_mutation', 'true', true);
  update public.shipment_items
  set reserved_quantity_kg = p_planned_quantity_kg
  where id = p_shipment_item_id and reserved_quantity_kg = 0;
  perform set_config('app.delivery_reservation_mutation', 'false', true);
  get diagnostics v_rows = row_count;
  if v_rows = 1 then
    update public.inventory_positions
    set reserved_quantity_kg = reserved_quantity_kg + p_planned_quantity_kg,
        updated_at = now()
    where id = v_position.id;
  else
    raise exception 'delivery_reservation_ledger_inconsistent';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_order_checkout_ready(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_order public.orders%rowtype;
begin

  select *
  into v_order
  from public.orders
  where id = p_order_id
  for update;


  if v_order.id is null then
    raise exception 'order_not_found';
  end if;


  if v_order.status <> 'CONFIRMED' then
    raise exception
      'order_must_be_confirmed_before_checkout';
  end if;


  if not public.organization_can_buy(
    v_order.buyer_organization_id
  ) then
    raise exception 'buyer_not_authorized';
  end if;


  if not exists (
    select 1
    from public.order_items oi
    where oi.order_id = p_order_id
  ) then
    raise exception 'order_has_no_items';
  end if;


  if not exists (
    select 1
    from public.order_shipments s
    where s.order_id = p_order_id
      and s.status in (
        'READY',
        'RESERVED'
      )
      and s.ready_at is not null
  ) then
    raise exception
      'shipment_must_be_ready_before_checkout';
  end if;


  if exists (
    select 1
    from public.order_items oi
    where oi.order_id = p_order_id
      and coalesce(
        (
          select sum(si.planned_quantity_kg)
          from public.shipment_items si
          join public.order_shipments os
            on os.id = si.shipment_id
          where si.order_item_id = oi.id
            and os.status not in (
              'CANCELLED',
              'FAILED'
            )
        ),
        0
      ) <> oi.quantity_kg
  ) then
    raise exception
      'shipment_quantities_do_not_match_order';
  end if;

end;
$function$

CREATE OR REPLACE FUNCTION public.attach_coffee_media(p_coffee_id uuid, p_object_path text, p_original_name text, p_mime_type text, p_size_bytes bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_coffee uuid;
  v_count int;
  v_file_asset_id uuid;
  v_media_id uuid;
  v_next_order int;
  v_prefix text := 'catalogue/' || p_coffee_id::text || '/';
begin
  if auth.uid() is null or public.is_blocked_user() or not public.is_platform_admin() then
    raise exception 'forbidden';
  end if;

  select id into v_coffee from public.coffees where id = p_coffee_id for update;
  if v_coffee is null then
    raise exception 'coffee_not_found';
  end if;

  if p_object_path is null or left(p_object_path, char_length(v_prefix)) <> v_prefix
     or char_length(p_object_path) <= char_length(v_prefix) or position('..' in p_object_path) > 0 then
    raise exception 'coffee_media_object_path_invalid';
  end if;
  if p_mime_type is null or p_mime_type not in ('image/jpeg', 'image/png', 'image/webp') then
    raise exception 'coffee_media_type_invalid';
  end if;
  if p_size_bytes is null or p_size_bytes <= 0 or p_size_bytes > 5242880 then
    raise exception 'coffee_media_size_invalid';
  end if;

  select count(*) into v_count from public.coffee_media where coffee_id = p_coffee_id;
  if v_count >= 12 then
    raise exception 'coffee_media_limit_reached';
  end if;

  insert into public.file_assets (uploaded_by, organization_id, bucket_name, object_path, original_name, mime_type, size_bytes, is_private)
  values (auth.uid(), null, 'public-assets', p_object_path, left(coalesce(p_original_name, ''), 255), p_mime_type, p_size_bytes, false)
  returning id into v_file_asset_id;

  select coalesce(max(sort_order), -1) + 1 into v_next_order from public.coffee_media where coffee_id = p_coffee_id;

  insert into public.coffee_media (coffee_id, file_asset_id, sort_order, is_primary)
  values (p_coffee_id, v_file_asset_id, v_next_order, v_count = 0)
  returning id into v_media_id;

  return v_media_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.attach_kyb_document(p_application_id uuid, p_document_type text, p_object_path text, p_original_name text, p_mime_type text, p_size_bytes bigint, p_expires_at date DEFAULT NULL::date, p_supersedes_document_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$ begin
  if not public.mfa_satisfied() then raise exception 'mfa_step_up_required' using errcode = '42501'; end if;
  return public.t033_internal_attach_kyb_document(
    p_application_id, p_document_type, p_object_path, p_original_name, p_mime_type,
    p_size_bytes, p_expires_at, p_supersedes_document_id
  );
end; $function$

CREATE OR REPLACE FUNCTION public.attach_offer_media(p_offer_id uuid, p_object_path text, p_original_name text, p_mime_type text, p_size_bytes bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_seller_org uuid;
  v_status text;
  v_count int;
  v_file_asset_id uuid;
  v_media_id uuid;
  v_next_order int;
  v_is_first boolean;
begin
  if auth.uid() is null then
    raise exception 'forbidden';
  end if;
  if public.is_blocked_user() then
    raise exception 'forbidden';
  end if;

  select seller_organization_id, status into v_seller_org, v_status
  from public.coffee_offers where id = p_offer_id and deleted_at is null
  for update;

  if v_seller_org is null then
    raise exception 'offer_not_found';
  end if;
  if not (public.is_platform_admin() or public.is_org_member(v_seller_org)) then
    raise exception 'forbidden';
  end if;
  if v_status not in ('DRAFT', 'PENDING_REVIEW', 'APPROVED', 'PUBLISHED', 'PARTIALLY_FILLED') then
    raise exception 'offer_media_not_editable';
  end if;

  -- REVIEW FIX (pre-apply security review, 2026-09-22): this function is otherwise the only place in
  -- this migration that accepts BOTH an ownership-scoping id (p_offer_id) and a free-form Storage path
  -- (p_object_path) without cross-validating them — unlike set_my_avatar()'s own p_object_path check
  -- against auth.uid(). Without this, a seller-of-record for SOME offer could call this function with
  -- a p_object_path belonging to a DIFFERENT offer they do not own, attaching someone else's already-
  -- uploaded image to their own listing. The existing file_assets_bucket_name_object_path_key UNIQUE
  -- constraint already blocks this once the real owner has attached that same path themselves, but
  -- does not close a path-squatting race (attaching a GUESSED path before its real owner does) or the
  -- general principle that this function should validate its own inputs, not rely on an incidental
  -- constraint elsewhere. Mirrors set_my_avatar()'s exact validation shape.
  if p_object_path is null or left(p_object_path, char_length('offers/' || p_offer_id::text || '/')) <> ('offers/' || p_offer_id::text || '/') then
    raise exception 'offer_media_object_path_invalid';
  end if;

  select count(*) into v_count from public.coffee_offer_media where offer_id = p_offer_id;
  if v_count >= 8 then
    raise exception 'offer_media_limit_reached';
  end if;
  v_is_first := v_count = 0;

  insert into public.file_assets (uploaded_by, organization_id, bucket_name, object_path, original_name, mime_type, size_bytes, is_private)
  values (auth.uid(), v_seller_org, 'listing-media', p_object_path, p_original_name, p_mime_type, p_size_bytes, true)
  returning id into v_file_asset_id;

  select coalesce(max(sort_order), -1) + 1 into v_next_order from public.coffee_offer_media where offer_id = p_offer_id;

  insert into public.coffee_offer_media (offer_id, file_asset_id, sort_order, is_primary)
  values (p_offer_id, v_file_asset_id, v_next_order, v_is_first)
  returning id into v_media_id;

  return v_media_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_proforma_snapshot_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_id uuid := coalesce(to_jsonb(new) ->> 'proforma_id', to_jsonb(new) ->> 'id')::uuid;
  h public.proforma_invoices%rowtype;
  o public.orders%rowtype;
  bi public.proforma_bank_instructions%rowtype;
  f public.order_financials%rowtype;
  v_problems text := '';
  v_items record;
  v_groups record;
  v_settle record;
  v_n bigint;
begin
  if v_id is null then
    return null;
  end if;
  select * into h from public.proforma_invoices where id = v_id;
  if not found then
    return null;
  end if;

  if h.validity_hours_snapshot is null then
    if exists (select 1 from public.proforma_invoice_items where proforma_id = v_id and seller_type_snapshot is not null)
       or exists (select 1 from public.proforma_line_economics where proforma_id = v_id)
       or exists (select 1 from public.proforma_fulfillment_groups where proforma_id = v_id)
       or exists (select 1 from public.proforma_seller_settlements where proforma_id = v_id)
       or exists (select 1 from public.proforma_bank_instructions where proforma_id = v_id)
       or exists (select 1 from public.order_financials where proforma_id = v_id) then
      raise exception 'proforma_snapshot_unbalanced' using detail = 'a LEGACY proforma cannot hold Feature 013 snapshot rows';
    end if;
    return null;
  end if;

  select * into o from public.orders where id = h.order_id;

  -- Lines: at least one, all Feature 013, each with its economics; VAT per line after discount (FIN-002/FIN-004).
  select count(*) as n, count(*) filter (where i.seller_type_snapshot is null) as legacy_lines,
         count(*) filter (where i.seller_type_snapshot is not null and e.proforma_item_id is null) as without_economics,
         count(*) filter (where i.vat_amount is distinct from round(i.net_amount * h.tax_rate_snapshot / 100, 2)) as vat_mismatch,
         count(*) filter (where (e.seller_funded_discount > 0 and i.promotion_funding_source is distinct from 'SELLER')
                             or (e.hills_funded_discount > 0 and i.promotion_funding_source is distinct from 'HILLS')) as funding_mismatch,
         coalesce(sum(i.gross_amount), 0) as gross, coalesce(sum(i.discount_amount), 0) as discount,
         coalesce(sum(i.net_amount), 0) as net, coalesce(sum(i.vat_amount), 0) as vat, coalesce(sum(i.quantity_kg), 0) as qty
  into v_items
  from public.proforma_invoice_items i
  left join public.proforma_line_economics e on e.proforma_item_id = i.id
  where i.proforma_id = v_id;
  if v_items.n = 0 then
    v_problems := v_problems || 'no lines; ';
  end if;
  if v_items.legacy_lines <> 0 then
    v_problems := v_problems || v_items.legacy_lines || ' line(s) without the Feature 013 snapshot; ';
  end if;
  if v_items.without_economics <> 0 then
    v_problems := v_problems || v_items.without_economics || ' line(s) without line economics; ';
  end if;
  if v_items.vat_mismatch <> 0 then
    v_problems := v_problems || v_items.vat_mismatch || ' line VAT amount(s) differ from round(net × rate, 2); ';
  end if;
  if v_items.funding_mismatch <> 0 then
    v_problems := v_problems || v_items.funding_mismatch || ' line(s) split a discount against its funding source (FIN-011); ';
  end if;

  -- Groups: at least one; each has lines, its merchandise equals its lines, shipping VAT follows the tax base (FIN-005).
  select count(*) as n,
         count(*) filter (where not exists (select 1 from public.proforma_invoice_items i where i.fulfillment_group_id = g.id)) as empty_groups,
         count(*) filter (where g.merchandise_net_amount is distinct from
                            (select coalesce(sum(i.net_amount), 0) from public.proforma_invoice_items i where i.fulfillment_group_id = g.id)) as net_mismatch,
         count(*) filter (where g.shipping_vat_amount is distinct from
                            case when h.tax_base_snapshot = 'MERCHANDISE_AND_SHIPPING' then round(g.shipping_amount * h.tax_rate_snapshot / 100, 2) else 0 end) as vat_mismatch,
         coalesce(sum(g.shipping_amount), 0) as shipping, coalesce(sum(g.shipping_vat_amount), 0) as shipping_vat
  into v_groups
  from public.proforma_fulfillment_groups g
  where g.proforma_id = v_id;
  if v_groups.n = 0 then
    v_problems := v_problems || 'no fulfillment group; ';
  end if;
  if v_groups.empty_groups <> 0 then
    v_problems := v_problems || v_groups.empty_groups || ' fulfillment group(s) without lines; ';
  end if;
  if v_groups.net_mismatch <> 0 then
    v_problems := v_problems || v_groups.net_mismatch || ' group merchandise amount(s) differ from their lines; ';
  end if;
  if v_groups.vat_mismatch <> 0 then
    v_problems := v_problems || v_groups.vat_mismatch || ' group shipping VAT amount(s) differ from the tax base/rate; ';
  end if;

  -- Header = sums (FIN-009); the NOT NULL DEFAULT 0 placeholders cannot satisfy this for a real order.
  if (h.merchandise_gross, h.discount_total, h.merchandise_net, h.shipping_total, h.vat_total)
     is distinct from (v_items.gross, v_items.discount, v_items.net, v_groups.shipping, v_items.vat + v_groups.shipping_vat) then
    v_problems := v_problems || 'header totals differ from the frozen lines and groups; ';
  end if;

  -- Seller settlements: exactly one per seller of the lines, with the lines' seller type.
  select count(*) filter (where s.proforma_id is null) as missing, count(*) filter (where l.seller_organization_id is null) as orphan,
         count(*) filter (where s.proforma_id is not null and l.seller_organization_id is not null and s.seller_type_snapshot <> l.seller_type_snapshot) as type_mismatch,
         coalesce(sum(s.commission_amount), 0) as commission, coalesce(sum(s.seller_net_amount), 0) as seller_net,
         coalesce(sum(s.hills_share_amount), 0) as hills_share, coalesce(sum(s.seller_funded_discount), 0) as sf,
         coalesce(sum(s.hills_funded_discount), 0) as hf
  into v_settle
  from (select distinct seller_organization_id, seller_type_snapshot from public.proforma_invoice_items
        where proforma_id = v_id and seller_type_snapshot is not null) l
  full join (select * from public.proforma_seller_settlements where proforma_id = v_id) s
    on s.seller_organization_id = l.seller_organization_id;
  select count(*) into v_n from (select seller_organization_id from public.proforma_invoice_items
                                 where proforma_id = v_id and seller_type_snapshot is not null
                                 group by seller_organization_id having count(distinct seller_type_snapshot) > 1) x;
  if v_settle.missing <> 0 or v_settle.orphan <> 0 or v_settle.type_mismatch <> 0 or v_n <> 0 then
    v_problems := v_problems || 'seller settlements do not match the sellers of the lines; ';
  end if;

  -- Bank instructions: present, quoting the order and proforma codes, and consistent with the masked header copy.
  select * into bi from public.proforma_bank_instructions where proforma_id = v_id;
  if bi.proforma_id is null then
    v_problems := v_problems || 'no bank instructions; ';
  else
    if position(o.order_code in bi.payment_reference) = 0 or position(h.proforma_code in bi.payment_reference) = 0 then
      v_problems := v_problems || 'payment_reference does not quote the order code and the proforma code; ';
    end if;
    if (h.bank_account_masked ->> 'bank_name', h.bank_account_masked ->> 'account_name', h.bank_account_masked ->> 'swift_code',
        h.bank_account_masked ->> 'account_number_last4', h.bank_account_masked ->> 'iban_last4')
       is distinct from
       (bi.bank_name, bi.account_name, bi.swift_code,
        case when bi.account_number is null then null when char_length(bi.account_number) < 8 then '****' else '****' || right(bi.account_number, 4) end,
        case when bi.iban is null then null when char_length(bi.iban) < 8 then '****' else '****' || right(bi.iban, 4) end) then
      v_problems := v_problems || 'bank_account_masked does not match the bank instructions; ';
    end if;
  end if;

  -- The open order carries the same destination snapshot.
  if o.current_proforma_id = v_id and h.destination_snapshot is distinct from o.destination_snapshot then
    v_problems := v_problems || 'destination_snapshot differs from the order''s; ';
  end if;

  -- order_financials is the order-level summary of the newest version (base_subtotal = merchandise gross).
  if not exists (select 1 from public.proforma_invoices p where p.order_id = h.order_id and p.version > h.version) then
    select * into f from public.order_financials where order_id = h.order_id;
    if f.order_id is null or f.proforma_id is distinct from v_id then
      v_problems := v_problems || 'order_financials does not summarize this proforma; ';
    elsif (f.base_subtotal, f.discount_amount, f.shipping_amount, f.vat_amount, f.buyer_total_amount, f.total_quantity_kg,
           f.commission_amount, f.seller_net_amount, f.hills_share_amount, f.seller_funded_discount, f.hills_funded_discount,
           f.tax_rule_id, f.tax_percentage_snapshot, f.tax_base_snapshot)
          is distinct from
          (h.merchandise_gross, h.discount_total, h.shipping_total, h.vat_total, h.buyer_total, v_items.qty,
           v_settle.commission, v_settle.seller_net, v_settle.hills_share, v_settle.sf, v_settle.hf,
           h.tax_rule_id, h.tax_rate_snapshot, h.tax_base_snapshot) then
      v_problems := v_problems || 'order_financials differs from the frozen proforma; ';
    end if;
  end if;

  if v_problems <> '' then
    raise exception 'proforma_snapshot_unbalanced' using detail = 'proforma ' || v_id || ': ' || v_problems;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_seller_settlement_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_proforma_id uuid := new.proforma_id;
  v_seller uuid := new.seller_organization_id;
  s public.proforma_seller_settlements%rowtype;
  v_lines bigint;
  v_problems text := '';
  v_sum record;
begin
  select * into s from public.proforma_seller_settlements where proforma_id = v_proforma_id and seller_organization_id = v_seller;
  select count(*) into v_lines from public.proforma_line_economics where proforma_id = v_proforma_id and seller_organization_id = v_seller;
  if s.proforma_id is null and v_lines = 0 then
    return null;
  end if;
  if s.proforma_id is null then
    raise exception 'seller_settlement_unbalanced' using detail = 'seller ' || v_seller || ' has line economics but no settlement row';
  end if;
  if v_lines = 0 then
    raise exception 'seller_settlement_unbalanced' using detail = 'seller ' || v_seller || ' has a settlement row but no line economics';
  end if;

  select coalesce(sum(e.gross_amount), 0) as gross, coalesce(sum(e.seller_funded_discount), 0) as sf,
         coalesce(sum(e.hills_funded_discount), 0) as hf, coalesce(sum(e.commission_basis), 0) as basis,
         coalesce(sum(e.commission_amount), 0) as commission, coalesce(sum(e.seller_net_amount), 0) as seller_net,
         coalesce(sum(e.hills_share_amount), 0) as hills_share, coalesce(sum(e.buyer_net_amount), 0) as buyer_net,
         count(*) filter (where e.seller_type_snapshot is distinct from s.seller_type_snapshot
                             or e.commission_policy_id is distinct from s.commission_policy_id
                             or e.commission_tier_id is distinct from s.commission_tier_id
                             or e.commission_rate_snapshot is distinct from s.commission_rate_snapshot
                             or e.seller_qualifying_quantity_kg is distinct from s.seller_qualifying_quantity_kg) as mismatched,
         coalesce(sum(i.quantity_kg) filter (where e.seller_type_snapshot = 'MEMBER_SELLER'), 0) as member_quantity
  into v_sum
  from public.proforma_line_economics e
  join public.proforma_invoice_items i on i.id = e.proforma_item_id
  where e.proforma_id = v_proforma_id and e.seller_organization_id = v_seller;

  if (s.gross_amount, s.seller_funded_discount, s.hills_funded_discount, s.commission_basis, s.commission_amount,
      s.seller_net_amount, s.hills_share_amount, s.buyer_net_amount)
     is distinct from (v_sum.gross, v_sum.sf, v_sum.hf, v_sum.basis, v_sum.commission, v_sum.seller_net, v_sum.hills_share, v_sum.buyer_net) then
    v_problems := v_problems || 'settlement amounts differ from the sum of the line economics; ';
  end if;
  if v_sum.mismatched <> 0 then
    v_problems := v_problems || v_sum.mismatched || ' line(s) carry a different seller type or commission assignment than the settlement; ';
  end if;
  if s.seller_type_snapshot = 'MEMBER_SELLER' and s.seller_qualifying_quantity_kg is distinct from v_sum.member_quantity then
    v_problems := v_problems || 'seller_qualifying_quantity_kg is not the seller''s own member-line quantity (FIN-013); ';
  end if;
  if s.seller_net_amount < 0 or s.hills_share_amount < 0 then
    v_problems := v_problems || 'negative seller net or Hills share (FIN-012); ';
  end if;
  if v_problems <> '' then
    raise exception 'seller_settlement_unbalanced' using detail = 'proforma ' || v_proforma_id || ', seller ' || v_seller || ': ' || v_problems;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.checkout_bank_transfer_v1(p_order_id uuid, p_destination_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_replay jsonb;
  v_order public.orders%rowtype;
  v_settings public.commerce_settings%rowtype;
  v_destination public.delivery_destinations%rowtype;
  v_reservation_id uuid;
  v_expires_at timestamptz;
  v_quote jsonb;
  v_issued_at timestamptz;
  v_valid_until timestamptz;
  v_account_last4 text;
  v_iban_last4 text;
  v_masked jsonb;
  v_proforma_id uuid;
  v_proforma_code text;
  v_payment_id uuid;
  v_buyer_total numeric;
  v_item record;
  v_group jsonb;
  v_line jsonb;
  v_group_id uuid;
  v_item_id uuid;
  v_settlement record;
  v_offer public.coffee_offers%rowtype;
  v_offer_attrs record;
  v_position public.inventory_positions%rowtype;
  v_position_id uuid;
  v_reclaim_order uuid;
  v_result jsonb;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found or v_order.commerce_flow <> 'BANK_TRANSFER_V1'
     or not public.is_org_member(v_order.buyer_organization_id) then
    raise exception 'order_not_found';
  end if;
  perform public.commerce_assert_buyer_member(v_order.buyer_organization_id);

  v_replay := public.commerce_request_begin(p_request_id, 'checkout_bank_transfer_v1', p_order_id);
  if v_replay is not null then
    return v_replay;
  end if;

  -- Replay check for already held orders with active reservation
  if v_order.status = 'HOLD' and v_order.current_proforma_id is not null then
    select r.id, r.expires_at into v_reservation_id, v_expires_at
    from public.inventory_reservations r
    where r.order_id = p_order_id and r.status = 'ACTIVE' and r.expires_at > clock_timestamp()
    limit 1;
    if v_reservation_id is not null then
      select p.id into v_payment_id from public.payments p where p.order_id = p_order_id limit 1;
      select buyer_total_amount into v_buyer_total from public.order_financials where order_id = p_order_id;
      select proforma_code into v_proforma_code from public.proforma_invoices where id = v_order.current_proforma_id;
      v_result := jsonb_build_object(
        'order_id', p_order_id,
        'order_code', v_order.order_code,
        'proforma_id', v_order.current_proforma_id,
        'proforma_code', v_proforma_code,
        'payment_id', v_payment_id,
        'reservation_id', v_reservation_id,
        'expires_at', v_expires_at,
        'buyer_total', v_buyer_total,
        'currency', v_order.currency
      );
      perform public.commerce_request_complete(p_request_id, v_result);
      return v_result;
    end if;
  end if;

  if v_order.status <> 'DRAFT' then
    raise exception 'order_not_editable';
  end if;

  select * into v_settings from public.commerce_settings where id;
  if not found or not v_settings.bank_transfer_checkout_enabled
     or (cardinality(v_settings.pilot_organization_ids) > 0
         and not v_order.buyer_organization_id = any(v_settings.pilot_organization_ids)) then
    raise exception 'checkout_disabled';
  end if;

  if p_destination_id is null then
    raise exception 'destination_required';
  end if;

  select * into v_destination from public.delivery_destinations
  where id = p_destination_id and organization_id = v_order.buyer_organization_id and retired_at is null;
  if not found then
    raise exception 'destination_not_found';
  end if;
  if v_destination.country_code <> 'AE' then
    raise exception 'destination_tax_unsupported';
  end if;

  if not exists (select 1 from public.order_items where order_id = p_order_id) then
    raise exception 'order_has_no_items';
  end if;

  -- 1. Reclaim other expired active reservations
  for v_reclaim_order in
    select distinct r.order_id
    from public.inventory_reservations r
    join public.inventory_reservation_items ri on ri.reservation_id = r.id
    join public.order_items oi on oi.offer_id = ri.offer_id and oi.order_id = p_order_id
    where r.status = 'ACTIVE' and r.expires_at <= clock_timestamp() and r.order_id <> p_order_id
    order by r.order_id
  loop
    perform public.commerce_release_reservation(v_reclaim_order);
  end loop;

  -- 2. Deterministic locks on offers ascending UUID, re-check offer availability
  for v_item in
    select oi.offer_id, sum(oi.quantity_kg) as total_quantity_kg
    from public.order_items oi
    where oi.order_id = p_order_id
    group by oi.offer_id
    order by oi.offer_id
  loop
    select * into v_offer from public.coffee_offers where id = v_item.offer_id for update;
    if v_offer.id is null or v_offer.status not in ('PUBLISHED', 'PARTIALLY_FILLED') or not v_offer.is_visible
       or (v_offer.quantity_kg - v_offer.filled_quantity_kg - v_offer.reserved_quantity_kg) < v_item.total_quantity_kg then
      raise exception 'listing_inventory_changed';
    end if;
    if v_offer.seller_type = 'MEMBER_SELLER' and not public.organization_can_sell(v_offer.seller_organization_id) then
      raise exception 'seller_not_authorized';
    end if;
  end loop;

  -- 3. Deterministic locks on backing positions ascending UUID, re-check aggregated demand
  for v_item in
    select ip.id as position_id, sum(oi.quantity_kg) as total_quantity_kg
    from public.order_items oi
    join public.coffee_offers o on o.id = oi.offer_id
    join public.inventory_positions ip
      on ip.lot_id = o.lot_id and ip.owner_organization_id = o.seller_organization_id
      and ip.warehouse_id = o.warehouse_id
      and ip.warehouse_location_id is not distinct from o.warehouse_location_id
    where oi.order_id = p_order_id
    group by ip.id
    order by ip.id
  loop
    select * into v_position from public.inventory_positions where id = v_item.position_id for update;
    if v_position.id is null or (v_position.available_quantity_kg - v_position.reserved_quantity_kg) < v_item.total_quantity_kg then
      raise exception 'seller_inventory_changed';
    end if;
  end loop;

  -- 4. Authoritative quote computation
  v_quote := public.compute_order_quote(p_order_id, p_destination_id, null);
  v_issued_at := clock_timestamp();
  v_valid_until := v_issued_at + make_interval(hours => v_settings.proforma_validity_hours);
  v_expires_at := v_issued_at + interval '20 minutes';

  v_account_last4 := case when v_quote ->> 'bank_account_number' is null then null
    when char_length(v_quote ->> 'bank_account_number') < 8 then '****'
    else '****' || right(v_quote ->> 'bank_account_number', 4) end;
  v_iban_last4 := case when v_quote ->> 'bank_iban' is null then null
    when char_length(v_quote ->> 'bank_iban') < 8 then '****'
    else '****' || right(v_quote ->> 'bank_iban', 4) end;
  v_masked := jsonb_build_object(
    'bank_name', v_quote ->> 'bank_name', 'account_name', v_quote ->> 'bank_account_name',
    'swift_code', v_quote ->> 'bank_swift',
    'account_number_last4', v_account_last4, 'iban_last4', v_iban_last4);

  -- 5. Insert proforma as ISSUED (satisfies Feature 013 snapshot triggers)
  insert into public.proforma_invoices (
    order_id, version, supersedes_proforma_id, status, issued_at, valid_until,
    validity_hours_snapshot, currency, merchandise_gross, discount_total,
    merchandise_net, shipping_total, vat_total, buyer_total, tax_rule_id,
    tax_rate_snapshot, tax_base_snapshot, buyer_snapshot, destination_snapshot,
    bank_account_masked, issued_by)
  values (
    p_order_id, 1, null, 'ISSUED', v_issued_at, v_valid_until,
    v_settings.proforma_validity_hours, 'USD',
    (v_quote ->> 'merchandise_gross')::numeric, 0,
    (v_quote ->> 'merchandise_net')::numeric,
    (v_quote ->> 'shipping_total')::numeric, (v_quote ->> 'vat_total')::numeric,
    (v_quote ->> 'buyer_total')::numeric, (v_quote ->> 'tax_rule_id')::uuid,
    (v_quote ->> 'tax_rate')::numeric, v_quote ->> 'tax_base',
    v_quote -> 'buyer_snapshot', v_quote -> 'destination_snapshot', v_masked, auth.uid())
  returning id, proforma_code into v_proforma_id, v_proforma_code;

  for v_group in select value from jsonb_array_elements(v_quote -> 'groups') loop
    insert into public.proforma_fulfillment_groups (
      proforma_id, seller_organization_id, warehouse_id, group_key,
      shipping_rule_id, delivery_method, shipping_amount, shipping_vat_amount,
      merchandise_net_amount)
    values (v_proforma_id, (v_group ->> 'seller_id')::uuid,
      (v_group ->> 'warehouse_id')::uuid,
      (v_group ->> 'seller_id') || ':' || (v_group ->> 'warehouse_id'),
      (v_group ->> 'shipping_rule_id')::uuid, v_group ->> 'delivery_method',
      (v_group ->> 'shipping')::numeric, (v_group ->> 'shipping_vat')::numeric,
      (v_group ->> 'merchandise_net')::numeric);
  end loop;

  for v_line in select value from jsonb_array_elements(v_quote -> 'lines') loop
    select id into v_group_id from public.proforma_fulfillment_groups
    where proforma_id = v_proforma_id
      and seller_organization_id = (v_line ->> 'seller_id')::uuid
      and warehouse_id = (v_line ->> 'warehouse_id')::uuid;
    if not found then raise exception 'proforma_snapshot_unbalanced'; end if;
    insert into public.proforma_invoice_items (
      proforma_id, order_item_id, description, quantity_kg, unit_price, amount,
      offer_id, offer_code_snapshot, seller_organization_id, seller_type_snapshot,
      warehouse_id, fulfillment_group_id, list_unit_price, price_tier_id,
      gross_amount, discount_amount, discount_capped, net_amount, vat_amount,
      line_total, product_name_snapshot, origin_name_snapshot, lot_code_snapshot)
    values (v_proforma_id, (v_line ->> 'order_item_id')::uuid,
      v_line ->> 'product_name', (v_line ->> 'quantity_kg')::numeric,
      (v_line ->> 'unit_price')::numeric, (v_line ->> 'net')::numeric,
      (v_line ->> 'offer_id')::uuid, v_line ->> 'offer_code',
      (v_line ->> 'seller_id')::uuid, v_line ->> 'seller_type',
      (v_line ->> 'warehouse_id')::uuid, v_group_id,
      (v_line ->> 'unit_price')::numeric, null,
      (v_line ->> 'gross')::numeric, 0, false, (v_line ->> 'net')::numeric,
      (v_line ->> 'vat')::numeric,
      (v_line ->> 'net')::numeric + (v_line ->> 'vat')::numeric,
      v_line ->> 'product_name', v_line ->> 'origin_name', v_line ->> 'lot_code')
    returning id into v_item_id;

    insert into public.proforma_line_economics (
      proforma_item_id, proforma_id, seller_organization_id, seller_type_snapshot,
      commission_policy_id, commission_tier_id, commission_rate_snapshot,
      seller_qualifying_quantity_kg, gross_amount, seller_funded_discount,
      hills_funded_discount, commission_on_gross, commission_basis,
      commission_amount, seller_net_amount, hills_share_amount, buyer_net_amount)
    values (v_item_id, v_proforma_id, (v_line ->> 'seller_id')::uuid,
      v_line ->> 'seller_type', (v_line ->> 'commission_policy_id')::uuid,
      (v_line ->> 'commission_tier_id')::uuid, (v_line ->> 'commission_rate')::numeric,
      (v_line ->> 'seller_qualifying_quantity_kg')::numeric,
      (v_line ->> 'gross')::numeric, 0, 0, (v_line ->> 'commission')::numeric,
      case when v_line ->> 'seller_type' = 'MEMBER_SELLER'
        then (v_line ->> 'gross')::numeric else 0 end,
      (v_line ->> 'commission')::numeric, (v_line ->> 'seller_net')::numeric,
      (v_line ->> 'hills_share')::numeric, (v_line ->> 'net')::numeric);
  end loop;

  for v_settlement in
    select seller_organization_id, min(seller_type_snapshot) as seller_type,
      min(commission_policy_id::text)::uuid as policy_id,
      min(commission_tier_id::text)::uuid as tier_id,
      min(commission_rate_snapshot) as rate,
      min(seller_qualifying_quantity_kg) as qualifying_quantity,
      sum(gross_amount) as gross, sum(seller_funded_discount) as seller_discount,
      sum(hills_funded_discount) as hills_discount, sum(commission_basis) as basis,
      sum(commission_amount) as commission, sum(seller_net_amount) as seller_net,
      sum(hills_share_amount) as hills_share, sum(buyer_net_amount) as buyer_net
    from public.proforma_line_economics where proforma_id = v_proforma_id
    group by seller_organization_id
  loop
    insert into public.proforma_seller_settlements (
      proforma_id, seller_organization_id, seller_type_snapshot,
      seller_qualifying_quantity_kg, commission_policy_id, commission_tier_id,
      commission_rate_snapshot, gross_amount, seller_funded_discount,
      hills_funded_discount, commission_basis, commission_amount,
      seller_net_amount, hills_share_amount, buyer_net_amount)
    values (v_proforma_id, v_settlement.seller_organization_id, v_settlement.seller_type,
      v_settlement.qualifying_quantity, v_settlement.policy_id, v_settlement.tier_id,
      v_settlement.rate, v_settlement.gross, v_settlement.seller_discount,
      v_settlement.hills_discount, v_settlement.basis, v_settlement.commission,
      v_settlement.seller_net, v_settlement.hills_share, v_settlement.buyer_net);
  end loop;

  insert into public.proforma_bank_instructions (
    proforma_id, payment_account_id, account_name, bank_name,
    account_number, iban, swift_code, currency, payment_reference)
  values (v_proforma_id, (v_quote ->> 'bank_account_id')::uuid,
    v_quote ->> 'bank_account_name', v_quote ->> 'bank_name',
    v_quote ->> 'bank_account_number', v_quote ->> 'bank_iban',
    v_quote ->> 'bank_swift', 'USD', v_order.order_code || ' / ' || v_proforma_code);

  -- 6. Insert inventory reservation and reserve quantities
  insert into public.inventory_reservations (order_id, proforma_id, status, expires_at, confirmed_by)
  values (p_order_id, v_proforma_id, 'ACTIVE', v_expires_at, auth.uid())
  returning id into v_reservation_id;

  for v_item in
    select oi.offer_id, oi.quantity_kg
    from public.order_items oi
    where oi.order_id = p_order_id
    order by oi.offer_id
  loop
    select o.lot_id, o.seller_organization_id, o.warehouse_id, o.warehouse_location_id
    into v_offer_attrs from public.coffee_offers o where o.id = v_item.offer_id;
    select id into v_position_id from public.inventory_positions ip
    where ip.lot_id = v_offer_attrs.lot_id and ip.owner_organization_id = v_offer_attrs.seller_organization_id
      and ip.warehouse_id = v_offer_attrs.warehouse_id
      and ip.warehouse_location_id is not distinct from v_offer_attrs.warehouse_location_id
    order by ip.created_at, ip.id limit 1;

    update public.inventory_positions
    set reserved_quantity_kg = reserved_quantity_kg + v_item.quantity_kg, updated_at = now()
    where id = v_position_id;

    perform set_config('app.checkout_reservation', 'true', true);
    update public.coffee_offers
    set reserved_quantity_kg = reserved_quantity_kg + v_item.quantity_kg
    where id = v_item.offer_id;
    perform set_config('app.checkout_reservation', 'false', true);

    insert into public.inventory_reservation_items (reservation_id, offer_id, inventory_position_id, quantity_kg)
    values (v_reservation_id, v_item.offer_id, v_position_id, v_item.quantity_kg);
  end loop;

  -- 7. Update proforma to CONFIRMED
  perform set_config('app.internal_transition', 'true', true);
  update public.proforma_invoices
  set status = 'CONFIRMED', confirmed_at = clock_timestamp(), confirmed_by = auth.uid()
  where id = v_proforma_id;

  -- 8. Insert order_financials (written under internal_transition while order is in DRAFT)
  insert into public.order_financials (
    order_id, proforma_id, base_subtotal, discount_amount,
    seller_funded_discount, hills_funded_discount, shipping_amount, vat_amount,
    buyer_total_amount, total_quantity_kg, commission_amount, seller_net_amount,
    hills_share_amount, currency, commission_policy_id, commission_percentage_snapshot,
    tax_rule_id, tax_percentage_snapshot, tax_base_snapshot, calculated_at)
  values (p_order_id, v_proforma_id, (v_quote ->> 'merchandise_gross')::numeric,
    0, 0, 0, (v_quote ->> 'shipping_total')::numeric, (v_quote ->> 'vat_total')::numeric,
    (v_quote ->> 'buyer_total')::numeric, (v_quote ->> 'total_quantity_kg')::numeric,
    (v_quote ->> 'commission_total')::numeric, (v_quote ->> 'seller_net_total')::numeric,
    (v_quote ->> 'hills_share_total')::numeric, 'USD', null, null,
    (v_quote ->> 'tax_rule_id')::uuid, (v_quote ->> 'tax_rate')::numeric,
    v_quote ->> 'tax_base', v_issued_at)
  on conflict (order_id) do update set
    proforma_id = excluded.proforma_id, base_subtotal = excluded.base_subtotal,
    discount_amount = excluded.discount_amount,
    seller_funded_discount = excluded.seller_funded_discount,
    hills_funded_discount = excluded.hills_funded_discount,
    shipping_amount = excluded.shipping_amount, vat_amount = excluded.vat_amount,
    buyer_total_amount = excluded.buyer_total_amount,
    total_quantity_kg = excluded.total_quantity_kg,
    commission_amount = excluded.commission_amount,
    seller_net_amount = excluded.seller_net_amount,
    hills_share_amount = excluded.hills_share_amount,
    tax_rule_id = excluded.tax_rule_id, tax_percentage_snapshot = excluded.tax_percentage_snapshot,
    tax_base_snapshot = excluded.tax_base_snapshot, calculated_at = excluded.calculated_at;

  -- 9. Update order to HOLD
  update public.orders
  set status = 'HOLD',
    delivery_destination_id = p_destination_id,
    destination_snapshot = v_quote -> 'destination_snapshot',
    current_proforma_id = v_proforma_id,
    hold_started_at = v_issued_at,
    hold_expires_at = v_expires_at,
    confirmed_at = v_issued_at
  where id = p_order_id;
  perform set_config('app.internal_transition', 'false', true);

  v_buyer_total := (v_quote ->> 'buyer_total')::numeric;

  -- 10. Insert Payment record (status = PENDING) (HIGH 2: server-derive expected_amount and link proforma_id)
  insert into public.payments (
    order_id, proforma_id, payment_method, amount, expected_amount, currency, status, payment_account_id
  ) values (
    p_order_id, v_proforma_id, 'BANK_TRANSFER', v_buyer_total, v_buyer_total, 'USD', 'PENDING',
    (v_quote ->> 'bank_account_id')::uuid
  )
  on conflict (order_id) do update set
    proforma_id = excluded.proforma_id,
    amount = excluded.amount,
    expected_amount = excluded.expected_amount,
    status = 'PENDING',
    payment_account_id = excluded.payment_account_id
  returning id into v_payment_id;

  -- 11. Notifications preservation:
  -- The order status update to HOLD triggers trg_notify_order_status_change which inserts RESERVATION_CONFIRMED.
  -- Insert ORDER_PROFORMA_ISSUED notification explicitly so Feature 014 milestone is preserved:
  insert into public.notifications (
    user_id, organization_id, notification_type, title, body, entity_type, entity_id
  ) values (
    v_order.created_by, v_order.buyer_organization_id, 'ORDER_PROFORMA_ISSUED',
    'Proforma Invoice Issued',
    'A proforma invoice has been generated for order ' || v_order.order_code,
    'orders', p_order_id
  );

  v_result := jsonb_build_object(
    'order_id', p_order_id,
    'order_code', v_order.order_code,
    'proforma_id', v_proforma_id,
    'proforma_code', v_proforma_code,
    'payment_id', v_payment_id,
    'reservation_id', v_reservation_id,
    'expires_at', v_expires_at,
    'buyer_total', v_buyer_total,
    'currency', 'USD'
  );

  perform public.commerce_request_complete(p_request_id, v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_orphan_payment_proof_upload(p_upload_intent_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_intent public.payment_proof_upload_intents%rowtype;
begin
  select * into v_intent
  from public.payment_proof_upload_intents
  where id = p_upload_intent_id for update;

  if not found then
    return false;
  end if;

  if v_intent.status = 'FINALIZED' then
    return false;
  end if;

  if public.is_platform_admin() or public.is_finance_operator() then
    -- Admin / Finance operator authorized
    null;
  elsif v_intent.prepared_by = auth.uid()
        and public.is_authorized_member()
        and public.is_org_member(v_intent.buyer_organization_id)
        and public.organization_can_buy(v_intent.buyer_organization_id)
        and not public.is_blocked_user()
        and public.mfa_satisfied() then
    -- Authenticated intent owner authorized
    null;
  else
    return false;
  end if;

  delete from storage.objects
  where bucket_id = 'payment-proofs' and name = v_intent.object_path;

  update public.payment_proof_upload_intents
  set status = 'CLEANED', cleaned_at = clock_timestamp()
  where id = p_upload_intent_id;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.commerce_assert_buyer_member(p_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  if auth.uid() is null or p_org_id is null or not public.is_org_member(p_org_id) or public.is_blocked_user()
     or not public.organization_can_buy(p_org_id) then
    raise exception 'buyer_not_authorized';
  end if;
  if not public.mfa_satisfied() then
    raise exception 'mfa_step_up_required';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.commerce_notify_order_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_title text;
  v_body text;
  v_type text;
begin
  if new.status is not distinct from old.status or new.commerce_flow is distinct from 'BANK_TRANSFER_V1' then
    return new;
  end if;

  if new.status = 'PROFORMA_ISSUED' then
    v_type := 'ORDER_PROFORMA_ISSUED';
    v_title := 'Proforma Invoice Issued';
    v_body := 'A proforma invoice has been generated for order ' || new.order_code;
  elsif new.status = 'HOLD' then
    v_type := 'RESERVATION_CONFIRMED';
    v_title := 'Stock Reservation Confirmed';
    v_body := 'Inventory reserved for 20 minutes for order ' || new.order_code;
  elsif new.status = 'EXPIRED' then
    v_type := 'RESERVATION_EXPIRED';
    v_title := 'Stock Reservation Expired';
    v_body := 'The reservation window for order ' || new.order_code || ' has expired';
  elsif new.status = 'PAYMENT_PROOF_SUBMITTED' then
    v_type := 'PAYMENT_PROOF_SUBMITTED';
    v_title := 'Payment Proof Submitted';
    v_body := 'Payment proof submitted for order ' || new.order_code;
  elsif new.status = 'PAID' then
    v_type := 'PAYMENT_CONFIRMED';
    v_title := 'Payment Confirmed';
    v_body := 'Payment confirmed for order ' || new.order_code;
  elsif new.status = 'PAYMENT_REJECTED' then
    v_type := 'PAYMENT_REJECTED';
    v_title := 'Payment Rejected';
    v_body := 'Payment review rejected for order ' || new.order_code;
  else
    return new;
  end if;

  insert into public.notifications(
    user_id,
    organization_id,
    notification_type,
    title,
    body,
    entity_type,
    entity_id
  ) select
    new.created_by,
    new.buyer_organization_id,
    v_type,
    v_title,
    v_body,
    'orders',
    new.id
  where not exists (
    select 1 from public.notifications n
    where n.user_id = new.created_by
      and n.notification_type = v_type
      and n.entity_type = 'orders'
      and n.entity_id = new.id
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.commerce_release_reservation(p_order_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_order public.orders%rowtype;
  v_reservation public.inventory_reservations%rowtype;
  v_item record;
begin
  select * into v_order from public.orders where id = p_order_id for update skip locked;
  if v_order.id is null or v_order.status <> 'HOLD' then
    return false;
  end if;

  select * into v_reservation from public.inventory_reservations
  where order_id = p_order_id and status = 'ACTIVE' for update;
  if v_reservation.id is null or v_reservation.expires_at > clock_timestamp() then
    return false;
  end if;

  -- Lock order matches data-model.md §8: offers ascending, then positions ascending. WRITE order is the reverse of
  -- the reservation's own increment (position mirror is the source of truth): positions decremented first, then
  -- offers — a listing's tradable remainder (quantity - filled - reserved) must never exceed the backing position's
  -- (available - reserved) even transiently, or the existing `listing_exceeds_tradable_inventory` guard trips.
  for v_item in
    select ri.offer_id from public.inventory_reservation_items ri where ri.reservation_id = v_reservation.id order by ri.offer_id
  loop
    perform 1 from public.coffee_offers where id = v_item.offer_id for update;
  end loop;
  for v_item in
    select ri.inventory_position_id from public.inventory_reservation_items ri
    where ri.reservation_id = v_reservation.id and ri.inventory_position_id is not null order by ri.inventory_position_id
  loop
    perform 1 from public.inventory_positions where id = v_item.inventory_position_id for update;
  end loop;

  for v_item in
    select ri.inventory_position_id, ri.quantity_kg
    from public.inventory_reservation_items ri
    where ri.reservation_id = v_reservation.id and ri.inventory_position_id is not null
    order by ri.inventory_position_id
  loop
    update public.inventory_positions set reserved_quantity_kg = reserved_quantity_kg - v_item.quantity_kg, updated_at = now()
    where id = v_item.inventory_position_id;
  end loop;

  for v_item in
    select ri.offer_id, ri.quantity_kg
    from public.inventory_reservation_items ri
    where ri.reservation_id = v_reservation.id
    order by ri.offer_id
  loop
    update public.coffee_offers set reserved_quantity_kg = reserved_quantity_kg - v_item.quantity_kg
    where id = v_item.offer_id;
  end loop;

  update public.inventory_reservations
  set status = 'EXPIRED', release_reason = 'EXPIRED', released_at = clock_timestamp()
  where id = v_reservation.id;

  perform set_config('app.internal_transition', 'true', true);
  update public.proforma_invoices set status = 'EXPIRED', expired_at = clock_timestamp()
  where id = v_reservation.proforma_id and status = 'CONFIRMED';
  update public.orders set status = 'EXPIRED' where id = p_order_id;
  perform set_config('app.internal_transition', 'false', true);

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.commerce_request_begin(p_request_id uuid, p_operation text, p_target_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_inserted integer;
  v_log public.commerce_request_log%rowtype;
begin
  if p_request_id is null then
    raise exception 'request_id_required';
  end if;
  insert into public.commerce_request_log (request_id, actor_user_id, operation, target_id, response)
  values (p_request_id, auth.uid(), p_operation, p_target_id, '{}'::jsonb)
  on conflict (request_id) do nothing;
  get diagnostics v_inserted = row_count;
  if v_inserted = 1 then
    -- a new request: every write below (and every trigger audit row) carries this correlation and reason
    perform set_config('app.correlation_id', p_request_id::text, true);
    perform set_config('app.transition_reason', p_operation, true);
    return null;
  end if;
  select * into v_log from public.commerce_request_log where request_id = p_request_id;
  if v_log.actor_user_id is distinct from auth.uid() or v_log.operation <> p_operation
     or v_log.target_id is distinct from p_target_id then
    raise exception 'request_id_conflict';
  end if;
  return v_log.response;
end;
$function$

CREATE OR REPLACE FUNCTION public.commerce_resolve_cart(p_org_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_order_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_org_id::text, 13));
  select o.id into v_order_id
  from public.orders o
  where o.buyer_organization_id = p_org_id and o.commerce_flow = 'BANK_TRANSFER_V1' and o.status = 'DRAFT'
  order by o.created_at desc, o.id desc
  limit 1;
  if v_order_id is null then
    if nullif(current_setting('app.correlation_id', true), '') is null then
      perform set_config('app.correlation_id', gen_random_uuid()::text, true);
    end if;
    perform set_config('app.transition_reason', coalesce(nullif(current_setting('app.transition_reason', true), ''), 'get_or_create_cart'), true);
    insert into public.orders (buyer_organization_id, created_by, status, commerce_flow)
    values (p_org_id, auth.uid(), 'DRAFT', 'BANK_TRANSFER_V1')
    returning id into v_order_id;
  end if;
  return v_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.compute_order_quote(p_order_id uuid, p_destination_id uuid, p_promo_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_order public.orders%rowtype;
  v_destination public.delivery_destinations%rowtype;
  v_tax public.tax_rules%rowtype;
  v_bank public.payment_accounts%rowtype;
  v_buyer public.organizations%rowtype;
  v_item record;
  v_group record;
  v_policy_id uuid;
  v_tier_id uuid;
  v_rate numeric;
  v_qualifying_quantity numeric;
  v_gross numeric;
  v_vat numeric;
  v_commission numeric;
  v_shipping public.shipping_rules%rowtype;
  v_lines jsonb := '[]'::jsonb;
  v_groups jsonb := '[]'::jsonb;
  v_destination_snapshot jsonb;
  v_amounts record;
  v_group_net numeric;
  v_group_shipping_vat numeric;
begin
  if nullif(btrim(p_promo_code), '') is not null then
    raise exception 'promotion_not_supported';
  end if;
  select * into v_order from public.orders where id = p_order_id;
  if not found or v_order.commerce_flow <> 'BANK_TRANSFER_V1' then
    raise exception 'order_not_found';
  end if;
  if v_order.currency <> 'USD' then raise exception 'currency_not_supported'; end if;
  if not exists (select 1 from public.order_items where order_id = p_order_id) then
    raise exception 'order_has_no_items';
  end if;
  select * into v_buyer from public.organizations where id = v_order.buyer_organization_id;

  if p_destination_id is not null then
    select * into v_destination from public.delivery_destinations
    where id = p_destination_id and organization_id = v_order.buyer_organization_id and retired_at is null;
    if not found then raise exception 'destination_not_found'; end if;
    -- No approved export/non-UAE treatment exists in the launch specification.
    if v_destination.country_code <> 'AE' then raise exception 'destination_tax_unsupported'; end if;
    select * into v_tax from public.tax_rules
    where country_code = 'AE' and tax_name = 'VAT' and is_active and effective_from <= statement_timestamp()
      and (effective_until is null or effective_until > statement_timestamp())
    order by effective_from desc, id desc limit 1;
    if not found then raise exception 'tax_rule_missing'; end if;
    select * into v_bank from public.payment_accounts
    where currency = 'USD' and is_active and is_default_for_currency
    order by id limit 1;
    if not found or (v_bank.account_number is null and v_bank.iban is null) then
      raise exception 'bank_account_missing';
    end if;
    v_destination_snapshot := jsonb_build_object(
      'label', v_destination.label, 'country_code', v_destination.country_code,
      'city', v_destination.city,
      'address_lines', case when v_destination.address_line_2 is null
        then jsonb_build_array(v_destination.address_line_1)
        else jsonb_build_array(v_destination.address_line_1, v_destination.address_line_2) end,
      'contact_name', v_destination.contact_name, 'contact_phone', v_destination.contact_phone,
      'delivery_method', v_destination.delivery_method);
  end if;

  for v_item in
    select oi.id as order_item_id, oi.quantity_kg, oi.product_name_snapshot,
           oi.origin_name_snapshot, oi.lot_code_snapshot,
           o.id as offer_id, o.offer_code, o.seller_organization_id,
           o.seller_type, o.warehouse_id, o.price_per_kg, o.currency,
           o.status, o.is_visible, o.deleted_at, o.quantity_kg as offer_quantity,
           o.filled_quantity_kg as offer_filled, o.reserved_quantity_kg as offer_reserved
    from public.order_items oi
    join public.coffee_offers o on o.id = oi.offer_id
    where oi.order_id = p_order_id
    order by oi.id
  loop
    if v_item.status not in ('PUBLISHED', 'PARTIALLY_FILLED') or not v_item.is_visible
       or v_item.deleted_at is not null or v_item.warehouse_id is null then
      raise exception 'listing_is_not_available';
    end if;
    if v_item.seller_type = 'MEMBER_SELLER'
       and not public.organization_can_sell(v_item.seller_organization_id) then
      raise exception 'listing_is_not_available';
    end if;
    if v_item.currency <> 'USD' then raise exception 'currency_not_supported'; end if;
    if v_item.seller_organization_id = v_order.buyer_organization_id then
      raise exception 'cannot_buy_own_listing';
    end if;
    if v_item.quantity_kg > v_item.offer_quantity - v_item.offer_filled - v_item.offer_reserved then
      raise exception 'requested_quantity_not_available';
    end if;

    v_policy_id := null; v_tier_id := null; v_rate := null; v_qualifying_quantity := null;
    if v_item.seller_type = 'MEMBER_SELLER' then
      select sum(oi2.quantity_kg) into v_qualifying_quantity
      from public.order_items oi2 join public.coffee_offers o2 on o2.id = oi2.offer_id
      where oi2.order_id = p_order_id and o2.seller_organization_id = v_item.seller_organization_id
        and o2.seller_type = 'MEMBER_SELLER';
      select p.id, t.id, t.percentage into v_policy_id, v_tier_id, v_rate
      from public.commission_policies p
      join public.commission_tiers t on t.policy_id = p.id
      where p.status = 'ACTIVE' and p.effective_from <= statement_timestamp()
        and (p.effective_until is null or p.effective_until > statement_timestamp())
        and t.min_quantity_kg <= v_qualifying_quantity
        and (t.max_quantity_kg is null or v_qualifying_quantity < t.max_quantity_kg)
      order by p.effective_from desc, t.min_quantity_kg desc, p.id desc, t.id desc
      limit 1;
      if not found then raise exception 'commission_rule_missing'; end if;
    end if;

    v_gross := round(v_item.quantity_kg * v_item.price_per_kg, 2);
    v_vat := case when p_destination_id is null then null
                  else round(v_gross * v_tax.rate_percentage / 100, 2) end;
    v_commission := case when v_item.seller_type = 'MEMBER_SELLER'
                         then round(v_gross * v_rate / 100, 2) else 0 end;
    if v_gross - v_commission < 0 then raise exception 'negative_economics'; end if;
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'order_item_id', v_item.order_item_id, 'offer_id', v_item.offer_id,
      'offer_code', v_item.offer_code, 'seller_id', v_item.seller_organization_id,
      'seller_type', v_item.seller_type, 'warehouse_id', v_item.warehouse_id,
      'quantity_kg', v_item.quantity_kg, 'unit_price', v_item.price_per_kg,
      'gross', v_gross, 'discount', 0, 'net', v_gross, 'vat', v_vat,
      'commission_policy_id', v_policy_id, 'commission_tier_id', v_tier_id,
      'commission_rate', v_rate, 'seller_qualifying_quantity_kg', v_qualifying_quantity,
      'commission', v_commission,
      'seller_net', case when v_item.seller_type = 'MEMBER_SELLER' then v_gross - v_commission else 0 end,
      'hills_share', case when v_item.seller_type = 'MEMBER_SELLER' then v_commission else v_gross end,
      'product_name', v_item.product_name_snapshot, 'origin_name', v_item.origin_name_snapshot,
      'lot_code', v_item.lot_code_snapshot));
  end loop;

  if p_destination_id is not null then
    for v_group in
      select distinct x.seller_id, x.warehouse_id
      from jsonb_to_recordset(v_lines) as x(seller_id uuid, warehouse_id uuid)
      order by x.seller_id, x.warehouse_id
    loop
      select * into v_shipping from public.shipping_rules
      where delivery_method = v_destination.delivery_method and currency = 'USD' and is_active
        and (country_code = v_destination.country_code or country_code is null)
        and effective_from <= statement_timestamp()
        and (effective_until is null or effective_until > statement_timestamp())
      -- R-8: exact country beats the NULL-country fallback (a bare comparison is NULL, and NULLs sort first under DESC).
      order by coalesce(country_code = v_destination.country_code, false) desc, effective_from desc, id desc
      limit 1;
      if not found then raise exception 'shipping_rule_missing'; end if;
      select coalesce(sum(x.net), 0) into v_group_net
      from jsonb_to_recordset(v_lines) as x(seller_id uuid, warehouse_id uuid, net numeric)
      where x.seller_id = v_group.seller_id and x.warehouse_id = v_group.warehouse_id;
      v_group_shipping_vat := case when v_tax.taxable_base = 'MERCHANDISE_AND_SHIPPING'
        then round(v_shipping.flat_fee * v_tax.rate_percentage / 100, 2) else 0 end;
      v_groups := v_groups || jsonb_build_array(jsonb_build_object(
        'seller_id', v_group.seller_id, 'warehouse_id', v_group.warehouse_id,
        'shipping_rule_id', v_shipping.id, 'delivery_method', v_destination.delivery_method,
        'shipping', round(v_shipping.flat_fee, 2), 'shipping_vat', v_group_shipping_vat,
        'merchandise_net', v_group_net));
    end loop;
  end if;

  select coalesce(sum(x.gross), 0) as gross, coalesce(sum(x.net), 0) as net,
         coalesce(sum(x.vat), 0) as line_vat,
         coalesce(sum(x.commission), 0) as commission,
         coalesce(sum(x.seller_net), 0) as seller_net,
         coalesce(sum(x.hills_share), 0) as hills_share,
         coalesce(sum(x.quantity_kg), 0) as quantity
  into v_amounts
  from jsonb_to_recordset(v_lines) as x(gross numeric, net numeric, vat numeric,
    commission numeric, seller_net numeric, hills_share numeric, quantity_kg numeric);

  return jsonb_build_object(
    'order_id', v_order.id, 'order_code', v_order.order_code,
    'buyer_snapshot', jsonb_build_object('legal_name', v_buyer.legal_name,
      'display_name', v_buyer.display_name, 'tax_number', v_buyer.tax_number,
      'country_code', v_buyer.country_code),
    'destination_snapshot', v_destination_snapshot,
    'tax_rule_id', v_tax.id, 'tax_rate', v_tax.rate_percentage, 'tax_base', v_tax.taxable_base,
    'bank_account_id', v_bank.id, 'bank_account_name', v_bank.account_name,
    'bank_name', v_bank.bank_name, 'bank_account_number', v_bank.account_number,
    'bank_iban', v_bank.iban, 'bank_swift', v_bank.swift_code,
    'lines', v_lines, 'groups', v_groups, 'merchandise_gross', v_amounts.gross,
    'discount_total', 0, 'merchandise_net', v_amounts.net,
    'shipping_total', case when p_destination_id is null then null else
      (select coalesce(sum(x.shipping), 0) from jsonb_to_recordset(v_groups) as x(shipping numeric)) end,
    'vat_total', case when p_destination_id is null then null else v_amounts.line_vat +
      (select coalesce(sum(x.shipping_vat), 0) from jsonb_to_recordset(v_groups) as x(shipping_vat numeric)) end,
    'buyer_total', case when p_destination_id is null then null else v_amounts.net +
      (select coalesce(sum(x.shipping + x.shipping_vat), 0)
       from jsonb_to_recordset(v_groups) as x(shipping numeric, shipping_vat numeric)) + v_amounts.line_vat end,
    'commission_total', v_amounts.commission, 'seller_net_total', v_amounts.seller_net,
    'hills_share_total', v_amounts.hills_share, 'total_quantity_kg', v_amounts.quantity);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_member_support_ticket(p_subject text, p_body text, p_priority text, p_order_id uuid, p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_ticket public.support_tickets%rowtype;
begin
  if auth.uid() is null or not public.is_authorized_member()
     or p_org_id is null or not public.is_org_member(p_org_id) then
    raise exception 'forbidden';
  end if;
  if length(btrim(p_subject)) not between 3 and 200
     or length(btrim(p_body)) not between 1 and 4000
     or p_priority not in ('LOW', 'NORMAL', 'HIGH', 'URGENT') then
    raise exception 'invalid_ticket_input';
  end if;
  insert into public.support_tickets
    (requester_user_id, requester_organization_id, subject, priority, order_id)
  values (auth.uid(), p_org_id, btrim(p_subject), p_priority, p_order_id)
  returning * into v_ticket;
  insert into public.support_messages (ticket_id, author_user_id, body)
  values (v_ticket.id, auth.uid(), btrim(p_body));
  return jsonb_build_object('ticket_id', v_ticket.id, 'ticket_code', v_ticket.ticket_code);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_support_ticket(p_subject text, p_body text, p_order_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_ticket public.support_tickets%rowtype;
  v_org_id uuid := p_organization_id;
begin
  if auth.uid() is null or public.is_blocked_user() then raise exception 'forbidden'; end if;

  if p_order_id is not null then
    if not public.can_view_order(p_order_id) then raise exception 'order_not_accessible'; end if;
    if v_org_id is null then
      select buyer_organization_id into v_org_id from public.orders where id = p_order_id;
    end if;
  end if;

  insert into public.support_tickets(
    requester_user_id, requester_organization_id, order_id, order_code_snapshot, subject
  )
  select auth.uid(), v_org_id, p_order_id, o.order_code, p_subject
  from public.orders o
  where o.id = p_order_id
  returning * into v_ticket;

  if not found then
    insert into public.support_tickets(
      requester_user_id, requester_organization_id, subject
    )
    values (auth.uid(), v_org_id, p_subject)
    returning * into v_ticket;
  end if;

  insert into public.support_messages(ticket_id, author_user_id, body)
  values (v_ticket.id, auth.uid(), p_body);

  return jsonb_build_object(
    'ticket_id', v_ticket.id,
    'ticket_code', v_ticket.ticket_code,
    'order_code', v_ticket.order_code_snapshot
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.emit_notification_event(p_event_type text, p_aggregate_type text, p_aggregate_id uuid, p_dedupe_key text, p_audience jsonb, p_template_key text, p_params jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_id uuid;
begin
  insert into public.notification_events (event_type, aggregate_type, aggregate_id, dedupe_key, audience, template_key, params)
  values (p_event_type, p_aggregate_type, p_aggregate_id, p_dedupe_key, p_audience, p_template_key, coalesce(p_params, '{}'::jsonb))
  on conflict (event_type, aggregate_id, dedupe_key) do nothing
  returning id into v_id;
  if v_id is null then
    select e.id into v_id from public.notification_events e
    where e.event_type = p_event_type and e.aggregate_id = p_aggregate_id and e.dedupe_key = p_dedupe_key;
  end if;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_new_order_flow()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if current_user <> 'service_role' then
    new.commerce_flow := 'BANK_TRANSFER_V1';
    new.has_manual_adjustment := false;
    new.cancelled_at := null;
    new.cancelled_by := null;
    new.cancel_reason := null;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.estimate_cart(p_order_id uuid, p_destination_id uuid DEFAULT NULL::uuid, p_promo_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_org_id uuid;
  v_quote jsonb;
  v_lines jsonb;
begin
  select buyer_organization_id into v_org_id from public.orders
  where id = p_order_id and commerce_flow = 'BANK_TRANSFER_V1' and status = 'DRAFT';
  if not found or not public.is_org_member(v_org_id) then raise exception 'order_not_found'; end if;
  perform public.commerce_assert_buyer_member(v_org_id);
  v_quote := public.compute_order_quote(p_order_id, p_destination_id, p_promo_code);
  select coalesce(jsonb_agg(jsonb_build_object(
    'offer_code', x.value -> 'offer_code', 'product_name', x.value -> 'product_name',
    'quantity_kg', x.value -> 'quantity_kg', 'unit_price', x.value -> 'unit_price',
    'gross', x.value -> 'gross', 'discount', x.value -> 'discount',
    'net', x.value -> 'net', 'vat', x.value -> 'vat') order by x.ordinality), '[]'::jsonb)
  into v_lines from jsonb_array_elements(v_quote -> 'lines') with ordinality as x(value, ordinality);
  return jsonb_build_object(
    'is_estimate', true, 'reason', case when p_destination_id is null then 'destination_required' else null end,
    'order_id', p_order_id, 'currency', 'USD', 'lines', v_lines,
    'groups', v_quote -> 'groups', 'merchandise_gross', v_quote -> 'merchandise_gross',
    'discount_total', v_quote -> 'discount_total', 'merchandise_net', v_quote -> 'merchandise_net',
    'shipping_total', v_quote -> 'shipping_total', 'vat_total', v_quote -> 'vat_total',
    'buyer_total', v_quote -> 'buyer_total');
end;
$function$

CREATE OR REPLACE FUNCTION public.expire_reservation(p_order_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_buyer_org uuid;
begin
  select buyer_organization_id into v_buyer_org from public.orders where id = p_order_id;
  if v_buyer_org is null then
    raise exception 'order_not_found';
  end if;
  if auth.role() <> 'service_role' and not (public.is_org_member(v_buyer_org) or public.is_platform_admin()) then
    raise exception 'order_not_found';
  end if;
  return public.commerce_release_reservation(p_order_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_payment_proof(p_order_id uuid, p_upload_intent_id uuid, p_customer_claimed_amount numeric, p_customer_transfer_date date, p_customer_bank_reference text, p_customer_reference_text text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_replay jsonb;
  v_order public.orders%rowtype;
  v_reservation public.inventory_reservations%rowtype;
  v_payment public.payments%rowtype;
  v_intent public.payment_proof_upload_intents%rowtype;
  v_storage_obj record;
  v_file_asset_id uuid;
  v_proof_id uuid;
  v_payment_id uuid;
  v_submitted_at timestamptz;
  v_reservation_status text;
  v_payment_status text;
  v_released boolean;
  v_result jsonb;
begin
  if p_request_id is null then
    raise exception 'request_id_required';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found or not public.is_org_member(v_order.buyer_organization_id) then
    raise exception 'order_not_found';
  end if;
  perform public.commerce_assert_buyer_member(v_order.buyer_organization_id);

  v_replay := public.commerce_request_begin(p_request_id, 'finalize_payment_proof', p_order_id);
  if v_replay is not null then
    return v_replay;
  end if;

  select * into v_intent from public.payment_proof_upload_intents
  where id = p_upload_intent_id and order_id = p_order_id for update;
  if not found or v_intent.buyer_organization_id <> v_order.buyer_organization_id then
    raise exception 'intent_not_found';
  end if;

  -- Replay handling: if intent is already finalized or order already PAYMENT_PROOF_SUBMITTED
  if v_intent.status = 'FINALIZED' or v_order.status = 'PAYMENT_PROOF_SUBMITTED' then
    select pp.id, pp.payment_id, pp.submitted_at into v_proof_id, v_payment_id, v_submitted_at
    from public.payment_proofs pp
    join public.payments p on p.id = pp.payment_id
    where p.order_id = p_order_id
      and (v_intent.finalized_proof_id is null or pp.id = v_intent.finalized_proof_id)
    order by pp.submitted_at desc, pp.created_at desc limit 1;

    select p.status into v_payment_status
    from public.payments p
    where p.id = v_payment_id and p.order_id = p_order_id;

    select r.status into v_reservation_status
    from public.inventory_reservations r
    where r.order_id = p_order_id
    order by r.created_at desc limit 1;

    -- Strict persisted entity integrity assertions (zero COALESCE fallbacks):
    if v_proof_id is null
       or v_payment_id is null
       or v_submitted_at is null
       or v_payment_status is null
       or v_payment_status <> 'PROOF_SUBMITTED'
       or v_reservation_status is null
       or v_reservation_status <> 'REVIEW_HOLD'
       or v_order.status <> 'PAYMENT_PROOF_SUBMITTED' then
      v_result := jsonb_build_object(
        'ok', false,
        'code', 'finalized_state_integrity_error'
      );
      perform public.commerce_request_complete(p_request_id, v_result);
      return v_result;
    end if;

    v_result := jsonb_build_object(
      'ok', true,
      'data', jsonb_build_object(
        'order_id', p_order_id,
        'order_code', v_order.order_code,
        'proof_id', v_proof_id,
        'payment_id', v_payment_id,
        'submitted_at', v_submitted_at,
        'order_status', v_order.status,
        'payment_status', v_payment_status,
        'reservation_status', v_reservation_status,
        'idempotent_replay', true
      )
    );
    perform public.commerce_request_complete(p_request_id, v_result);
    return v_result;
  end if;

  select * into v_payment from public.payments where order_id = p_order_id for update;
  if not found then
    raise exception 'payment_not_found';
  end if;

  select * into v_reservation from public.inventory_reservations
  where order_id = p_order_id and status = 'ACTIVE' for update;

  -- Authoritative deadline decision under lock:
  if v_reservation.id is null or v_reservation.expires_at <= clock_timestamp() then
    v_released := public.commerce_release_reservation(p_order_id);
    update public.payment_proof_upload_intents
    set status = 'EXPIRED'
    where id = p_upload_intent_id and status = 'PREPARED';

    v_result := jsonb_build_object(
      'ok', false,
      'code', 'reservation_expired',
      'released', coalesce(v_released, false)
    );
    perform public.commerce_request_complete(p_request_id, v_result);
    return v_result;
  end if;

  -- Timely finalize: verify exact storage object in payment-proofs bucket
  select * into v_storage_obj from storage.objects
  where bucket_id = 'payment-proofs' and name = v_intent.object_path;

  if v_storage_obj.id is null then
    v_result := jsonb_build_object('ok', false, 'code', 'storage_object_not_found');
    perform public.commerce_request_complete(p_request_id, v_result);
    return v_result;
  end if;

  -- Validate actual storage object metadata (HIGH 4)
  if coalesce((v_storage_obj.metadata->>'size')::bigint, 0) > 10485760
     or coalesce(v_storage_obj.metadata->>'mimetype', '') not in ('application/pdf', 'image/jpeg', 'image/png')
     or v_storage_obj.bucket_id <> 'payment-proofs' then
    v_result := jsonb_build_object('ok', false, 'code', 'metadata_invalid');
    perform public.commerce_request_complete(p_request_id, v_result);
    return v_result;
  end if;

  -- Insert private file_assets record
  insert into public.file_assets (
    uploaded_by, organization_id, bucket_name, object_path, original_name,
    mime_type, size_bytes, is_private
  ) values (
    auth.uid(), v_order.buyer_organization_id, 'payment-proofs', v_intent.object_path,
    coalesce(v_intent.display_filename, 'proof'),
    v_storage_obj.metadata->>'mimetype',
    (v_storage_obj.metadata->>'size')::bigint,
    true
  )
  on conflict (bucket_name, object_path) do update set
    size_bytes = excluded.size_bytes
  returning id into v_file_asset_id;

  -- Insert payment_proofs record
  insert into public.payment_proofs (
    payment_id, file_asset_id, reference_text, submitted_by,
    claimed_amount, claimed_currency, transfer_date, bank_reference,
    submitted_at, submission_kind, request_id, status
  ) values (
    v_payment.id, v_file_asset_id, p_customer_reference_text, auth.uid(),
    p_customer_claimed_amount, 'USD', p_customer_transfer_date,
    p_customer_bank_reference, clock_timestamp(), 'ON_TIME', p_request_id, 'SUBMITTED'
  )
  returning id, submitted_at into v_proof_id, v_submitted_at;

  -- Update intent to FINALIZED
  update public.payment_proof_upload_intents
  set status = 'FINALIZED', finalized_proof_id = v_proof_id, finalized_at = clock_timestamp()
  where id = p_upload_intent_id;

  -- Transition reservation to REVIEW_HOLD (protects against sweeper release)
  update public.inventory_reservations
  set status = 'REVIEW_HOLD'
  where id = v_reservation.id;

  -- Transition payment to PROOF_SUBMITTED
  update public.payments
  set status = 'PROOF_SUBMITTED', updated_at = clock_timestamp()
  where id = v_payment.id;

  -- Transition order to PAYMENT_PROOF_SUBMITTED
  perform set_config('app.internal_transition', 'true', true);
  update public.orders
  set status = 'PAYMENT_PROOF_SUBMITTED', updated_at = clock_timestamp()
  where id = p_order_id;
  perform set_config('app.internal_transition', 'false', true);

  v_result := jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'order_id', p_order_id,
      'order_code', v_order.order_code,
      'proof_id', v_proof_id,
      'payment_id', v_payment.id,
      'submitted_at', v_submitted_at,
      'order_status', 'PAYMENT_PROOF_SUBMITTED',
      'payment_status', 'PROOF_SUBMITTED',
      'reservation_status', 'REVIEW_HOLD'
    )
  );

  perform public.commerce_request_complete(p_request_id, v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_review_bank_transfer_v1(p_order_id uuid, p_payment_id uuid, p_decision text, p_notes text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_request_id uuid;
  v_review_id uuid;
  v_existing_review public.payment_reviews%rowtype;
  v_original_review public.payment_reviews%rowtype;
  v_review_count integer;

  v_order public.orders%rowtype;
  v_payment public.payments%rowtype;
  v_reservation public.inventory_reservations%rowtype;
  v_proforma public.proforma_invoices%rowtype;
  v_intent public.payment_proof_upload_intents%rowtype;
  v_proof public.payment_proofs%rowtype;

  v_group record;
  v_group_count integer := 0;
  v_shipment_id uuid;
  v_shipment_ids uuid[] := array[]::uuid[];
  v_address_line text;
  v_invoice_number text;
  v_order_item_id uuid;

  v_iri record;
  v_seller_pos public.inventory_positions%rowtype;
  v_buyer_key text;
  v_buyer_keys text[] := array[]::text[];
  v_all_position_ids uuid[] := array[]::uuid[];
  v_lot_id uuid;
  v_wh_id uuid;
  v_loc_id uuid;

  v_expected_lines_count integer;
  v_actual_lines_count integer;
  v_expected_shipment_count integer;
  v_actual_shipment_count integer;
  v_tax_invoice record;

  v_result jsonb;
begin
  -- 1. Actor & authorization checks
  if auth.uid() is null then
    raise exception 'unauthenticated';
  end if;

  if public.is_blocked_user() then
    raise exception 'forbidden';
  end if;

  if not public.mfa_satisfied() then
    raise exception 'mfa_required';
  end if;

  if not (public.is_finance_operator() or public.is_platform_admin()) then
    raise exception 'forbidden';
  end if;

  if p_decision is null or p_decision not in ('CONFIRMED', 'REJECTED') then
    raise exception 'invalid_decision';
  end if;

  if p_decision = 'REJECTED' and nullif(trim(p_notes), '') is null then
    raise exception 'rejection_notes_required';
  end if;

  v_request_id := coalesce(p_request_id, gen_random_uuid());

  -- 2. Lock orders then payments in strict order
  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.id is null then
    raise exception 'order_not_found';
  end if;

  select * into v_payment from public.payments where id = p_payment_id for update;
  if v_payment.id is null then
    raise exception 'payment_not_found';
  end if;

  if v_payment.order_id <> v_order.id then
    raise exception 'proof_payment_mismatch';
  end if;

  if v_order.commerce_flow <> 'BANK_TRANSFER_V1' then
    raise exception 'invalid_commerce_flow';
  end if;

  -- 3. Replay-first inspection
  select * into v_existing_review from public.payment_reviews where request_id = v_request_id;

  -- Case A: Same request ID replay
  if v_existing_review.id is not null then
    if v_existing_review.payment_id <> p_payment_id
       or v_existing_review.decision <> p_decision
       or v_existing_review.reviewer_user_id <> auth.uid() then
      raise exception 'request_id_conflict';
    end if;

    if not public.finance_terminal_review_integrity(p_order_id, p_payment_id, p_decision) then
      raise exception 'persisted_review_integrity_error';
    end if;

    if p_decision = 'CONFIRMED' then
      -- Complete CONFIRMED persisted terminal validator
      if v_order.status <> 'PAID' or v_payment.status <> 'CONFIRMED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_reservation from public.inventory_reservations where order_id = p_order_id;
      if v_reservation.id is null or v_reservation.status <> 'CONSUMED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_intent from public.payment_proof_upload_intents where order_id = p_order_id and status = 'FINALIZED';
      if v_intent.id is null or v_intent.finalized_proof_id is null then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_proof from public.payment_proofs where id = v_intent.finalized_proof_id and payment_id = p_payment_id;
      if v_proof.id is null or v_proof.status <> 'ACCEPTED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_tax_invoice from public.tax_invoices where order_id = p_order_id and proforma_id = v_order.current_proforma_id;
      if v_tax_invoice.id is null then
        raise exception 'persisted_review_integrity_error';
      end if;

      select count(*) into v_expected_lines_count from public.inventory_reservation_items where reservation_id = v_reservation.id;
      select count(*) into v_actual_lines_count from public.inventory_ownership_events where correlation_id = p_order_id;
      if v_expected_lines_count = 0 or v_actual_lines_count < v_expected_lines_count then
        raise exception 'persisted_review_integrity_error';
      end if;

      select count(*) into v_expected_shipment_count from public.proforma_fulfillment_groups where proforma_id = v_order.current_proforma_id;
      select count(*), array_agg(id) into v_actual_shipment_count, v_shipment_ids from public.order_shipments where order_id = p_order_id and shipment_kind = 'FULFILLMENT' and status = 'REQUESTED';
      if v_expected_shipment_count = 0 or v_actual_shipment_count <> v_expected_shipment_count then
        raise exception 'persisted_review_integrity_error';
      end if;

      return jsonb_build_object(
        'orderId', v_order.id,
        'order_id', v_order.id,
        'orderCode', v_order.order_code,
        'order_code', v_order.order_code,
        'paymentId', v_payment.id,
        'payment_id', v_payment.id,
        'decision', 'CONFIRMED',
        'orderStatus', 'PAID',
        'order_status', 'PAID',
        'paymentStatus', 'CONFIRMED',
        'payment_status', 'CONFIRMED',
        'reservationStatus', 'CONSUMED',
        'reservation_status', 'CONSUMED',
        'taxInvoiceNumber', v_tax_invoice.invoice_number,
        'tax_invoice_number', v_tax_invoice.invoice_number,
        'shipmentIds', v_shipment_ids,
        'shipment_ids', v_shipment_ids,
        'confirmedAt', v_existing_review.created_at,
        'confirmed_at', v_existing_review.created_at,
        'requestId', v_request_id,
        'request_id', v_request_id
      );
    else
      -- Complete REJECTED persisted terminal validator
      if v_order.status <> 'PAYMENT_REJECTED' or v_payment.status <> 'REJECTED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_reservation from public.inventory_reservations where order_id = p_order_id;
      if v_reservation.id is null or v_reservation.status <> 'RELEASED' or v_reservation.release_reason <> 'REJECTED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_intent from public.payment_proof_upload_intents where order_id = p_order_id and status = 'FINALIZED';
      if v_intent.id is null or v_intent.finalized_proof_id is null then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_proof from public.payment_proofs where id = v_intent.finalized_proof_id and payment_id = p_payment_id;
      if v_proof.id is null or v_proof.status <> 'REJECTED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      if exists (select 1 from public.tax_invoices where order_id = p_order_id)
         or exists (select 1 from public.inventory_ownership_events where correlation_id = p_order_id)
         or exists (select 1 from public.order_shipments where order_id = p_order_id and shipment_kind = 'FULFILLMENT') then
        raise exception 'persisted_review_integrity_error';
      end if;

      return jsonb_build_object(
        'orderId', v_order.id,
        'order_id', v_order.id,
        'orderCode', v_order.order_code,
        'order_code', v_order.order_code,
        'paymentId', v_payment.id,
        'payment_id', v_payment.id,
        'decision', 'REJECTED',
        'orderStatus', 'PAYMENT_REJECTED',
        'order_status', 'PAYMENT_REJECTED',
        'paymentStatus', 'REJECTED',
        'payment_status', 'REJECTED',
        'reservationStatus', 'RELEASED',
        'reservation_status', 'RELEASED',
        'rejectedAt', v_existing_review.created_at,
        'rejected_at', v_existing_review.created_at,
        'requestId', v_request_id,
        'request_id', v_request_id
      );
    end if;
  end if;

  -- Case B: Different request ID on a terminal order
  if v_order.status in ('PAID', 'PAYMENT_REJECTED') then
    select count(*) into v_review_count from public.payment_reviews where payment_id = p_payment_id;
    if v_review_count <> 1 then
      raise exception 'persisted_review_integrity_error';
    end if;

    select * into v_original_review from public.payment_reviews where payment_id = p_payment_id order by created_at asc limit 1;
    if v_original_review.id is null then
      raise exception 'persisted_review_integrity_error';
    end if;

    if v_original_review.decision <> p_decision then
      raise exception 'order_already_finalized';
    end if;

    if not public.finance_terminal_review_integrity(p_order_id, p_payment_id, p_decision) then
      raise exception 'persisted_review_integrity_error';
    end if;

    if p_decision = 'CONFIRMED' then
      if v_order.status <> 'PAID' or v_payment.status <> 'CONFIRMED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_reservation from public.inventory_reservations where order_id = p_order_id;
      if v_reservation.id is null or v_reservation.status <> 'CONSUMED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_intent from public.payment_proof_upload_intents where order_id = p_order_id and status = 'FINALIZED';
      if v_intent.id is null or v_intent.finalized_proof_id is null then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_proof from public.payment_proofs where id = v_intent.finalized_proof_id and payment_id = p_payment_id;
      if v_proof.id is null or v_proof.status <> 'ACCEPTED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_tax_invoice from public.tax_invoices where order_id = p_order_id and proforma_id = v_order.current_proforma_id;
      if v_tax_invoice.id is null then
        raise exception 'persisted_review_integrity_error';
      end if;

      select count(*) into v_expected_lines_count from public.inventory_reservation_items where reservation_id = v_reservation.id;
      select count(*) into v_actual_lines_count from public.inventory_ownership_events where correlation_id = p_order_id;
      if v_expected_lines_count = 0 or v_actual_lines_count < v_expected_lines_count then
        raise exception 'persisted_review_integrity_error';
      end if;

      select count(*), array_agg(id) into v_actual_shipment_count, v_shipment_ids from public.order_shipments where order_id = p_order_id and shipment_kind = 'FULFILLMENT' and status = 'REQUESTED';
      select count(*) into v_expected_shipment_count from public.proforma_fulfillment_groups where proforma_id = v_order.current_proforma_id;
      if v_expected_shipment_count = 0 or v_actual_shipment_count <> v_expected_shipment_count then
        raise exception 'persisted_review_integrity_error';
      end if;

      return jsonb_build_object(
        'orderId', v_order.id,
        'order_id', v_order.id,
        'orderCode', v_order.order_code,
        'order_code', v_order.order_code,
        'paymentId', v_payment.id,
        'payment_id', v_payment.id,
        'decision', 'CONFIRMED',
        'orderStatus', 'PAID',
        'order_status', 'PAID',
        'paymentStatus', 'CONFIRMED',
        'payment_status', 'CONFIRMED',
        'reservationStatus', 'CONSUMED',
        'reservation_status', 'CONSUMED',
        'taxInvoiceNumber', v_tax_invoice.invoice_number,
        'tax_invoice_number', v_tax_invoice.invoice_number,
        'shipmentIds', v_shipment_ids,
        'shipment_ids', v_shipment_ids,
        'confirmedAt', v_original_review.created_at,
        'confirmed_at', v_original_review.created_at,
        'requestId', v_original_review.request_id,
        'request_id', v_original_review.request_id
      );
    else
      if v_order.status <> 'PAYMENT_REJECTED' or v_payment.status <> 'REJECTED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_reservation from public.inventory_reservations where order_id = p_order_id;
      if v_reservation.id is null or v_reservation.status <> 'RELEASED' or v_reservation.release_reason <> 'REJECTED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_intent from public.payment_proof_upload_intents where order_id = p_order_id and status = 'FINALIZED';
      if v_intent.id is null or v_intent.finalized_proof_id is null then
        raise exception 'persisted_review_integrity_error';
      end if;

      select * into v_proof from public.payment_proofs where id = v_intent.finalized_proof_id and payment_id = p_payment_id;
      if v_proof.id is null or v_proof.status <> 'REJECTED' then
        raise exception 'persisted_review_integrity_error';
      end if;

      if exists (select 1 from public.tax_invoices where order_id = p_order_id)
         or exists (select 1 from public.inventory_ownership_events where correlation_id = p_order_id)
         or exists (select 1 from public.order_shipments where order_id = p_order_id and shipment_kind = 'FULFILLMENT') then
        raise exception 'persisted_review_integrity_error';
      end if;

      return jsonb_build_object(
        'orderId', v_order.id,
        'order_id', v_order.id,
        'orderCode', v_order.order_code,
        'order_code', v_order.order_code,
        'paymentId', v_payment.id,
        'payment_id', v_payment.id,
        'decision', 'REJECTED',
        'orderStatus', 'PAYMENT_REJECTED',
        'order_status', 'PAYMENT_REJECTED',
        'paymentStatus', 'REJECTED',
        'payment_status', 'REJECTED',
        'reservationStatus', 'RELEASED',
        'reservation_status', 'RELEASED',
        'rejectedAt', v_original_review.created_at,
        'rejected_at', v_original_review.created_at,
        'requestId', v_original_review.request_id,
        'request_id', v_original_review.request_id
      );
    end if;
  end if;

  -- 4. Initial Mutation Path — Eligibility & Snapshot Assertions
  perform public.commerce_request_begin(v_request_id, 'finance_review_bank_transfer_v1', p_order_id);

  if v_order.status <> 'PAYMENT_PROOF_SUBMITTED' then
    raise exception 'reservation_not_review_hold';
  end if;

  if v_payment.status <> 'PROOF_SUBMITTED' then
    raise exception 'invalid_payment_status';
  end if;

  select * into v_reservation
  from public.inventory_reservations
  where order_id = p_order_id;

  if v_reservation.id is null then
    raise exception 'reservation_not_found';
  end if;

  if v_reservation.status <> 'REVIEW_HOLD' then
    raise exception 'reservation_not_review_hold';
  end if;

  -- Four-pointer equality check:
  -- payments.proforma_id = orders.current_proforma_id = inventory_reservations.proforma_id = proforma_invoices.id
  if v_payment.proforma_id is null
     or v_order.current_proforma_id is null
     or v_reservation.proforma_id is null
     or v_payment.proforma_id is distinct from v_order.current_proforma_id
     or v_payment.proforma_id is distinct from v_reservation.proforma_id then
    raise exception 'authoritative_proforma_mismatch';
  end if;

  select * into v_proforma
  from public.proforma_invoices
  where id = v_payment.proforma_id
    and order_id = p_order_id;

  if v_proforma.id is null then
    raise exception 'proforma_not_found';
  end if;

  if v_proforma.status <> 'CONFIRMED' then
    raise exception 'proforma_not_confirmed';
  end if;

  -- Exact upload intent and proof binding
  select * into v_intent
  from public.payment_proof_upload_intents
  where order_id = p_order_id
    and status = 'FINALIZED';

  if v_intent.id is null or v_intent.finalized_proof_id is null then
    raise exception 'finalized_upload_intent_not_found';
  end if;

  select * into v_proof
  from public.payment_proofs
  where id = v_intent.finalized_proof_id
    and payment_id = p_payment_id;

  if v_proof.id is null then
    raise exception 'finalized_proof_not_found';
  end if;

  if v_proof.status <> 'SUBMITTED' then
    raise exception 'proof_payment_mismatch';
  end if;

  -- 5. Set transaction-local transition context BEFORE first business write
  perform set_config('app.internal_transition', 'true', true);

  if p_decision = 'CONFIRMED' then
    -- Exact proof mutation: status = 'ACCEPTED' (no updated_at column on payment_proofs)
    update public.payment_proofs
    set status = 'ACCEPTED'
    where id = v_intent.finalized_proof_id;

    -- Payment review record
    insert into public.payment_reviews (
      payment_id, reviewer_user_id, decision, reason, request_id, created_at
    ) values (
      p_payment_id, auth.uid(), 'CONFIRMED', p_notes, v_request_id, clock_timestamp()
    ) returning id into v_review_id;

    -- Inventory Reservation Consumed
    update public.inventory_reservations
    set status = 'CONSUMED', consumed_at = clock_timestamp()
    where id = v_reservation.id;

    -- Inventory conservation and locking protocol
    -- Derive all distinct buyer keys and lock them in sorted order
    -- Deduplicate logical buyer keys first, then order by expressions available to the outer query.
    -- This is valid PostgreSQL and preserves NULL-location serialization via the sentinel UUID.
    for v_iri in
      select buyer_keys.lot_id, buyer_keys.warehouse_id, buyer_keys.warehouse_location_id
      from (
        select distinct ip.lot_id, ip.warehouse_id, ip.warehouse_location_id
        from public.inventory_reservation_items iri
        join public.inventory_positions ip on ip.id = iri.inventory_position_id
        where iri.reservation_id = v_reservation.id
      ) as buyer_keys
      order by buyer_keys.lot_id, buyer_keys.warehouse_id,
        coalesce(buyer_keys.warehouse_location_id, '00000000-0000-0000-0000-000000000000'::uuid)
    loop
      v_buyer_key := format('%s:%s:%s:%s', v_iri.lot_id, v_order.buyer_organization_id, v_iri.warehouse_id, coalesce(v_iri.warehouse_location_id::text, '00000000-0000-0000-0000-000000000000'));
      perform pg_advisory_xact_lock(hashtext(v_buyer_key)::bigint);
    end loop;

    -- Compatible global hierarchy with checkout: lock all offers first, then inventory positions.
    perform 1
    from public.coffee_offers co
    join public.inventory_reservation_items iri on iri.offer_id = co.id
    where iri.reservation_id = v_reservation.id
    order by co.id asc
    for update;

    -- Collect all position IDs (source and existing buyer) and lock globally in ascending order
    select array_agg(id order by id asc) into v_all_position_ids
    from (
      select iri.inventory_position_id as id
      from public.inventory_reservation_items iri
      where iri.reservation_id = v_reservation.id
      union
      select bp.id
      from public.inventory_reservation_items iri
      join public.inventory_positions sp on sp.id = iri.inventory_position_id
      join public.inventory_positions bp
        on bp.lot_id = sp.lot_id
       and bp.owner_organization_id = v_order.buyer_organization_id
       and bp.warehouse_id = sp.warehouse_id
       and bp.warehouse_location_id is not distinct from sp.warehouse_location_id
      where iri.reservation_id = v_reservation.id
    ) pos_ids;

    if v_all_position_ids is not null and array_length(v_all_position_ids, 1) > 0 then
      perform id from public.inventory_positions where id = any(v_all_position_ids) order by id asc for update;
    end if;

    -- Mutate positions, record ownership events, and update offers
    for v_iri in
      select
        iri.offer_id,
        iri.inventory_position_id,
        iri.quantity_kg,
        pii.order_item_id,
        pii.seller_type_snapshot
      from public.inventory_reservation_items iri
      join public.proforma_invoice_items pii
        on pii.proforma_id = v_proforma.id
       and pii.offer_id = iri.offer_id
      where iri.reservation_id = v_reservation.id
      order by iri.offer_id
    loop
      select * into v_seller_pos from public.inventory_positions where id = v_iri.inventory_position_id for update;
      if v_seller_pos.id is null then
        raise exception 'seller_available_insufficient';
      end if;

      if v_seller_pos.available_quantity_kg < v_iri.quantity_kg then
        raise exception 'seller_available_insufficient';
      end if;

      if v_seller_pos.reserved_quantity_kg < v_iri.quantity_kg then
        raise exception 'seller_reserved_insufficient';
      end if;

      -- Seller position: available -= q, reserved -= q
      update public.inventory_positions
      set available_quantity_kg = available_quantity_kg - v_iri.quantity_kg,
          reserved_quantity_kg = reserved_quantity_kg - v_iri.quantity_kg,
          updated_at = clock_timestamp()
      where id = v_seller_pos.id;

      -- Buyer position: null-safe upsert available += q
      insert into public.inventory_positions (
        lot_id, owner_organization_id, warehouse_id, warehouse_location_id,
        available_quantity_kg, reserved_quantity_kg, updated_at
      ) values (
        v_seller_pos.lot_id, v_order.buyer_organization_id, v_seller_pos.warehouse_id, v_seller_pos.warehouse_location_id,
        v_iri.quantity_kg, 0, clock_timestamp()
      )
      on conflict (lot_id, owner_organization_id, warehouse_id, warehouse_location_id)
      do update set
        available_quantity_kg = public.inventory_positions.available_quantity_kg + excluded.available_quantity_kg,
        updated_at = clock_timestamp();

      -- Ownership title transfer event
      insert into public.inventory_ownership_events (
        lot_id, from_organization_id, to_organization_id, order_item_id,
        warehouse_id, warehouse_location_id, quantity_kg, event_type, created_by, correlation_id, reason
      ) values (
        v_seller_pos.lot_id,
        v_seller_pos.owner_organization_id,
        v_order.buyer_organization_id,
        v_iri.order_item_id,
        v_seller_pos.warehouse_id,
        v_seller_pos.warehouse_location_id,
        v_iri.quantity_kg,
        case when v_iri.seller_type_snapshot = 'HILLS' then 'SALE' else 'RESALE' end,
        auth.uid(),
        p_order_id,
        'FINANCE_CONFIRMATION'
      );

      -- Buyer custody must exist before Feature 009 delivery reservation can progress.
      insert into public.storage_allocations (
        order_item_id, owner_organization_id, lot_id, warehouse_id, warehouse_location_id,
        quantity_kg, released_quantity_kg, status
      ) values (
        v_iri.order_item_id, v_order.buyer_organization_id, v_seller_pos.lot_id,
        v_seller_pos.warehouse_id, v_seller_pos.warehouse_location_id,
        v_iri.quantity_kg, 0, 'STORED'
      ) on conflict do nothing;

      -- Preserve effective offer semantics: final consumption must leave no empty published listing.
      update public.coffee_offers
      set reserved_quantity_kg = reserved_quantity_kg - v_iri.quantity_kg,
          filled_quantity_kg = filled_quantity_kg + v_iri.quantity_kg,
          status = case
            when filled_quantity_kg + v_iri.quantity_kg >= quantity_kg then 'SOLD_OUT'
            else 'PARTIALLY_FILLED'
          end,
          is_visible = case
            when filled_quantity_kg + v_iri.quantity_kg >= quantity_kg then false
            else true
          end,
          updated_at = clock_timestamp()
      where id = v_iri.offer_id;
    end loop;

    -- Issue Final Tax Invoice
    v_invoice_number := public.next_tax_invoice_code();
    insert into public.tax_invoices (
      order_id, proforma_id, invoice_number, status, snapshot, issued_by, issued_at_ts
    ) values (
      p_order_id,
      v_proforma.id,
      v_invoice_number,
      'ISSUED',
      jsonb_build_object(
        'merchandise_gross', v_proforma.merchandise_gross,
        'discount_total', v_proforma.discount_total,
        'merchandise_net', v_proforma.merchandise_net,
        'shipping_total', v_proforma.shipping_total,
        'vat_total', v_proforma.vat_total,
        'buyer_total', v_proforma.buyer_total,
        'currency', v_proforma.currency,
        'destination_snapshot', v_proforma.destination_snapshot,
        'confirmed_at', clock_timestamp()
      ),
      auth.uid(),
      clock_timestamp()
    );

    -- Automatic Feature 009 FULFILLMENT Shipment Handoff (one per fulfillment group)
    for v_group in
      select * from public.proforma_fulfillment_groups
      where proforma_id = v_proforma.id
      order by id asc
    loop
      v_group_count := v_group_count + 1;

      v_address_line := array_to_string(ARRAY(
        select jsonb_array_elements_text(coalesce(v_proforma.destination_snapshot->'address_lines', '[]'::jsonb))
      ), ', ');
      if nullif(trim(v_address_line), '') is null then
        v_address_line := coalesce(v_proforma.destination_snapshot->>'address_line', 'Standard Delivery');
      end if;

      insert into public.order_shipments (
        order_id, status, shipment_kind, fulfillment_seller_organization_id,
        fulfillment_warehouse_id, proforma_fulfillment_group_id, delivery_method,
        country_code, city, address_line, contact_name, contact_phone,
        shipping_fee, currency, created_by
      ) values (
        p_order_id,
        'DRAFT',
        'FULFILLMENT',
        v_group.seller_organization_id,
        v_group.warehouse_id,
        v_group.id,
        v_group.delivery_method,
        coalesce(v_proforma.destination_snapshot->>'country_code', 'AE'),
        coalesce(v_proforma.destination_snapshot->>'city', 'Dubai'),
        v_address_line,
        coalesce(v_proforma.destination_snapshot->>'contact_name', 'Customer'),
        coalesce(v_proforma.destination_snapshot->>'contact_phone', '+9710000000'),
        v_group.shipping_amount,
        coalesce(v_proforma.currency, 'USD'),
        auth.uid()
      ) returning id into v_shipment_id;

      v_shipment_ids := array_append(v_shipment_ids, v_shipment_id);

      -- Line items strictly belonging to this fulfillment group
      insert into public.shipment_items (
        shipment_id, order_item_id, planned_quantity_kg, delivered_quantity_kg, reserved_quantity_kg
      )
      select v_shipment_id, pii.order_item_id, pii.quantity_kg, 0, 0
      from public.proforma_invoice_items pii
      where pii.proforma_id = v_proforma.id
        and pii.fulfillment_group_id = v_group.id;

      -- Transition FULFILLMENT shipment DRAFT -> REQUESTED
      update public.order_shipments
      set status = 'REQUESTED', updated_at = clock_timestamp()
      where id = v_shipment_id;
    end loop;

    -- Transition payment to CONFIRMED
    update public.payments
    set status = 'CONFIRMED',
        confirmed_by = auth.uid(),
        confirmed_at = clock_timestamp()
    where id = p_payment_id;

    -- Transition order to PAID
    update public.orders
    set status = 'PAID',
        paid_at = clock_timestamp()
    where id = p_order_id;

    -- Build return DTO
    v_result := jsonb_build_object(
      'orderId', v_order.id,
      'order_id', v_order.id,
      'orderCode', v_order.order_code,
      'order_code', v_order.order_code,
      'paymentId', v_payment.id,
      'payment_id', v_payment.id,
      'decision', 'CONFIRMED',
      'orderStatus', 'PAID',
      'order_status', 'PAID',
      'paymentStatus', 'CONFIRMED',
      'payment_status', 'CONFIRMED',
      'reservationStatus', 'CONSUMED',
      'reservation_status', 'CONSUMED',
      'taxInvoiceNumber', v_invoice_number,
      'tax_invoice_number', v_invoice_number,
      'shipmentIds', v_shipment_ids,
      'shipment_ids', v_shipment_ids,
      'confirmedAt', clock_timestamp(),
      'confirmed_at', clock_timestamp(),
      'requestId', v_request_id,
      'request_id', v_request_id
    );

  else
    -- REJECTED branch
    update public.payment_proofs
    set status = 'REJECTED'
    where id = v_intent.finalized_proof_id;

    insert into public.payment_reviews (
      payment_id, reviewer_user_id, decision, reason, request_id, created_at
    ) values (
      p_payment_id, auth.uid(), 'REJECTED', p_notes, v_request_id, clock_timestamp()
    ) returning id into v_review_id;

    -- Compatible global hierarchy with checkout: lock all offers before backing positions.
    perform 1
    from public.coffee_offers co
    join public.inventory_reservation_items iri on iri.offer_id = co.id
    where iri.reservation_id = v_reservation.id
    order by co.id asc
    for update;

    perform 1
    from public.inventory_positions ip
    join public.inventory_reservation_items iri on iri.inventory_position_id = ip.id
    where iri.reservation_id = v_reservation.id
    order by ip.id asc
    for update;

    -- Decrement backing positions before coffee offers
    for v_iri in
      select iri.offer_id, iri.inventory_position_id, iri.quantity_kg
      from public.inventory_reservation_items iri
      where iri.reservation_id = v_reservation.id
      order by iri.offer_id
    loop
      update public.inventory_positions
      set reserved_quantity_kg = reserved_quantity_kg - v_iri.quantity_kg,
          updated_at = clock_timestamp()
      where id = v_iri.inventory_position_id;

      update public.coffee_offers
      set reserved_quantity_kg = reserved_quantity_kg - v_iri.quantity_kg,
          updated_at = clock_timestamp()
      where id = v_iri.offer_id;
    end loop;

    update public.inventory_reservations
    set status = 'RELEASED',
        release_reason = 'REJECTED',
        released_at = clock_timestamp()
    where id = v_reservation.id;

    update public.payments
    set status = 'REJECTED',
        rejected_by = auth.uid(),
        rejected_at = clock_timestamp(),
        rejected_reason = p_notes
    where id = p_payment_id;

    update public.orders
    set status = 'PAYMENT_REJECTED'
    where id = p_order_id;

    v_result := jsonb_build_object(
      'orderId', v_order.id,
      'order_id', v_order.id,
      'orderCode', v_order.order_code,
      'order_code', v_order.order_code,
      'paymentId', v_payment.id,
      'payment_id', v_payment.id,
      'decision', 'REJECTED',
      'orderStatus', 'PAYMENT_REJECTED',
      'order_status', 'PAYMENT_REJECTED',
      'paymentStatus', 'REJECTED',
      'payment_status', 'REJECTED',
      'reservationStatus', 'RELEASED',
      'reservation_status', 'RELEASED',
      'rejectedAt', clock_timestamp(),
      'rejected_at', clock_timestamp(),
      'requestId', v_request_id,
      'request_id', v_request_id
    );
  end if;

  -- Approved live-suite failpoint is transaction-local and proves rollback before commit.
  if current_setting('app.f016_test_failpoint', true) = 'after_review_mutations' then
    raise exception 'f016_test_failpoint_after_review_mutations';
  end if;

  -- 6. Audit log write (T012)
  insert into public.audit_logs (
    actor_user_id, action, entity_type, entity_id, new_data
  ) values (
    auth.uid(),
    'FINANCE_PAYMENT_REVIEW',
    'orders',
    p_order_id,
    jsonb_build_object(
      'payment_id', p_payment_id,
      'decision', p_decision,
      'request_id', v_request_id,
      'notes', p_notes
    )
  );

  perform public.commerce_request_complete(v_request_id, v_result);

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_terminal_review_integrity(p_order_id uuid, p_payment_id uuid, p_decision text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare v_order public.orders%rowtype; v_payment public.payments%rowtype; v_res public.inventory_reservations%rowtype;
declare v_proforma public.proforma_invoices%rowtype; v_intent public.payment_proof_upload_intents%rowtype; v_proof public.payment_proofs%rowtype;
declare v_expected integer; v_actual integer;
begin
  select * into v_order from public.orders where id = p_order_id;
  select * into v_payment from public.payments where id = p_payment_id;
  select * into v_res from public.inventory_reservations where order_id = p_order_id;
  if v_order.id is null or v_payment.id is null or v_payment.order_id <> p_order_id or v_res.id is null
     or (select count(*) from public.inventory_reservations where order_id = p_order_id) <> 1 then return false; end if;
  if v_payment.proforma_id is null or v_payment.proforma_id is distinct from v_order.current_proforma_id
     or v_payment.proforma_id is distinct from v_res.proforma_id then return false; end if;
  select * into v_proforma from public.proforma_invoices where id = v_payment.proforma_id and order_id = p_order_id;
  if v_proforma.id is null or v_proforma.status <> 'CONFIRMED' then return false; end if;
  -- A terminal payment has exactly one authoritative review total, not merely one matching decision.
  select count(*) into v_actual from public.payment_reviews where payment_id = p_payment_id;
  if v_actual <> 1 then return false; end if;
  if not exists (select 1 from public.payment_reviews where payment_id = p_payment_id and decision = p_decision) then return false; end if;
  select * into v_intent from public.payment_proof_upload_intents where order_id = p_order_id and status = 'FINALIZED';
  if v_intent.id is null or v_intent.finalized_proof_id is null
     or (select count(*) from public.payment_proof_upload_intents where order_id = p_order_id and status = 'FINALIZED') <> 1 then return false; end if;
  select * into v_proof from public.payment_proofs where id = v_intent.finalized_proof_id and payment_id = p_payment_id;
  if v_proof.id is null or v_proof.status is distinct from (case when p_decision = 'CONFIRMED' then 'ACCEPTED' else 'REJECTED' end) then return false; end if;
  if p_decision = 'REJECTED' then
    return v_order.status = 'PAYMENT_REJECTED' and v_payment.status = 'REJECTED'
      and v_res.status = 'RELEASED' and v_res.release_reason = 'REJECTED'
      and not exists (select 1 from public.tax_invoices where order_id = p_order_id)
      and not exists (select 1 from public.inventory_ownership_events where correlation_id = p_order_id)
      and not exists (select 1 from public.storage_allocations sa join public.order_items oi on oi.id = sa.order_item_id where oi.order_id = p_order_id)
      and not exists (select 1 from public.order_shipments where order_id = p_order_id and shipment_kind = 'FULFILLMENT');
  end if;
  if v_order.status <> 'PAID' or v_payment.status <> 'CONFIRMED' or v_res.status <> 'CONSUMED' then return false; end if;
  select count(*) into v_actual from public.tax_invoices ti
    where ti.order_id = p_order_id and ti.proforma_id = v_proforma.id and ti.status = 'ISSUED'
      and (ti.snapshot->>'merchandise_gross')::numeric = v_proforma.merchandise_gross
      and (ti.snapshot->>'discount_total')::numeric = v_proforma.discount_total
      and (ti.snapshot->>'merchandise_net')::numeric = v_proforma.merchandise_net
      and (ti.snapshot->>'shipping_total')::numeric = v_proforma.shipping_total
      and (ti.snapshot->>'vat_total')::numeric = v_proforma.vat_total
      and (ti.snapshot->>'buyer_total')::numeric = v_proforma.buyer_total
      and ti.snapshot->>'currency' = v_proforma.currency
      and ti.snapshot->'destination_snapshot' = v_proforma.destination_snapshot;
  if v_actual <> 1 then return false; end if;
  select count(*) into v_expected from public.inventory_reservation_items where reservation_id = v_res.id;
  select count(*) into v_actual from public.inventory_ownership_events e
    join public.inventory_reservation_items iri on iri.reservation_id = v_res.id
    join public.proforma_invoice_items pii on pii.proforma_id = v_proforma.id and pii.offer_id = iri.offer_id
    join public.coffee_offers co on co.id = iri.offer_id
    where e.correlation_id = p_order_id and e.reason = 'FINANCE_CONFIRMATION'
      and e.order_item_id = pii.order_item_id and e.lot_id = co.lot_id
      and e.from_organization_id = co.seller_organization_id and e.to_organization_id = v_order.buyer_organization_id
      and e.event_type = case when pii.seller_type_snapshot = 'HILLS' then 'SALE' else 'RESALE' end
      and e.quantity_kg = iri.quantity_kg
      and exists (select 1 from public.inventory_positions sp where sp.id = iri.inventory_position_id
        and sp.lot_id = co.lot_id
        and e.warehouse_id = sp.warehouse_id
        and e.warehouse_location_id is not distinct from sp.warehouse_location_id);
  if v_expected = 0 or v_actual <> v_expected
     or (select count(*) from public.inventory_ownership_events where correlation_id = p_order_id and reason = 'FINANCE_CONFIRMATION') <> v_expected then return false; end if;
  select count(*) into v_actual from public.storage_allocations sa
    join public.inventory_reservation_items iri on iri.reservation_id = v_res.id
    join public.proforma_invoice_items pii on pii.proforma_id = v_proforma.id and pii.offer_id = iri.offer_id
    join public.inventory_positions ip on ip.id = iri.inventory_position_id
    where sa.order_item_id = pii.order_item_id and sa.owner_organization_id = v_order.buyer_organization_id
      and sa.lot_id = ip.lot_id and sa.warehouse_id = ip.warehouse_id and sa.warehouse_location_id is not distinct from ip.warehouse_location_id
      and sa.quantity_kg = iri.quantity_kg and sa.status = 'STORED';
  if v_actual <> v_expected then return false; end if;
  select count(*) into v_expected from public.proforma_fulfillment_groups where proforma_id = v_proforma.id;
  select count(*) into v_actual from public.order_shipments s join public.proforma_fulfillment_groups g on g.id = s.proforma_fulfillment_group_id
    where s.order_id = p_order_id and s.shipment_kind = 'FULFILLMENT' and s.status = 'REQUESTED'
      and g.proforma_id = v_proforma.id and s.fulfillment_seller_organization_id = g.seller_organization_id
      and s.fulfillment_warehouse_id = g.warehouse_id and s.delivery_method = g.delivery_method
      and s.shipping_fee = g.shipping_amount and s.currency = v_proforma.currency
      and s.country_code = coalesce(v_proforma.destination_snapshot->>'country_code', 'AE')::char(2)
      and s.city is not distinct from coalesce(v_proforma.destination_snapshot->>'city', 'Dubai')
      and s.address_line = coalesce(nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(v_proforma.destination_snapshot->'address_lines', '[]'::jsonb))), ', '), ''), v_proforma.destination_snapshot->>'address_line', 'Standard Delivery')
      and s.contact_name = coalesce(v_proforma.destination_snapshot->>'contact_name', 'Customer')
      and s.contact_phone = coalesce(v_proforma.destination_snapshot->>'contact_phone', '+9710000000');
  if v_expected = 0 or v_actual <> v_expected then return false; end if;
  if exists (select 1 from public.order_shipments s where s.order_id = p_order_id and s.shipment_kind = 'FULFILLMENT' and not exists (
    select 1 from public.proforma_fulfillment_groups g where g.id = s.proforma_fulfillment_group_id and g.proforma_id = v_proforma.id)) then return false; end if;
  if exists (select 1 from public.order_shipments s join public.proforma_fulfillment_groups g on g.id = s.proforma_fulfillment_group_id
    where s.order_id = p_order_id and s.shipment_kind = 'FULFILLMENT' and (
      (select count(*) from public.shipment_items si where si.shipment_id = s.id) <> (select count(*) from public.proforma_invoice_items pii where pii.proforma_id = v_proforma.id and pii.fulfillment_group_id = g.id)
      or exists (select 1 from public.shipment_items si where si.shipment_id = s.id and (not exists (select 1 from public.proforma_invoice_items pii where pii.proforma_id = v_proforma.id and pii.fulfillment_group_id = g.id and pii.order_item_id = si.order_item_id and pii.quantity_kg = si.planned_quantity_kg) or si.reserved_quantity_kg <> 0 or si.delivered_quantity_kg <> 0))
    )) then return false; end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.freeze_order_financials()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_order_id uuid;
  v_flow text;
  v_status text;
begin
  if tg_op = 'INSERT' then
    v_order_id := new.order_id;
  else
    v_order_id := old.order_id;
  end if;
  select o.commerce_flow, o.status into v_flow, v_status from public.orders o where o.id = v_order_id;
  if not found then
    -- The parent order is being deleted in this statement (cascade), or the order foreign key rejects the row.
    if tg_op = 'DELETE' and old.proforma_id is not null then
      raise exception 'order_financials_frozen' using detail = 'a Feature 013 financial summary is never deleted';
    end if;
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if v_flow = 'LEGACY' then
    if tg_op <> 'DELETE' and new.proforma_id is not null then
      raise exception 'order_financials_frozen' using detail = 'a LEGACY order''s financials cannot reference a Feature 013 proforma';
    end if;
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'order_financials_frozen' using detail = 'a BANK_TRANSFER_V1 financial summary is never deleted';
  end if;
  if v_status not in ('DRAFT', 'PROFORMA_ISSUED') then
    raise exception 'order_financials_frozen' using detail = 'the order has left PROFORMA_ISSUED (' || v_status || ')';
  end if;
  if not public.is_internal_transition() then
    raise exception 'order_financials_frozen' using detail = 'BANK_TRANSFER_V1 financials are written only by issue_proforma';
  end if;
  if new.proforma_id is null then
    raise exception 'order_financials_frozen' using detail = 'BANK_TRANSFER_V1 financials must reference the issued proforma';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_fulfillment_shipment_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'UPDATE' then
    if (new.shipment_kind, new.fulfillment_seller_organization_id, new.fulfillment_warehouse_id, new.proforma_fulfillment_group_id)
       is not distinct from (old.shipment_kind, old.fulfillment_seller_organization_id, old.fulfillment_warehouse_id, old.proforma_fulfillment_group_id) then
      return new;
    end if;
    raise exception 'order_field_not_client_writable' using detail = 'a shipment''s kind and fulfillment group never change';
  end if;
  if new.shipment_kind = 'DELIVERY_REQUEST' then
    return new;
  end if;
  if not public.is_internal_transition() then
    raise exception 'order_field_not_client_writable' using detail = 'FULFILLMENT shipments are created only by the settlement workflow';
  end if;
  if not exists (
    select 1
    from public.proforma_fulfillment_groups g
    join public.proforma_invoices p on p.id = g.proforma_id
    where g.id = new.proforma_fulfillment_group_id
      and p.order_id = new.order_id
      and g.seller_organization_id = new.fulfillment_seller_organization_id
      and g.warehouse_id = new.fulfillment_warehouse_id
  ) then
    raise exception 'fulfillment_group_mismatch' using detail = 'the shipment does not match a frozen fulfillment group of this order';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_offer_inventory_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  if tg_op = 'UPDATE' and (new.status = old.status or new.status not in ('PENDING_REVIEW', 'APPROVED', 'PUBLISHED')) then
    return new;
  end if;

  if exists (
    select 1
    from public.inventory_positions ip
    join public.inventory_open_cases h on h.inventory_position_id = ip.id
    where ip.lot_id = new.lot_id
      and ip.owner_organization_id = new.seller_organization_id
      and ip.warehouse_id = new.warehouse_id
      and ip.warehouse_location_id is not distinct from new.warehouse_location_id
  ) then
    raise exception 'inventory_position_held';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_order_destination_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if public.is_internal_transition() then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.delivery_destination_id is not null or new.destination_snapshot is not null then
      raise exception 'order_field_not_client_writable';
    end if;
  elsif (new.delivery_destination_id, new.destination_snapshot) is distinct from (old.delivery_destination_id, old.destination_snapshot) then
    raise exception 'order_field_not_client_writable';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_order_proforma_pointer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'UPDATE' and new.current_proforma_id is not distinct from old.current_proforma_id then
    return new;
  end if;
  if tg_op = 'INSERT' and new.current_proforma_id is null then
    return new;
  end if;
  if not public.is_internal_transition() then
    raise exception 'order_field_not_client_writable';
  end if;
  if new.current_proforma_id is not null and new.commerce_flow <> 'BANK_TRANSFER_V1' then
    raise exception 'order_field_not_client_writable' using detail = 'only a BANK_TRANSFER_V1 order points to a proforma';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_organization_compliance_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  -- Only a compliance operator who is NOT a platform admin is narrowed. Platform admins keep
  -- `organizations_admin_all`; the service role (no JWT) and definer maintenance are unaffected;
  -- members hold no UPDATE policy at all.
  if auth.uid() is null or public.is_platform_admin() or not public.is_compliance_operator() then
    return new;
  end if;

  -- No column other than `status` may change (`updated_at` is maintained by its own trigger).
  if (to_jsonb(new) - 'status' - 'updated_at') is distinct from (to_jsonb(old) - 'status' - 'updated_at') then
    raise exception 'organization_compliance_update_scope';
  end if;

  if new.status is distinct from old.status and not (
    (old.status = 'PENDING_KYB' and new.status in ('UNDER_REVIEW', 'ACTIVE', 'REJECTED'))
    or (old.status = 'UNDER_REVIEW' and new.status in ('ACTIVE', 'REJECTED'))
    or (old.status = 'ACTIVE' and new.status = 'SUSPENDED')
    or (old.status = 'SUSPENDED' and new.status = 'ACTIVE')
  ) then
    raise exception 'organization_compliance_transition_refused';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_reconciliation_case()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  -- the only columns a case may change after it is opened
  c_mutable constant text[] := array['status', 'resolution_type', 'resolution_note', 'linked_order_id', 'resolved_by', 'resolved_at'];
begin
  if tg_op = 'DELETE' then
    raise exception 'reconciliation_case_immutable' using detail = 'a reconciliation case is never deleted';
  end if;
  if not public.is_internal_transition() then
    raise exception 'reconciliation_case_immutable' using detail = 'reconciliation cases change only through the finance workflow';
  end if;
  if tg_op = 'INSERT' then
    if new.status <> 'OPEN' then
      raise exception 'reconciliation_case_invalid' using detail = 'a case is opened OPEN';
    end if;
    if not exists (select 1 from public.payments p where p.id = new.payment_id and p.order_id = new.order_id) then
      raise exception 'reconciliation_case_invalid' using detail = 'the payment does not belong to the order';
    end if;
    if new.proof_id is not null and not exists (select 1 from public.payment_proofs pp where pp.id = new.proof_id and pp.payment_id = new.payment_id) then
      raise exception 'reconciliation_case_invalid' using detail = 'the proof does not belong to the payment';
    end if;
    return new;
  end if;
  if (to_jsonb(new) - c_mutable) is distinct from (to_jsonb(old) - c_mutable) then
    raise exception 'reconciliation_case_immutable' using detail = 'identity and observed values are frozen once a case is opened';
  end if;
  if old.status in ('RESOLVED', 'CLOSED_NO_ACTION') then
    raise exception 'reconciliation_case_immutable' using detail = 'a closed case is final';
  end if;
  if new.status is distinct from old.status
     and not ((old.status = 'OPEN' and new.status in ('IN_REVIEW', 'CLOSED_NO_ACTION'))
              or (old.status = 'IN_REVIEW' and new.status in ('RESOLVED', 'CLOSED_NO_ACTION'))) then
    raise exception 'reconciliation_case_transition_invalid' using detail = old.status || ' -> ' || new.status;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ingest_stripe_event(p_provider text, p_external_event_id text, p_event_type text, p_payment_id uuid, p_payload jsonb, p_funding_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_payment public.payments%rowtype;
  v_event_id uuid;
  v_correlation uuid;
  v_deduped boolean := false;
begin
  if p_provider is null or btrim(p_provider) = '' then
    raise exception 'stripe_event_provider_required';
  end if;
  if p_external_event_id is null or btrim(p_external_event_id) = '' then
    raise exception 'stripe_event_id_required';
  end if;
  if p_event_type is null or btrim(p_event_type) = '' then
    raise exception 'stripe_event_type_required';
  end if;

  select * into v_payment from public.payments where id = p_payment_id for update;
  if v_payment.id is null then
    raise exception 'payment_not_found';
  end if;

  -- Anti-tamper / correlation check (STRIPE-PREPARATION.md §8: "never trust a client-side redirect...
  -- only a verified server-side event... may write funding evidence"). A forged event naming a real
  -- order id cannot mark a payment that never actually initiated Stripe funding (payments.provider is
  -- only ever set by record_stripe_payment_intent(), below) as funded.
  if v_payment.provider is distinct from p_provider then
    raise exception 'stripe_event_payment_provider_mismatch';
  end if;

  v_correlation := coalesce(v_payment.correlation_id, gen_random_uuid());

  -- Dedupe on event.id (never on a timestamp — Stripe does not guarantee delivery order and two events
  -- can share a `created` value). A duplicate/replayed delivery is a safe no-op, not an error.
  insert into public.payment_events (payment_id, provider, external_event_id, event_type, payload, correlation_id)
  values (p_payment_id, p_provider, p_external_event_id, p_event_type, p_payload, v_correlation)
  on conflict (provider, external_event_id) do nothing
  returning id into v_event_id;

  if v_event_id is null then
    v_deduped := true;
    select id into v_event_id from public.payment_events where provider = p_provider and external_event_id = p_external_event_id;
    return jsonb_build_object('deduped', true, 'event_id', v_event_id);
  end if;

  if p_funding_confirmed then
    -- coalesce: the FIRST confirming event wins. A later duplicate/out-of-order event can never move an
    -- already-confirmed timestamp or event pointer.
    update public.payments
    set
      trusted_funding_confirmed_at = coalesce(trusted_funding_confirmed_at, now()),
      trusted_funding_event_id = coalesce(trusted_funding_event_id, v_event_id)
    where id = p_payment_id;
  end if;

  return jsonb_build_object('deduped', v_deduped, 'event_id', v_event_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.kyb_storage_object_authorized(p_object_name text, p_require_editable boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_parts text[];
  v_org_id uuid;
  v_application_id uuid;
  v_app_status text;
  v_app_org_id uuid;
begin
  if auth.uid() is null then
    return false;
  end if;

  if public.is_blocked_user() then
    return false;
  end if;

  if public.is_platform_admin() or public.is_compliance_operator() then
    return true;
  end if;

  v_parts := string_to_array(p_object_name, '/');

  if array_length(v_parts, 1) is null
     or array_length(v_parts, 1) < 4
     or v_parts[1] <> 'org'
     or v_parts[3] <> 'application' then
    return false;
  end if;

  begin
    v_org_id := v_parts[2]::uuid;
    v_application_id := v_parts[4]::uuid;
  exception
    when others then
      return false;
  end;

  select organization_id, status into v_app_org_id, v_app_status
  from public.kyb_applications
  where id = v_application_id;

  if v_app_org_id is null or v_app_org_id <> v_org_id then
    return false;
  end if;

  if not public.is_org_member(v_org_id) then
    return false;
  end if;

  if p_require_editable and v_app_status not in ('DRAFT', 'RESUBMISSION_REQUIRED') then
    return false;
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_all_notifications_read()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_count integer := 0;
begin
  if auth.uid() is null then
    return 0;
  end if;

  with updated as (
    update public.notifications
    set read_at = clock_timestamp()
    where user_id = auth.uid()
      and read_at is null
    returning 1
  )
  select count(*)::integer into v_count from updated;

  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_notification_read(p_notification_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_updated boolean := false;
begin
  if auth.uid() is null then
    return false;
  end if;

  update public.notifications
  set read_at = coalesce(read_at, clock_timestamp())
  where id = p_notification_id
    and user_id = auth.uid()
    and read_at is null;

  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.offer_media_object_authorized(p_object_name text, p_require_editable boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_parts text[];
  v_offer_id uuid;
  v_seller_org uuid;
  v_status text;
  v_is_visible boolean;
  v_deleted_at timestamptz;
begin
  v_parts := string_to_array(p_object_name, '/');
  if array_length(v_parts, 1) is null or array_length(v_parts, 1) < 3 or v_parts[1] <> 'offers' then
    return false;
  end if;

  begin
    v_offer_id := v_parts[2]::uuid;
  exception
    when others then
      return false;
  end;

  select seller_organization_id, status, is_visible, deleted_at
  into v_seller_org, v_status, v_is_visible, v_deleted_at
  from public.coffee_offers where id = v_offer_id;

  if v_seller_org is null then
    return false;
  end if;

  if auth.uid() is null then
    return false;
  end if;
  if public.is_blocked_user() then
    return false;
  end if;
  if public.is_platform_admin() then
    return true;
  end if;

  -- "Member" read: the SAME audience coffee_offers' own member_read_published_offers policy already
  -- admits (is_authorized_member() AND is_visible) — never a wider grant than the underlying listing
  -- data itself has. A draft/suspended/deleted offer's images stay unreachable by anyone but its own
  -- seller org or an admin, even by direct Storage path guess.
  if not p_require_editable and public.is_authorized_member() and v_is_visible = true and v_deleted_at is null then
    return true;
  end if;

  if not public.is_org_member(v_seller_org) then
    return false;
  end if;

  if p_require_editable and v_status not in ('DRAFT', 'PENDING_REVIEW', 'APPROVED', 'PUBLISHED', 'PARTIALLY_FILLED') then
    return false;
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.payment_proof_storage_object_authorized(p_object_name text, p_for_write boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_intent public.payment_proof_upload_intents%rowtype;
  v_order public.orders%rowtype;
  v_reservation public.inventory_reservations%rowtype;
begin
  if auth.uid() is null then
    return false;
  end if;

  if public.is_blocked_user() then
    return false;
  end if;

  if not public.mfa_satisfied() then
    return false;
  end if;

  select * into v_intent
  from public.payment_proof_upload_intents
  where bucket_id = 'payment-proofs' and object_path = p_object_name;

  if v_intent.id is null then
    return false;
  end if;

  select * into v_order from public.orders where id = v_intent.order_id;
  if v_order.id is null then
    return false;
  end if;

  if p_for_write then
    if v_intent.status <> 'PREPARED' then
      return false;
    end if;
    if not (public.is_authorized_member() and public.is_org_member(v_intent.buyer_organization_id) and public.organization_can_buy(v_intent.buyer_organization_id)) then
      return false;
    end if;
    if v_order.status <> 'HOLD' then
      return false;
    end if;
    select * into v_reservation from public.inventory_reservations
    where order_id = v_intent.order_id and status = 'ACTIVE';
    if v_reservation.id is null or v_reservation.expires_at <= clock_timestamp() then
      return false;
    end if;
    return true;
  else
    if public.is_platform_admin() or public.is_finance_operator() then
      return true;
    end if;
    if public.is_authorized_member() and public.is_org_member(v_intent.buyer_organization_id) and public.organization_can_buy(v_intent.buyer_organization_id) then
      return true;
    end if;
    return false;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_payment_proof_upload(p_order_id uuid, p_request_id uuid, p_display_filename text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_replay jsonb;
  v_order public.orders%rowtype;
  v_reservation public.inventory_reservations%rowtype;
  v_existing_intent public.payment_proof_upload_intents%rowtype;
  v_intent_id uuid;
  v_canonical_path text;
  v_clean_filename text;
  v_result jsonb;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found or not public.is_org_member(v_order.buyer_organization_id) then
    raise exception 'order_not_found';
  end if;
  perform public.commerce_assert_buyer_member(v_order.buyer_organization_id);

  v_replay := public.commerce_request_begin(p_request_id, 'prepare_payment_proof_upload', p_order_id);
  if v_replay is not null then
    return v_replay;
  end if;

  if v_order.status <> 'HOLD' then
    raise exception 'order_not_editable';
  end if;

  select * into v_reservation from public.inventory_reservations
  where order_id = p_order_id and status = 'ACTIVE' for update;
  if v_reservation.id is null or v_reservation.expires_at <= clock_timestamp() then
    raise exception 'reservation_expired';
  end if;

  -- Replay existing PREPARED intent if still unexpired
  select * into v_existing_intent from public.payment_proof_upload_intents
  where order_id = p_order_id and status = 'PREPARED' and expires_at > clock_timestamp()
  order by created_at desc limit 1;

  if v_existing_intent.id is not null then
    v_result := jsonb_build_object(
      'intent_id', v_existing_intent.id,
      'bucket_id', v_existing_intent.bucket_id,
      'object_path', v_existing_intent.object_path,
      'display_filename', v_existing_intent.display_filename,
      'expires_at', v_existing_intent.expires_at,
      'max_size_bytes', 10485760,
      'allowed_mime_types', jsonb_build_array('application/pdf', 'image/jpeg', 'image/png')
    );
    perform public.commerce_request_complete(p_request_id, v_result);
    return v_result;
  end if;

  update public.payment_proof_upload_intents
  set status = 'EXPIRED'
  where order_id = p_order_id and status = 'PREPARED' and expires_at <= clock_timestamp();

  v_intent_id := gen_random_uuid();
  v_canonical_path := 'org/' || v_order.buyer_organization_id || '/orders/' || p_order_id || '/' || v_intent_id || '/proof';

  if p_display_filename is not null then
    v_clean_filename := substring(regexp_replace(p_display_filename, '[^a-zA-Z0-9._-]', '_', 'g') from 1 for 255);
  else
    v_clean_filename := 'proof';
  end if;

  insert into public.payment_proof_upload_intents (
    id, order_id, buyer_organization_id, prepared_by, bucket_id, object_path,
    display_filename, expires_at, status, prepare_request_id
  ) values (
    v_intent_id, p_order_id, v_order.buyer_organization_id, auth.uid(),
    'payment-proofs', v_canonical_path, v_clean_filename,
    v_reservation.expires_at, 'PREPARED', p_request_id
  );

  v_result := jsonb_build_object(
    'intent_id', v_intent_id,
    'bucket_id', 'payment-proofs',
    'object_path', v_canonical_path,
    'display_filename', v_clean_filename,
    'expires_at', v_reservation.expires_at,
    'max_size_bytes', 10485760,
    'allowed_mime_types', jsonb_build_array('application/pdf', 'image/jpeg', 'image/png')
  );

  perform public.commerce_request_complete(p_request_id, v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_dispute_status_history_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  if tg_op = 'INSERT' then
    -- Only public.transition_dispute() raises this transaction-local flag.
    if coalesce(current_setting('app.dispute_transition', true), 'false') <> 'true' then
      raise exception 'dispute_status_history_is_append_only';
    end if;
    return new;
  end if;

  -- The ONLY permitted delete: the FK cascade from deleting the parent dispute (nested inside the
  -- referential-action trigger, so depth > 1). A direct DELETE — by any role — is refused.
  if tg_op = 'DELETE' and pg_trigger_depth() > 1 then
    return old;
  end if;

  raise exception 'dispute_status_history_is_append_only';
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_inventory_variance_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  if tg_op = 'INSERT' then
    -- Only record_inventory_variance() / resolve_inventory_variance() raise this transaction-local flag.
    if coalesce(current_setting('app.inventory_variance_write', true), 'false') <> 'true' then
      raise exception 'inventory_variance_events_is_append_only';
    end if;
    return new;
  end if;

  -- UPDATE, DELETE and TRUNCATE are refused for every role, always (H2). The parent-position FK is ON DELETE RESTRICT,
  -- so there is no cascade path either: deleting a position that has case history fails at the foreign key.
  raise exception 'inventory_variance_events_is_append_only';
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_snapshot_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_table_name = 'proforma_invoice_items' and (to_jsonb(old) ->> 'seller_type_snapshot') is null then
    if tg_op = 'DELETE' then
      return old;
    end if;
    if (to_jsonb(new) ->> 'seller_type_snapshot') is null then
      return new;
    end if;
  end if;
  raise exception 'snapshot_immutable' using detail = tg_table_name || ' rows are append-only (' || tg_op || ' refused)';
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_notification_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  c_processing constant text[] := array['status', 'attempts', 'next_attempt_at', 'claimed_at', 'claimed_by', 'processed_at', 'last_error'];
begin
  if (to_jsonb(new) - c_processing) is distinct from (to_jsonb(old) - c_processing) then
    raise exception 'notification_event_immutable' using detail = 'an outbox event''s identity and content are frozen once queued';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_proforma_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_flow text;
  v_order_status text;
  v_prev public.proforma_invoices%rowtype;
  -- The only columns a Feature 013 row may change after insert.
  c_lifecycle constant text[] := array['status', 'confirmed_at', 'confirmed_by', 'expired_at', 'cancelled_at', 'voided_at', 'updated_at'];
  -- The pre-M2b columns, which legacy writers keep changing as before.
  c_legacy constant text[] := array['id', 'order_id', 'proforma_code', 'status', 'issued_at', 'valid_until', 'file_asset_id', 'updated_at'];
begin
  if tg_op = 'INSERT' then
    select o.commerce_flow, o.status into v_flow, v_order_status from public.orders o where o.id = new.order_id;
    if not found then
      return new; -- the order foreign key rejects the row
    end if;
    if v_flow = 'LEGACY' then
      if new.validity_hours_snapshot is not null then
        raise exception 'proforma_snapshot_invalid' using detail = 'a LEGACY order cannot hold a Feature 013 proforma';
      end if;
      return new;
    end if;
    if new.validity_hours_snapshot is null then
      raise exception 'proforma_snapshot_invalid' using detail = 'a BANK_TRANSFER_V1 proforma must carry the full snapshot marker';
    end if;
    if v_order_status not in ('DRAFT', 'PROFORMA_ISSUED') then
      raise exception 'proforma_snapshot_invalid' using detail = 'a proforma is issued only while the order is DRAFT or PROFORMA_ISSUED';
    end if;
    if new.status <> 'ISSUED' then
      raise exception 'proforma_snapshot_invalid' using detail = 'a Feature 013 proforma is inserted ISSUED';
    end if;
    if new.version > 1 then
      select * into v_prev from public.proforma_invoices where id = new.supersedes_proforma_id;
      if not found or v_prev.order_id <> new.order_id or v_prev.version <> new.version - 1
         or v_prev.status in ('ISSUED', 'CONFIRMED', 'PAID') then
        raise exception 'proforma_snapshot_invalid' using detail = 'a replacement supersedes the closed previous version of the same order';
      end if;
    end if;
    return new;
  end if;

  if old.validity_hours_snapshot is null then
    -- LEGACY row.
    if tg_op = 'DELETE' then
      return old;
    end if;
    if (to_jsonb(new) - c_legacy) is distinct from (to_jsonb(old) - c_legacy) then
      raise exception 'proforma_snapshot_immutable' using detail = 'the Feature 013 columns of a LEGACY proforma are fixed placeholders';
    end if;
    return new;
  end if;

  -- Feature 013 row.
  if tg_op = 'DELETE' then
    raise exception 'proforma_snapshot_immutable' using detail = 'a Feature 013 proforma is never deleted';
  end if;
  if (to_jsonb(new) - c_lifecycle) is distinct from (to_jsonb(old) - c_lifecycle) then
    raise exception 'proforma_snapshot_immutable' using detail = 'money, party and snapshot columns are frozen at issuance';
  end if;
  if new.status is distinct from old.status then
    if not public.is_internal_transition() then
      raise exception 'proforma_snapshot_immutable' using detail = 'proforma status changes only through the commerce workflow';
    end if;
    if not ((old.status = 'ISSUED' and new.status in ('CONFIRMED', 'EXPIRED', 'CANCELLED', 'VOID', 'SUPERSEDED'))
            or (old.status = 'CONFIRMED' and new.status in ('PAID', 'EXPIRED', 'CANCELLED', 'VOID'))) then
      raise exception 'proforma_transition_invalid' using detail = old.status || ' -> ' || new.status;
    end if;
  end if;
  -- Lifecycle stamps are written once, by their own transition.
  if (new.confirmed_at, new.confirmed_by) is distinct from (old.confirmed_at, old.confirmed_by)
     and not (old.confirmed_at is null and old.status = 'ISSUED' and new.status = 'CONFIRMED') then
    raise exception 'proforma_snapshot_immutable' using detail = 'confirmed_at/confirmed_by are set once, on ISSUED -> CONFIRMED';
  end if;
  if new.expired_at is distinct from old.expired_at and not (old.expired_at is null and new.status = 'EXPIRED') then
    raise exception 'proforma_snapshot_immutable' using detail = 'expired_at is set once, on -> EXPIRED';
  end if;
  if new.cancelled_at is distinct from old.cancelled_at and not (old.cancelled_at is null and new.status = 'CANCELLED') then
    raise exception 'proforma_snapshot_immutable' using detail = 'cancelled_at is set once, on -> CANCELLED';
  end if;
  if new.voided_at is distinct from old.voided_at and not (old.voided_at is null and new.status = 'VOID') then
    raise exception 'proforma_snapshot_immutable' using detail = 'voided_at is set once, on -> VOID';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_tax_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  c_feature_013 constant text[] := array['status', 'proforma_id', 'issued_by', 'issued_at_ts', 'snapshot'];
  c_mutable constant text[] := array['status', 'file_asset_id', 'uploaded_by'];
begin
  if tg_op = 'INSERT' then
    if new.proforma_id is not null and not public.is_internal_transition() then
      raise exception 'tax_invoice_immutable' using detail = 'a Feature 013 final invoice is issued only by the settlement workflow';
    end if;
    if new.proforma_id is not null and new.status <> 'ISSUED' then
      raise exception 'tax_invoice_invalid' using detail = 'a Feature 013 final invoice is issued ISSUED';
    end if;
    return new;
  end if;
  if old.proforma_id is null then
    -- LEGACY invoice.
    if tg_op = 'DELETE' then
      return old;
    end if;
    if (select jsonb_object_agg(k, to_jsonb(new) -> k) from unnest(c_feature_013) k)
       is distinct from (select jsonb_object_agg(k, to_jsonb(old) -> k) from unnest(c_feature_013) k) then
      raise exception 'tax_invoice_immutable' using detail = 'a LEGACY invoice cannot acquire Feature 013 values';
    end if;
    return new;
  end if;
  -- Feature 013 invoice.
  if tg_op = 'DELETE' then
    raise exception 'tax_invoice_immutable' using detail = 'a final invoice is never deleted';
  end if;
  if (to_jsonb(new) - c_mutable) is distinct from (to_jsonb(old) - c_mutable) then
    raise exception 'tax_invoice_immutable' using detail = 'a final invoice is frozen at issuance';
  end if;
  if not public.is_internal_transition() then
    raise exception 'tax_invoice_immutable' using detail = 'final invoices change only through the finance workflow';
  end if;
  if new.status is distinct from old.status and not (old.status = 'ISSUED' and new.status = 'VOID') then
    raise exception 'tax_invoice_transition_invalid' using detail = old.status || ' -> ' || new.status;
  end if;
  if (new.file_asset_id, new.uploaded_by) is distinct from (old.file_asset_id, old.uploaded_by) and old.file_asset_id is not null then
    raise exception 'tax_invoice_immutable' using detail = 'the signed file is attached once';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.public_asset_object_authorized(p_object_name text, p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_parts text[];
begin
  if p_operation = 'select' then
    return true;
  end if;

  if auth.uid() is null or public.is_blocked_user() then
    return false;
  end if;

  v_parts := string_to_array(p_object_name, '/');
  if array_length(v_parts, 1) is null or array_length(v_parts, 1) < 2 then
    return false;
  end if;

  if v_parts[1] = 'avatars' then
    return v_parts[2] = auth.uid()::text;
  end if;

  if v_parts[1] = 'branding' then
    return public.is_platform_admin();
  end if;

  -- catalogue/{coffee_id}/{file} — catalogue photography, platform admins only.
  if v_parts[1] = 'catalogue' then
    return array_length(v_parts, 1) >= 3 and public.is_platform_admin();
  end if;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_inventory_variance(p_position_id uuid, p_kind text, p_expected_available_quantity_kg numeric, p_counted_quantity_kg numeric, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_position public.inventory_positions%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_actor uuid := auth.uid();
  v_id uuid := gen_random_uuid();
  v_correlation uuid := gen_random_uuid();
  v_counted numeric;
  v_now timestamptz := now();
begin
  if not public.is_warehouse_operator() then
    raise exception 'forbidden';
  end if;
  if not public.mfa_satisfied() then
    raise exception 'mfa_step_up_required';
  end if;
  if p_kind is null or p_kind not in ('VARIANCE', 'HOLD', 'QUARANTINE') then
    raise exception 'variance_kind_invalid';
  end if;
  if char_length(v_reason) = 0 then
    raise exception 'variance_reason_required';
  end if;
  if char_length(v_reason) > 2000 then
    raise exception 'variance_reason_too_long';
  end if;
  if p_expected_available_quantity_kg is null or p_expected_available_quantity_kg < 0 then
    raise exception 'variance_quantity_invalid';
  end if;

  select * into v_position from public.inventory_positions where id = p_position_id for update;
  if v_position.id is null then
    raise exception 'variance_position_not_found';
  end if;

  -- Compare-and-set on the on-hand quantity the operator saw. Concurrent callers serialise on the row lock
  -- above; the loser re-reads the committed state here and is refused rather than recording against a stale one.
  if v_position.available_quantity_kg <> p_expected_available_quantity_kg then
    raise exception 'variance_stale_position';
  end if;

  if exists (select 1 from public.inventory_open_cases h where h.inventory_position_id = v_position.id) then
    raise exception 'variance_already_open';
  end if;

  if p_kind = 'VARIANCE' then
    if p_counted_quantity_kg is null or p_counted_quantity_kg < 0 then
      raise exception 'variance_quantity_invalid';
    end if;
    if p_counted_quantity_kg = v_position.available_quantity_kg then
      raise exception 'variance_quantity_zero';
    end if;
    v_counted := p_counted_quantity_kg;
  else
    if p_counted_quantity_kg is not null then
      raise exception 'variance_quantity_not_applicable';
    end if;
    v_counted := v_position.available_quantity_kg;
  end if;

  perform set_config('app.correlation_id', v_correlation::text, true);
  perform set_config('app.inventory_variance_write', 'true', true);

  insert into public.inventory_variance_events (
    id, event_type, variance_id, inventory_position_id, warehouse_id, kind,
    recorded_quantity_kg, counted_quantity_kg, reason, actor_user_id, correlation_id, created_at
  )
  values (
    v_id, 'RECORDED', v_id, v_position.id, v_position.warehouse_id, p_kind,
    v_position.available_quantity_kg, v_counted, v_reason, v_actor, v_correlation, v_now
  );

  perform set_config('app.inventory_variance_write', 'false', true);

  return jsonb_build_object(
    'variance_id', v_id,
    'inventory_position_id', v_position.id,
    'kind', p_kind,
    'recorded_quantity_kg', v_position.available_quantity_kg,
    'counted_quantity_kg', v_counted,
    'correlation_id', v_correlation,
    'recorded_at', v_now
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.record_payment_transfer(p_payout_id uuid, p_provider_transfer_id text, p_transfer_group text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_payout public.payouts%rowtype;
  v_payment public.payments%rowtype;
  v_id uuid;
begin
  if not public.is_finance_operator() then
    raise exception 'forbidden';
  end if;
  if p_provider_transfer_id is null or btrim(p_provider_transfer_id) = '' then
    raise exception 'stripe_transfer_id_required';
  end if;
  if p_transfer_group is null or btrim(p_transfer_group) = '' then
    raise exception 'stripe_transfer_group_required';
  end if;
  if p_idempotency_key is null or btrim(p_idempotency_key) = '' then
    raise exception 'stripe_idempotency_key_required';
  end if;

  select * into v_payout from public.payouts where id = p_payout_id for update;
  if v_payout.id is null then
    raise exception 'payout_not_found';
  end if;

  select * into v_payment from public.payments where order_id = v_payout.order_id;
  if v_payment.id is null then
    raise exception 'payment_not_found';
  end if;
  if v_payment.trusted_funding_confirmed_at is null then
    raise exception 'trusted_funding_required';
  end if;

  insert into public.payment_transfers (payment_id, payout_id, provider_transfer_id, transfer_group, idempotency_key)
  values (v_payment.id, p_payout_id, p_provider_transfer_id, p_transfer_group, p_idempotency_key)
  on conflict (payout_id) do nothing
  returning id into v_id;

  if v_id is null then
    -- Already recorded — a second transfer for the same payout is refused at the database level,
    -- whatever the caller does.
    select id into v_id from public.payment_transfers where payout_id = p_payout_id;
    return jsonb_build_object('payout_id', p_payout_id, 'transfer_id', v_id, 'already_recorded', true);
  end if;

  return jsonb_build_object('payout_id', p_payout_id, 'transfer_id', v_id, 'already_recorded', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_reconciliation_case_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then
    return null;
  end if;
  insert into public.reconciliation_case_events (case_id, from_status, to_status, note, actor_user_id)
  values (new.id, case when tg_op = 'UPDATE' then old.status end, new.status,
          nullif(btrim(current_setting('app.transition_reason', true)), ''), auth.uid());
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_stripe_payment_intent(p_order_id uuid, p_payment_intent_id text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_order public.orders%rowtype;
  v_payment public.payments%rowtype;
  v_updated int;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.id is null then
    raise exception 'order_not_found';
  end if;
  if not public.is_org_member(v_order.buyer_organization_id) then
    raise exception 'forbidden';
  end if;
  if v_order.status <> 'HOLD' then
    raise exception 'order_not_fundable';
  end if;
  if p_payment_intent_id is null or btrim(p_payment_intent_id) = '' then
    raise exception 'stripe_payment_intent_required';
  end if;
  if p_idempotency_key is null or btrim(p_idempotency_key) = '' then
    raise exception 'stripe_idempotency_key_required';
  end if;

  select * into v_payment from public.payments where order_id = p_order_id for update;
  if v_payment.id is null then
    raise exception 'payment_not_found';
  end if;

  -- Idempotent retry: the SAME PaymentIntent id being recorded again is a safe no-op.
  if v_payment.external_reference = p_payment_intent_id and v_payment.provider = 'STRIPE' then
    return jsonb_build_object('order_id', p_order_id, 'payment_id', v_payment.id, 'provider', 'STRIPE', 'external_reference', p_payment_intent_id, 'already_recorded', true);
  end if;

  -- Race/duplicate-create safety: a DIFFERENT PaymentIntent already recorded for this order is refused,
  -- never silently overwritten.
  if v_payment.external_reference is not null then
    raise exception 'stripe_payment_intent_already_recorded';
  end if;

  update public.payments
  set
    payment_method = 'PROVIDER',
    provider = 'STRIPE',
    external_reference = p_payment_intent_id,
    idempotency_key = p_idempotency_key
  where id = v_payment.id
    and external_reference is null;
  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    -- Lost the race to a concurrent caller; re-check rather than assume failure.
    select * into v_payment from public.payments where id = v_payment.id;
    if v_payment.external_reference = p_payment_intent_id then
      return jsonb_build_object('order_id', p_order_id, 'payment_id', v_payment.id, 'provider', 'STRIPE', 'external_reference', p_payment_intent_id, 'already_recorded', true);
    end if;
    raise exception 'stripe_payment_intent_already_recorded';
  end if;

  return jsonb_build_object('order_id', p_order_id, 'payment_id', v_payment.id, 'provider', 'STRIPE', 'external_reference', p_payment_intent_id, 'already_recorded', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_coffee_media(p_media_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_coffee_id uuid;
  v_file_asset_id uuid;
  v_was_primary boolean;
  v_bucket text;
  v_path text;
  v_next uuid;
begin
  if auth.uid() is null or public.is_blocked_user() or not public.is_platform_admin() then
    raise exception 'forbidden';
  end if;

  select m.coffee_id, m.file_asset_id, m.is_primary, fa.bucket_name, fa.object_path
  into v_coffee_id, v_file_asset_id, v_was_primary, v_bucket, v_path
  from public.coffee_media m
  join public.file_assets fa on fa.id = m.file_asset_id
  where m.id = p_media_id
  for update of m;

  if v_coffee_id is null then
    raise exception 'coffee_media_not_found';
  end if;

  delete from public.coffee_media where id = p_media_id;
  -- Only a public catalogue asset is removed with its record. A legacy file_assets row in any other
  -- bucket (e.g. a metadata-only fixture) is left untouched rather than orphaning some other owner.
  if v_bucket = 'public-assets' then
    delete from public.file_assets where id = v_file_asset_id
      and not exists (select 1 from public.coffee_media where file_asset_id = v_file_asset_id);
  end if;

  if v_was_primary then
    select id into v_next from public.coffee_media where coffee_id = v_coffee_id order by sort_order, created_at limit 1;
    if v_next is not null then
      update public.coffee_media set is_primary = true where id = v_next;
    end if;
  end if;

  return case when v_bucket = 'public-assets' then v_path else null end;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_my_avatar()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
