CREATE OR REPLACE FUNCTION public.remove_offer_media(p_media_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_offer_id uuid;
  v_seller_org uuid;
  v_status text;
  v_file_asset_id uuid;
  v_object_path text;
  v_was_primary boolean;
  v_next_id uuid;
begin
  if auth.uid() is null then
    raise exception 'forbidden';
  end if;
  if public.is_blocked_user() then
    raise exception 'forbidden';
  end if;

  select m.offer_id, m.file_asset_id, m.is_primary, o.seller_organization_id, o.status, fa.object_path
  into v_offer_id, v_file_asset_id, v_was_primary, v_seller_org, v_status, v_object_path
  from public.coffee_offer_media m
  join public.coffee_offers o on o.id = m.offer_id
  join public.file_assets fa on fa.id = m.file_asset_id
  where m.id = p_media_id
  for update of m;

  if v_offer_id is null then
    raise exception 'offer_media_not_found';
  end if;
  if not (public.is_platform_admin() or public.is_org_member(v_seller_org)) then
    raise exception 'forbidden';
  end if;
  if v_status not in ('DRAFT', 'PENDING_REVIEW', 'APPROVED', 'PUBLISHED', 'PARTIALLY_FILLED') then
    raise exception 'offer_media_not_editable';
  end if;

  delete from public.coffee_offer_media where id = p_media_id;
  delete from public.file_assets where id = v_file_asset_id;

  if v_was_primary then
    select id into v_next_id from public.coffee_offer_media
    where offer_id = v_offer_id order by sort_order asc limit 1;
    if v_next_id is not null then
      update public.coffee_offer_media set is_primary = true, updated_at = now() where id = v_next_id;
    end if;
  end if;

  return v_object_path;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_order_item(p_order_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_item public.order_items%rowtype;
  v_order public.orders%rowtype;
begin

  -- Non-enumerating resolution: the item is found ONLY if the caller is an active member of its
  -- order's buyer organization. A nonexistent id and another organization's id both raise the same
  -- 'order_item_not_found'; every more specific refusal below is shown only to that buyer.
  select oi.*
  into v_item
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  where oi.id = p_order_item_id
    and public.is_org_member(o.buyer_organization_id);

  if v_item.id is null then
    raise exception 'order_item_not_found';
  end if;

  -- Lock the parent order first — checkout_order()'s own lock order (order, then listing) — so an
  -- edit can never interleave with a concurrent confirm/checkout of the same order.
  select *
  into v_order
  from public.orders
  where id = v_item.order_id
  for update;

  if v_order.status <> 'DRAFT' then
    raise exception 'order_items_can_only_change_in_draft';
  end if;

  if not public.organization_can_buy(v_order.buyer_organization_id) then
    raise exception 'buyer_not_authorized';
  end if;

  -- A shipment plan that has left DRAFT (REQUESTED or any warehouse state) is closed to the buyer
  -- (validate_shipment_item); changing or removing an item it plans would silently break it.
  if exists (
    select 1
    from public.shipment_items si
    join public.order_shipments os on os.id = si.shipment_id
    where si.order_item_id = v_item.id
      and os.status not in ('DRAFT', 'CANCELLED', 'FAILED')
  ) then
    raise exception 'order_item_on_closed_shipment_plan';
  end if;

  -- shipment_items.order_item_id is ON DELETE CASCADE (verified by the guard): only DRAFT-shipment plan
  -- rows (checked above) can be removed with the item. A DRAFT order has no proforma/reservation rows.
  delete from public.order_items
  where id = v_item.id;
end;
$function$

