CREATE OR REPLACE FUNCTION public.reorder_offer_media(p_offer_id uuid, p_media_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_seller_org uuid;
  v_status text;
  v_existing_ids uuid[];
  v_i int;
begin
  if auth.uid() is null then
    raise exception 'forbidden';
  end if;
  if public.is_blocked_user() then
    raise exception 'forbidden';
  end if;

  select seller_organization_id, status into v_seller_org, v_status
  from public.coffee_offers where id = p_offer_id and deleted_at is null
  for update;

  if v_seller_org is null then
    raise exception 'offer_not_found';
  end if;
  if not (public.is_platform_admin() or public.is_org_member(v_seller_org)) then
    raise exception 'forbidden';
  end if;
  if v_status not in ('DRAFT', 'PENDING_REVIEW', 'APPROVED', 'PUBLISHED', 'PARTIALLY_FILLED') then
    raise exception 'offer_media_not_editable';
  end if;

  select array_agg(id order by id) into v_existing_ids from public.coffee_offer_media where offer_id = p_offer_id;
  if v_existing_ids is null or array_length(v_existing_ids, 1) <> array_length(p_media_ids, 1)
     or v_existing_ids <> (select array_agg(x order by x) from unnest(p_media_ids) x) then
    raise exception 'offer_media_reorder_set_mismatch';
  end if;

  for v_i in 1 .. array_length(p_media_ids, 1) loop
    update public.coffee_offer_media set sort_order = v_i - 1, updated_at = now() where id = p_media_ids[v_i];
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_ready_deliveries_for_settlement(p_order_id uuid, p_buyer_organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_shipment record;
  v_item record;
begin
  for v_shipment in
    select id
    from public.order_shipments
    where order_id = p_order_id
      and status = 'READY'
      and settlement_verified_at is null
    order by id
    for update
  loop
    for v_item in
      select si.id, si.order_item_id, si.planned_quantity_kg, si.delivered_quantity_kg, si.reserved_quantity_kg, oi.lot_id
      from public.shipment_items si
      join public.order_items oi on oi.id = si.order_item_id
      where si.shipment_id = v_shipment.id
      order by si.id
      for update of si
    loop
      if v_item.reserved_quantity_kg <> 0 then
        raise exception 'delivery_reservation_ledger_inconsistent';
      end if;
      if v_item.planned_quantity_kg > v_item.delivered_quantity_kg then
        perform public.apply_delivery_reservation(
          v_item.id, v_item.order_item_id, v_item.lot_id, p_buyer_organization_id, v_item.planned_quantity_kg
        );
      end if;
    end loop;

    -- Trusted settlement stamp: the ONLY UPDATE this function issues against order_shipments itself,
    -- guarded by the same transaction-local-marker pattern used for the child reservation column, so
    -- validate_shipment_transition's tamper-protection reset does not discard this trusted write.
    perform set_config('app.delivery_settlement_mutation', 'true', true);
    update public.order_shipments
    set settlement_verified_at = now()
    where id = v_shipment.id;
    perform set_config('app.delivery_settlement_mutation', 'false', true);
    if not found then
      raise exception 'delivery_reservation_ledger_inconsistent';
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_inventory_variance(p_variance_id uuid, p_outcome text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_case public.inventory_variance_events%rowtype;
  v_position public.inventory_positions%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_actor uuid := auth.uid();
  v_id uuid := gen_random_uuid();
  v_resolved numeric;
  v_now timestamptz := now();
begin
  if not public.is_warehouse_operator() then
    raise exception 'forbidden';
  end if;
  if not public.mfa_satisfied() then
    raise exception 'mfa_step_up_required';
  end if;
  if p_outcome is null or p_outcome not in ('RELEASED', 'ADJUSTED') then
    raise exception 'variance_outcome_invalid';
  end if;
  if char_length(v_reason) = 0 then
    raise exception 'variance_reason_required';
  end if;
  if char_length(v_reason) > 2000 then
    raise exception 'variance_reason_too_long';
  end if;

  select * into v_case from public.inventory_variance_events where id = p_variance_id and event_type = 'RECORDED';
  if v_case.id is null then
    raise exception 'variance_not_found';
  end if;

  -- Lock order matches the other inventory writers (position row). Concurrent resolvers serialise here.
  select * into v_position from public.inventory_positions where id = v_case.inventory_position_id for update;
  if v_position.id is null then
    raise exception 'variance_position_not_found';
  end if;

  if exists (select 1 from public.inventory_variance_events r where r.variance_id = v_case.id and r.event_type = 'RESOLVED') then
    raise exception 'variance_already_resolved';
  end if;

  -- The on-hand quantity is frozen while a case is open, so it must still be what was recorded.
  if v_position.available_quantity_kg <> v_case.recorded_quantity_kg then
    raise exception 'variance_stale_position';
  end if;

  perform set_config('app.correlation_id', v_case.correlation_id::text, true);

  if p_outcome = 'ADJUSTED' then
    if v_case.kind <> 'VARIANCE' then
      raise exception 'variance_adjustment_not_applicable';
    end if;
    -- Never adjust below what is already reserved (that would strand an active reservation).
    if v_case.counted_quantity_kg < v_position.reserved_quantity_kg then
      raise exception 'variance_adjustment_below_reserved';
    end if;

    v_resolved := v_case.counted_quantity_kg;

    perform set_config('app.inventory_variance_resolution', 'true', true);
    update public.inventory_positions
    set available_quantity_kg = v_resolved,
        updated_at = v_now
    where id = v_position.id;
    perform set_config('app.inventory_variance_resolution', 'false', true);

    -- LOT-03: every inventory change is an immutable ledger event. quantity_kg > 0 by constraint, so the
    -- direction is carried by the endpoints: a surplus enters from no organization; a shortage leaves the owner.
    insert into public.inventory_ownership_events (
      lot_id, from_organization_id, to_organization_id, order_item_id, quantity_kg, event_type, created_by, correlation_id, reason
    )
    values (
      v_position.lot_id,
      case when v_case.variance_quantity_kg < 0 then v_position.owner_organization_id else null end,
      v_position.owner_organization_id,
      null,
      abs(v_case.variance_quantity_kg),
      'ADJUSTMENT',
      v_actor,
      v_case.correlation_id,
      -- The ledger is member-visible (spec PS3), so it carries a fixed, member-safe reason — never the operator's free
      -- text, which stays in the case history (same correlation id) for warehouse operators and auditors (H3).
      'Warehouse stock count adjustment (' || case when v_case.variance_quantity_kg < 0 then 'shortage' else 'surplus' end || ', recorded ' || v_case.recorded_quantity_kg::text || ' kg, counted ' || v_case.counted_quantity_kg::text || ' kg)'
    );
  else
    v_resolved := v_position.available_quantity_kg;
  end if;

  perform set_config('app.inventory_variance_write', 'true', true);

  insert into public.inventory_variance_events (
    id, event_type, variance_id, inventory_position_id, warehouse_id, kind,
    recorded_quantity_kg, counted_quantity_kg, outcome, resolved_quantity_kg, reason, actor_user_id, correlation_id, created_at
  )
  values (
    v_id, 'RESOLVED', v_case.id, v_case.inventory_position_id, v_case.warehouse_id, v_case.kind,
    v_case.recorded_quantity_kg, v_case.counted_quantity_kg, p_outcome, v_resolved, v_reason, v_actor, v_case.correlation_id, v_now
  );

  perform set_config('app.inventory_variance_write', 'false', true);

  return jsonb_build_object(
    'variance_id', v_case.id,
    'resolution_id', v_id,
    'inventory_position_id', v_case.inventory_position_id,
    'outcome', p_outcome,
    'recorded_quantity_kg', v_case.recorded_quantity_kg,
    'resolved_quantity_kg', v_resolved,
    'correlation_id', v_case.correlation_id,
    'resolved_at', v_now
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.retire_delivery_destination(p_id uuid, p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare v_replay jsonb; v_destination public.delivery_destinations%rowtype;
begin
  -- Resolve only through the caller's current membership before the replay lookup, preserving non-enumeration.
  select d.* into v_destination from public.delivery_destinations d where d.id = p_id and public.is_org_member(d.organization_id) for update;
  if v_destination.id is null then raise exception 'destination_not_found'; end if;
  perform public.commerce_assert_buyer_member(v_destination.organization_id);
  v_replay := public.commerce_request_begin(p_request_id, 'retire_delivery_destination', p_id);
  if v_replay is not null then return; end if;
  if v_destination.retired_at is null then update public.delivery_destinations
    set retired_at = clock_timestamp(), retired_by = auth.uid(), is_default = false where id = p_id; end if;
  perform public.commerce_request_complete(p_request_id, jsonb_build_object('destination_id', p_id));
end;
$function$

CREATE OR REPLACE FUNCTION public.set_catalogue_translation(p_kind text, p_entity_id uuid, p_locale text, p_name text, p_description text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_description text := nullif(btrim(coalesce(p_description, '')), '');
begin
  if auth.uid() is null or public.is_blocked_user() or not public.is_platform_admin() then
    raise exception 'forbidden';
  end if;
  if p_locale is null or p_locale not in ('en', 'ar') then
    raise exception 'translation_locale_invalid';
  end if;
  if v_name is not null and char_length(v_name) > 200 then
    raise exception 'translation_name_too_long';
  end if;
  if v_description is not null and char_length(v_description) > 4000 then
    raise exception 'translation_description_too_long';
  end if;
  if v_description is not null and p_kind not in ('coffee', 'origin') then
    raise exception 'translation_description_not_applicable';
  end if;

  if p_kind = 'coffee' then
    if v_name is null then
      delete from public.coffee_translations where coffee_id = p_entity_id and locale = p_locale;
    else
      insert into public.coffee_translations (coffee_id, locale, name, description) values (p_entity_id, p_locale, v_name, v_description)
      on conflict (coffee_id, locale) do update set name = excluded.name, description = excluded.description;
    end if;
  elsif p_kind = 'origin' then
    if v_name is null then
      delete from public.origin_translations where origin_id = p_entity_id and locale = p_locale;
    else
      insert into public.origin_translations (origin_id, locale, name, description) values (p_entity_id, p_locale, v_name, v_description)
      on conflict (origin_id, locale) do update set name = excluded.name, description = excluded.description;
    end if;
  elsif p_kind = 'region' then
    if v_name is null then
      delete from public.region_translations where region_id = p_entity_id and locale = p_locale;
    else
      insert into public.region_translations (region_id, locale, name) values (p_entity_id, p_locale, v_name)
      on conflict (region_id, locale) do update set name = excluded.name;
    end if;
  elsif p_kind = 'coffee_type' then
    if v_name is null then
      delete from public.coffee_type_translations where coffee_type_id = p_entity_id and locale = p_locale;
    else
      insert into public.coffee_type_translations (coffee_type_id, locale, name) values (p_entity_id, p_locale, v_name)
      on conflict (coffee_type_id, locale) do update set name = excluded.name;
    end if;
  elsif p_kind = 'variety' then
    if v_name is null then
      delete from public.coffee_variety_translations where coffee_variety_id = p_entity_id and locale = p_locale;
    else
      insert into public.coffee_variety_translations (coffee_variety_id, locale, name) values (p_entity_id, p_locale, v_name)
      on conflict (coffee_variety_id, locale) do update set name = excluded.name;
    end if;
  elsif p_kind = 'processing' then
    if v_name is null then
      delete from public.processing_method_translations where processing_method_id = p_entity_id and locale = p_locale;
    else
      insert into public.processing_method_translations (processing_method_id, locale, name) values (p_entity_id, p_locale, v_name)
      on conflict (processing_method_id, locale) do update set name = excluded.name;
    end if;
  elsif p_kind = 'packaging' then
    if v_name is null then
      delete from public.packaging_type_translations where packaging_type_id = p_entity_id and locale = p_locale;
    else
      insert into public.packaging_type_translations (packaging_type_id, locale, name) values (p_entity_id, p_locale, v_name)
      on conflict (packaging_type_id, locale) do update set name = excluded.name;
    end if;
  elsif p_kind = 'tag' then
    if v_name is null then
      delete from public.tag_translations where tag_id = p_entity_id and locale = p_locale;
    else
      insert into public.tag_translations (tag_id, locale, name) values (p_entity_id, p_locale, v_name)
      on conflict (tag_id, locale) do update set name = excluded.name;
    end if;
  else
    raise exception 'translation_kind_invalid';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_default_payment_account(p_account_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare v_replay jsonb; v_account_id uuid; v_result jsonb;
begin
  if not public.is_platform_admin() then raise exception 'forbidden'; end if;
  if not public.mfa_satisfied() then raise exception 'mfa_step_up_required'; end if;
  v_replay := public.commerce_request_begin(p_request_id, 'set_default_payment_account', p_account_id);
  if v_replay is not null then return v_replay; end if;
  select a.id into v_account_id from public.payment_accounts a where a.id = p_account_id and a.is_active and a.currency = 'USD' for update;
  if v_account_id is null then raise exception 'payment_account_not_found'; end if;
  update public.payment_accounts set is_default_for_currency = false where currency = 'USD' and is_default_for_currency and id <> v_account_id;
  update public.payment_accounts set is_default_for_currency = true where id = v_account_id and not is_default_for_currency;
  v_result := jsonb_build_object('payment_account_id', v_account_id, 'currency', 'USD');
  perform public.commerce_request_complete(p_request_id, v_result); return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_avatar(p_object_path text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_old_path text;
  v_expected_prefix text := 'avatars/' || auth.uid()::text || '/';
begin
  if auth.uid() is null then
    raise exception 'forbidden';
  end if;
  if public.is_blocked_user() then
    raise exception 'forbidden';
  end if;
  if p_object_path is null or left(p_object_path, char_length(v_expected_prefix)) <> v_expected_prefix then
    raise exception 'avatar_object_path_invalid';
  end if;

  select avatar_path into v_old_path from public.profiles where id = auth.uid();

  update public.profiles set avatar_path = p_object_path, updated_at = now() where id = auth.uid();

  return v_old_path;
end;
$function$

