CREATE OR REPLACE FUNCTION public.submit_payment_proof(p_order_id uuid, p_file_asset_id uuid, p_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_payment_id uuid;
  v_flow text;
begin
  -- Inspect order commerce flow
  select o.commerce_flow into v_flow
  from public.orders o
  where o.id = p_order_id;

  -- FENCE: BANK_TRANSFER_V1 orders MUST use finalize_payment_proof.
  -- Fail closed immediately before any mutation, counter change, or transition.
  if v_flow = 'BANK_TRANSFER_V1' or (v_flow is not null and v_flow <> 'LEGACY') then
    raise exception 'endpoint_deprecated_use_finalize_payment_proof';
  end if;

  -- Documented legacy flow (commerce_flow = 'LEGACY') callers only:
  if not exists (
    select 1
    from public.orders o
    join public.organization_members om on om.organization_id = o.buyer_organization_id
    where o.id = p_order_id
      and om.user_id = auth.uid()
      and om.is_active
      and o.status in ('HOLD', 'PAYMENT_PROOF_SUBMITTED')
  ) then
    raise exception 'order_not_payable';
  end if;

  select id into v_payment_id
  from public.payments
  where order_id = p_order_id
  for update;

  insert into public.payment_proofs(payment_id, file_asset_id, reference_text, submitted_by)
  values (v_payment_id, p_file_asset_id, p_reference, auth.uid());

  update public.payments set status = 'UNDER_REVIEW' where id = v_payment_id;
  perform set_config('app.internal_transition', 'true', true);
  update public.orders set status = 'PAYMENT_UNDER_REVIEW' where id = p_order_id;
  return v_payment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.sweep_expired_reservations(p_limit integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_order_id uuid;
  v_released int := 0;
begin
  for v_order_id in
    select r.order_id from public.inventory_reservations r
    where r.status = 'ACTIVE' and r.expires_at <= clock_timestamp()
    order by r.expires_at
    limit greatest(p_limit, 0)
  loop
    if public.commerce_release_reservation(v_order_id) then
      v_released := v_released + 1;
    end if;
  end loop;
  return v_released;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_shipment_ready()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin

  if new.status in (
    'CAPACITY_CONFIRMED',
    'READY',
    'RESERVED'
  ) then

    new.ready_at :=
      coalesce(
        new.ready_at,
        now()
      );

    update public.orders
    set shipping_ready_at =
      coalesce(
        shipping_ready_at,
        now()
      )
    where id = new.order_id;

  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.t033_internal_attach_kyb_document(p_application_id uuid, p_document_type text, p_object_path text, p_original_name text, p_mime_type text, p_size_bytes bigint, p_expires_at date DEFAULT NULL::date, p_supersedes_document_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_organization_id uuid;
  v_status text;
  v_expected_prefix text;
  v_new_version integer;
  v_prev_application_id uuid;
  v_prev_document_type text;
  v_file_asset_id uuid;
  v_document_id uuid;
  v_storage_mime text;
  v_storage_size bigint;
  v_allowed_mime constant text[] := array['application/pdf', 'image/jpeg', 'image/png'];
  v_max_bytes constant bigint := 10485760;
begin
  if auth.uid() is null or public.is_blocked_user() then
    raise exception 'forbidden';
  end if;

  select organization_id, status into v_organization_id, v_status
  from public.kyb_applications
  where id = p_application_id;

  if v_organization_id is null then
    raise exception 'application_not_found';
  end if;

  if not public.is_org_member(v_organization_id) then
    raise exception 'forbidden';
  end if;

  if v_status not in ('DRAFT', 'RESUBMISSION_REQUIRED') then
    raise exception 'invalid_transition';
  end if;

  if p_mime_type is null or not (p_mime_type = any (v_allowed_mime)) then
    raise exception 'invalid_mime_type';
  end if;

  if p_size_bytes is null or p_size_bytes > v_max_bytes or p_size_bytes <= 0 then
    raise exception 'object_too_large';
  end if;

  v_expected_prefix := 'org/' || v_organization_id::text || '/application/' || p_application_id::text || '/';
  if p_object_path is null or left(p_object_path, length(v_expected_prefix)) <> v_expected_prefix then
    raise exception 'cross_organization_object_path';
  end if;

  -- REVIEW FIX #4 (storage object -> metadata integrity): refuse to create canonical metadata for
  -- an object that was never actually uploaded. `bucket_id`/`name` are core, version-independent
  -- `storage.objects` columns — safe to rely on unconditionally.
  if not exists (
    select 1 from storage.objects so
    where so.bucket_id = 'kyb-evidence'
      and so.name = p_object_path
  ) then
    raise exception 'storage_object_not_found';
  end if;

  -- Best-effort cross-check against the Storage object's own recorded metadata. Supabase Storage
  -- populates `storage.objects.metadata` with keys including `mimetype`/`size` at upload time —
  -- documented, stable Storage behaviour — but this repository has never introspected a live
  -- `storage.objects` row (zero buckets existed at the last schema audit, so
  -- `database-schema-report.json` has no `objects` column rows to confirm the exact key names
  -- against). This check is therefore deliberately tolerant: it rejects only when Storage-recorded
  -- metadata IS PRESENT and DISAGREES with the caller's claim, never when metadata is absent or
  -- differently shaped than expected. CONFIRMING THE EXACT `metadata` KEY NAMES AGAINST A REAL
  -- UPLOADED OBJECT IS A REQUIRED T010g LIVE-VERIFICATION STEP, not assumed here.
  select (so.metadata ->> 'mimetype'), nullif(so.metadata ->> 'size', '')::bigint
  into v_storage_mime, v_storage_size
  from storage.objects so
  where so.bucket_id = 'kyb-evidence'
    and so.name = p_object_path;

  if v_storage_mime is not null and v_storage_mime <> p_mime_type then
    raise exception 'mime_type_mismatch';
  end if;

  if v_storage_size is not null and v_storage_size <> p_size_bytes then
    raise exception 'size_mismatch';
  end if;

  v_new_version := 1;
  if p_supersedes_document_id is not null then
    select application_id, version, document_type
    into v_prev_application_id, v_new_version, v_prev_document_type
    from public.kyb_documents
    where id = p_supersedes_document_id;

    if v_prev_application_id is null then
      raise exception 'superseded_document_not_found';
    end if;

    if v_prev_application_id <> p_application_id then
      raise exception 'cross_application_document_replacement';
    end if;

    if v_prev_document_type <> p_document_type then
      raise exception 'cross_document_type_replacement';
    end if;

    v_new_version := v_new_version + 1;
  end if;

  insert into public.file_assets (
    uploaded_by, organization_id, bucket_name, object_path, original_name, mime_type, size_bytes, is_private
  )
  values (
    auth.uid(), v_organization_id, 'kyb-evidence', p_object_path, p_original_name, p_mime_type, p_size_bytes, true
  )
  returning id into v_file_asset_id;

  insert into public.kyb_documents (
    application_id, document_type, file_asset_id, expires_at, version, supersedes_document_id, status
  )
  values (
    p_application_id, p_document_type, v_file_asset_id, p_expires_at, v_new_version, p_supersedes_document_id, 'PENDING'
  )
  returning id into v_document_id;

  return v_document_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.t033_internal_create_kyb_draft(p_organization_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_application_id uuid;
begin
  if auth.uid() is null or public.is_blocked_user() then
    raise exception 'forbidden';
  end if;

  if not public.is_org_member(p_organization_id) then
    raise exception 'forbidden';
  end if;

  perform pg_advisory_xact_lock(hashtext(p_organization_id::text));

  select id into v_application_id
  from public.kyb_applications
  where organization_id = p_organization_id
    and status in ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'RESUBMISSION_REQUIRED')
  order by created_at desc
  limit 1;

  if v_application_id is not null then
    return v_application_id;
  end if;

  begin
    insert into public.kyb_applications (organization_id, submitted_by, status)
    values (p_organization_id, auth.uid(), 'DRAFT')
    returning id into v_application_id;
  exception
    when unique_violation then
      select id into v_application_id
      from public.kyb_applications
      where organization_id = p_organization_id
        and status in ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'RESUBMISSION_REQUIRED')
      order by created_at desc
      limit 1;
  end;

  return v_application_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.t033_internal_create_kyb_review(p_application_id uuid, p_document_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_review_id uuid;
begin
  if auth.uid() is null then
    raise exception 'forbidden';
  end if;

  if not public.is_compliance_operator() then
    raise exception 'forbidden';
  end if;

  if p_decision not in ('ACCEPTED', 'REJECTED') then
    raise exception 'invalid_decision';
  end if;

  if p_decision = 'REJECTED' and (p_reason is null or length(trim(p_reason)) = 0) then
    raise exception 'reason_required_for_rejection';
  end if;

  if not exists (
    select 1 from public.kyb_documents kd
    where kd.id = p_document_id
      and kd.application_id = p_application_id
  ) then
    raise exception 'review_item_document_application_mismatch';
  end if;

  insert into public.kyb_review_items (application_id, document_id, decision, reason, reviewer_user_id)
  values (p_application_id, p_document_id, p_decision, p_reason, auth.uid())
  returning id into v_review_id;

  return v_review_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.t033_internal_resubmit_kyb_application(p_application_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_organization_id uuid;
begin
  if auth.uid() is null or public.is_blocked_user() then
    raise exception 'forbidden';
  end if;

  select organization_id into v_organization_id
  from public.kyb_applications
  where id = p_application_id;

  if v_organization_id is null then
    raise exception 'application_not_found';
  end if;

  if not public.is_org_member(v_organization_id) then
    raise exception 'forbidden';
  end if;

  if exists (
    select 1 from public.kyb_documents
    where application_id = p_application_id
      and status = 'REJECTED'
  ) then
    raise exception 'unresolved_rejected_document';
  end if;

  perform public.transition_kyb_application(p_application_id, array['RESUBMISSION_REQUIRED']);
end;
$function$

CREATE OR REPLACE FUNCTION public.t033_internal_start_organization_onboarding(p_legal_name text, p_display_name text, p_account_type text, p_country_code text DEFAULT NULL::text, p_tax_number text DEFAULT NULL::text, p_registration_number text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_can_buy boolean;
  v_can_sell boolean;
  v_new_org_id uuid;
begin
  if auth.uid() is null then
    raise exception 'forbidden';
  end if;

  if public.is_blocked_user() then
    raise exception 'forbidden';
  end if;

  if not exists (
    select 1 from auth.users u
    where u.id = auth.uid()
      and u.email_confirmed_at is not null
  ) then
    raise exception 'email_not_verified';
  end if;

  if p_account_type not in ('BUYER', 'SELLER') then
    raise exception 'invalid_account_type';
  end if;

  if p_legal_name is null or length(trim(p_legal_name)) = 0 then
    raise exception 'legal_name_required';
  end if;

  if p_country_code is not null and length(p_country_code) <> 2 then
    raise exception 'invalid_country_code';
  end if;

  -- Serialize concurrent calls from the SAME caller so a double-submit cannot race past the
  -- existing-membership check below and create two organizations for one user.
  perform pg_advisory_xact_lock(hashtext(auth.uid()::text));

  -- REVIEW FIX #7 (multi-org onboarding): an earlier draft ranked the caller's memberships and
  -- returned the top one, implicitly picking "the first" organization for a multi-org user — exactly
  -- the acting-organization anti-pattern T002's resolver exists to prevent. This function now only
  -- ever asks EXISTS: it never names, ranks, or picks any specific organization. A caller who already
  -- has ANY active membership is refused onboarding outright; which organization(s) are relevant is
  -- entirely the existing acting-organization resolver's job (`lib/auth/dal.ts`), never this RPC's.
  if exists (
    select 1 from public.organization_members om
    where om.user_id = auth.uid()
      and om.is_active = true
  ) then
    return jsonb_build_object('ok', false, 'conflict', 'already_member');
  end if;

  -- Server-owned capability derivation. BUYER = buy-only; SELLER = buy AND sell (never sell-only).
  -- Neither flag alone grants trading — organization_can_buy/sell also require ACTIVE + APPROVED KYB.
  if p_account_type = 'SELLER' then
    v_can_buy := true;
    v_can_sell := true;
  else
    v_can_buy := true;
    v_can_sell := false;
  end if;

  begin
    insert into public.organizations (
      legal_name, display_name, account_type, country_code, tax_number, registration_number,
      email, phone, status, is_hills_internal, created_by, can_buy, can_sell
    )
    values (
      trim(p_legal_name), p_display_name, p_account_type, p_country_code, p_tax_number,
      p_registration_number, p_email, p_phone, 'PENDING_KYB', false, auth.uid(), v_can_buy, v_can_sell
    )
    returning id into v_new_org_id;
  exception
    when unique_violation then
      raise exception 'tax_number_already_registered';
  end;

  insert into public.organization_members (organization_id, user_id, member_role, is_active)
  values (v_new_org_id, auth.uid(), 'OWNER', true);

  return jsonb_build_object(
    'ok', true,
    'organization_id', v_new_org_id,
    'organization_status', 'PENDING_KYB'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.t033_internal_update_kyb_draft(p_application_id uuid, p_registered_address text, p_business_activity text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_organization_id uuid;
  v_status text;
begin
  if auth.uid() is null or public.is_blocked_user() then
    raise exception 'forbidden';
  end if;

  select organization_id, status into v_organization_id, v_status
  from public.kyb_applications
  where id = p_application_id
  for update;

  if v_organization_id is null then
    raise exception 'application_not_found';
  end if;

  if not public.is_org_member(v_organization_id) then
    raise exception 'forbidden';
  end if;

  -- Same editable-state rule the Storage INSERT policy already enforces for document uploads
  -- (contract §3): a draft is editable in DRAFT or RESUBMISSION_REQUIRED, never once SUBMITTED,
  -- UNDER_REVIEW, APPROVED, REJECTED, or SUSPENDED.
  if not (v_status = any (array['DRAFT', 'RESUBMISSION_REQUIRED'])) then
    raise exception 'invalid_transition';
  end if;

  update public.kyb_applications
  set
    registered_address = nullif(btrim(p_registered_address), ''),
    business_activity = nullif(btrim(p_business_activity), ''),
    updated_at = now()
  where id = p_application_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_dispute(p_dispute_id uuid, p_expected_status text, p_to_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_dispute public.disputes%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_now timestamptz := now();
  v_actor uuid := auth.uid();
  v_history_id uuid;
  v_outcome boolean;
begin
  if not public.is_compliance_operator() then
    raise exception 'forbidden';
  end if;
  if not public.mfa_satisfied() then
    raise exception 'mfa_step_up_required';
  end if;
  if char_length(v_reason) = 0 then
    raise exception 'dispute_reason_required';
  end if;
  if char_length(v_reason) > 2000 then
    raise exception 'dispute_reason_too_long';
  end if;

  select * into v_dispute from public.disputes where id = p_dispute_id for update;
  if v_dispute.id is null then
    raise exception 'dispute_not_found';
  end if;

  -- Compare-and-set on the status the operator saw. Concurrent callers serialise on the row lock above;
  -- the loser re-reads the committed status here and is refused rather than overwriting.
  if p_expected_status is null or v_dispute.status <> p_expected_status then
    raise exception 'dispute_stale';
  end if;

  if not (
    (v_dispute.status = 'OPEN' and p_to_status in ('UNDER_REVIEW', 'FROZEN', 'REJECTED'))
    or (v_dispute.status = 'UNDER_REVIEW' and p_to_status in ('FROZEN', 'RESOLVED', 'REJECTED'))
    or (v_dispute.status = 'FROZEN' and p_to_status in ('UNDER_REVIEW', 'RESOLVED', 'REJECTED'))
    or (v_dispute.status = 'RESOLVED' and p_to_status = 'CLOSED')
    or (v_dispute.status = 'REJECTED' and p_to_status = 'CLOSED')
  ) then
    raise exception 'invalid_dispute_transition';
  end if;

  v_outcome := p_to_status in ('RESOLVED', 'REJECTED');
  if v_outcome and (v_dispute.resolution is not null or v_dispute.resolved_by is not null or v_dispute.resolved_at is not null) then
    raise exception 'dispute_resolution_already_recorded';
  end if;

  perform set_config('app.dispute_transition', 'true', true);

  update public.disputes
  set status = p_to_status,
      updated_at = v_now,
      resolution = case when v_outcome then v_reason else resolution end,
      resolved_by = case when v_outcome then v_actor else resolved_by end,
      resolved_at = case when v_outcome then v_now else resolved_at end
  where id = v_dispute.id;

  insert into public.dispute_status_history (dispute_id, from_status, to_status, actor_user_id, reason, correlation_id, created_at)
  values (v_dispute.id, v_dispute.status, p_to_status, v_actor, v_reason, v_dispute.correlation_id, v_now)
  returning id into v_history_id;

  perform set_config('app.dispute_transition', 'false', true);

  return jsonb_build_object(
    'dispute_id', v_dispute.id,
    'from_status', v_dispute.status,
    'to_status', p_to_status,
    'history_id', v_history_id,
    'recorded_at', v_now
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_kyb_application(p_application_id uuid, p_allowed_source_states text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_organization_id uuid;
  v_status text;
begin
  if auth.uid() is null or public.is_blocked_user() then
    raise exception 'forbidden';
  end if;

  select organization_id, status into v_organization_id, v_status
  from public.kyb_applications
  where id = p_application_id
  for update;

  if v_organization_id is null then
    raise exception 'application_not_found';
  end if;

  if not public.is_org_member(v_organization_id) then
    raise exception 'forbidden';
  end if;

  if not (v_status = any (p_allowed_source_states)) then
    raise exception 'invalid_transition';
  end if;

  update public.kyb_applications
  set status = 'SUBMITTED',
      submitted_by = auth.uid(),
      submitted_at = now()
  where id = p_application_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_commerce_settings(p_validity_hours integer, p_checkout_enabled boolean, p_proof_enabled boolean, p_request_id uuid, p_pilot_organization_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare v_replay jsonb; v_old public.commerce_settings%rowtype; v_new public.commerce_settings%rowtype; v_result jsonb;
begin
  if not public.is_platform_admin() then raise exception 'forbidden'; end if;
  if not public.mfa_satisfied() then raise exception 'mfa_step_up_required'; end if;
  v_replay := public.commerce_request_begin(p_request_id, 'update_commerce_settings', null);
  if v_replay is not null then return v_replay; end if;
  if p_validity_hours is not null and p_validity_hours not between 1 and 720 then raise exception 'invalid_validity_hours'; end if;
  select * into v_old from public.commerce_settings where id for update;
  update public.commerce_settings set proforma_validity_hours = coalesce(p_validity_hours, proforma_validity_hours),
    bank_transfer_checkout_enabled = coalesce(p_checkout_enabled, bank_transfer_checkout_enabled),
    proof_submission_enabled = coalesce(p_proof_enabled, proof_submission_enabled),
    pilot_organization_ids = case when p_pilot_organization_ids is null then pilot_organization_ids else
      coalesce((select array_agg(distinct x order by x) from unnest(p_pilot_organization_ids) x where x is not null), '{}'::uuid[]) end,
    updated_by = auth.uid() where id returning * into v_new;
  v_result := jsonb_build_object('proforma_validity_hours', v_new.proforma_validity_hours,
    'bank_transfer_checkout_enabled', v_new.bank_transfer_checkout_enabled, 'proof_submission_enabled', v_new.proof_submission_enabled,
    'pilot_organization_ids', to_jsonb(v_new.pilot_organization_ids));
  insert into public.audit_logs (actor_user_id, entity_type, entity_id, action, old_data, new_data, metadata, correlation_id)
  values (auth.uid(), 'commerce_settings', null, 'UPDATE', jsonb_build_object('proforma_validity_hours', v_old.proforma_validity_hours,
    'bank_transfer_checkout_enabled', v_old.bank_transfer_checkout_enabled, 'proof_submission_enabled', v_old.proof_submission_enabled,
    'pilot_organization_ids', to_jsonb(v_old.pilot_organization_ids)), v_result,
    jsonb_build_object('operation', 'update_commerce_settings', 'request_id', p_request_id), p_request_id);
  perform public.commerce_request_complete(p_request_id, v_result); return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_order_item_quantity(p_order_item_id uuid, p_quantity_kg numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_item public.order_items%rowtype;
  v_order public.orders%rowtype;
  v_planned numeric(14,3);
begin
  if p_quantity_kg is null or p_quantity_kg <= 0 then
    raise exception 'requested_quantity_not_available';
  end if;

  -- Non-enumerating resolution: the item is found ONLY if the caller is an active member of its
  -- order's buyer organization. A nonexistent id and another organization's id both raise the same
  -- 'order_item_not_found'; every more specific refusal below is shown only to that buyer.
  select oi.*
  into v_item
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  where oi.id = p_order_item_id
    and public.is_org_member(o.buyer_organization_id);

  if v_item.id is null then
    raise exception 'order_item_not_found';
  end if;

  -- Lock the parent order first — checkout_order()'s own lock order (order, then listing) — so an
  -- edit can never interleave with a concurrent confirm/checkout of the same order.
  select *
  into v_order
  from public.orders
  where id = v_item.order_id
  for update;

  if v_order.status <> 'DRAFT' then
    raise exception 'order_items_can_only_change_in_draft';
  end if;

  if not public.organization_can_buy(v_order.buyer_organization_id) then
    raise exception 'buyer_not_authorized';
  end if;

  -- A shipment plan that has left DRAFT (REQUESTED or any warehouse state) is closed to the buyer
  -- (validate_shipment_item); changing or removing an item it plans would silently break it.
  if exists (
    select 1
    from public.shipment_items si
    join public.order_shipments os on os.id = si.shipment_id
    where si.order_item_id = v_item.id
      and os.status not in ('DRAFT', 'CANCELLED', 'FAILED')
  ) then
    raise exception 'order_item_on_closed_shipment_plan';
  end if;

  select coalesce(sum(si.planned_quantity_kg), 0)
  into v_planned
  from public.shipment_items si
  join public.order_shipments os on os.id = si.shipment_id
  where si.order_item_id = v_item.id
    and os.status not in ('CANCELLED', 'FAILED');

  if v_planned > p_quantity_kg then
    raise exception 'order_item_quantity_below_shipment_plan';
  end if;

  -- The ONLY column written. trg_order_item_offer (validate_order_item_offer) still fires on this
  -- UPDATE and remains the authority on availability, own-listing and the price/lot/seller snapshots.
  update public.order_items
  set quantity_kg = p_quantity_kg
  where id = v_item.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_delivery_destination(p_id uuid, p_org_id uuid, p_fields jsonb, p_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare v_replay jsonb; v_id uuid; v_default boolean;
begin
  perform public.commerce_assert_buyer_member(p_org_id);
  v_replay := public.commerce_request_begin(p_request_id, 'upsert_delivery_destination', p_org_id);
  if v_replay is not null then return (v_replay ->> 'destination_id')::uuid; end if;
  if p_id is not null then
    select d.id into v_id from public.delivery_destinations d
    where d.id = p_id and d.organization_id = p_org_id and d.retired_at is null for update;
    if v_id is null then raise exception 'destination_not_found'; end if;
  end if;
  begin
    if jsonb_typeof(p_fields) is distinct from 'object' then raise exception using errcode = '23514'; end if;
    v_default := coalesce((p_fields ->> 'is_default')::boolean, false);
    if v_default then update public.delivery_destinations set is_default = false
      where organization_id = p_org_id and is_default and retired_at is null and id is distinct from v_id; end if;
    if v_id is null then
      insert into public.delivery_destinations (organization_id, label, country_code, city, address_line_1, address_line_2,
        contact_name, contact_phone, delivery_method, is_default, created_by)
      values (p_org_id, p_fields ->> 'label', p_fields ->> 'country_code', p_fields ->> 'city', p_fields ->> 'address_line_1',
        nullif(p_fields ->> 'address_line_2', ''), p_fields ->> 'contact_name', p_fields ->> 'contact_phone',
        coalesce(p_fields ->> 'delivery_method', 'Courier'), v_default, auth.uid()) returning id into v_id;
    else
      update public.delivery_destinations set label = p_fields ->> 'label', country_code = p_fields ->> 'country_code',
        city = p_fields ->> 'city', address_line_1 = p_fields ->> 'address_line_1',
        address_line_2 = nullif(p_fields ->> 'address_line_2', ''), contact_name = p_fields ->> 'contact_name',
        contact_phone = p_fields ->> 'contact_phone', delivery_method = coalesce(p_fields ->> 'delivery_method', 'Courier'),
        is_default = v_default where id = v_id;
    end if;
  exception when check_violation or not_null_violation or string_data_right_truncation or invalid_text_representation then
    raise exception 'destination_invalid';
  end;
  perform public.commerce_request_complete(p_request_id, jsonb_build_object('destination_id', v_id));
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_dispute_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.status <> 'OPEN' or new.resolution is not null or new.resolved_by is not null or new.resolved_at is not null then
      raise exception 'dispute_must_start_open';
    end if;
    return new;
  end if;

  if coalesce(current_setting('app.dispute_transition', true), 'false') <> 'true' then
    raise exception 'dispute_changes_only_through_workflow';
  end if;

  if new.id <> old.id
     or new.order_id <> old.order_id
     or new.opened_by_user_id <> old.opened_by_user_id
     or new.opened_by_organization_id is distinct from old.opened_by_organization_id
     or new.reason <> old.reason
     or new.correlation_id <> old.correlation_id
     or new.opened_at <> old.opened_at
     or new.created_at <> old.created_at
  then
    raise exception 'dispute_intake_is_immutable';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_inventory_location()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin

  if new.warehouse_id is null then
    raise exception 'inventory_requires_warehouse';
  end if;

  if new.warehouse_location_id is not null
     and not exists (
       select 1
       from public.warehouse_locations wl
       where wl.id = new.warehouse_location_id
         and wl.warehouse_id = new.warehouse_id
     )
  then
    raise exception 'warehouse_location_mismatch';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_kyb_document_lineage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_prev_application_id uuid;
  v_prev_version integer;
  v_prev_status text;
  v_prev_document_type text;
begin
  if new.supersedes_document_id is not null then
    if new.supersedes_document_id = new.id then
      raise exception 'self_replacement_not_allowed';
    end if;

    select application_id, version, status, document_type
    into v_prev_application_id, v_prev_version, v_prev_status, v_prev_document_type
    from public.kyb_documents
    where id = new.supersedes_document_id;

    if v_prev_application_id is null then
      raise exception 'superseded_document_not_found';
    end if;

    if v_prev_application_id <> new.application_id then
      raise exception 'cross_application_document_replacement';
    end if;

    if v_prev_document_type <> new.document_type then
      raise exception 'cross_document_type_replacement';
    end if;

    if new.version <> v_prev_version + 1 then
      raise exception 'invalid_document_version';
    end if;

    if v_prev_status <> 'SUPERSEDED' then
      update public.kyb_documents
      set status = 'SUPERSEDED'
      where id = new.supersedes_document_id;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_manual_financial_adjustment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not public.is_internal_transition() then
    raise exception 'manual_adjustment_invalid' using detail = 'manual adjustments are recorded only through the finance workflow';
  end if;
  if new.payment_id is not null and not exists (select 1 from public.payments p where p.id = new.payment_id and p.order_id = new.order_id) then
    raise exception 'manual_adjustment_invalid' using detail = 'the payment does not belong to the order';
  end if;
  if new.payout_id is not null and not exists (select 1 from public.payouts p where p.id = new.payout_id and p.order_id = new.order_id) then
    raise exception 'manual_adjustment_invalid' using detail = 'the payout does not belong to the order';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_offer_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_inventory public.inventory_positions%rowtype;
begin

  if new.warehouse_id is null then
    raise exception 'listing_requires_warehouse';
  end if;


  if not exists (
    select 1
    from public.coffee_lots cl
    where cl.id = new.lot_id
      and cl.coffee_id = new.coffee_id
  ) then
    raise exception 'offer_coffee_lot_mismatch';
  end if;


  if new.warehouse_location_id is not null
     and not exists (
       select 1
       from public.warehouse_locations wl
       where wl.id = new.warehouse_location_id
         and wl.warehouse_id = new.warehouse_id
     )
  then
    raise exception 'warehouse_location_mismatch';
  end if;


  if new.seller_type = 'HILLS' then

    if not exists (
      select 1
      from public.organizations o
      where o.id = new.seller_organization_id
        and o.is_hills_internal = true
        and o.status = 'ACTIVE'
    ) then
      raise exception
        'hills_listing_requires_active_hills_owner';
    end if;

  else

    if not public.organization_can_sell(
      new.seller_organization_id
    ) then
      raise exception
        'member_listing_requires_authorized_seller';
    end if;


    if new.source_purchase_order_item_id is null then
      raise exception
        'member_listing_requires_purchase_source';
    end if;


    if not exists (
      select 1
      from public.order_items oi
      join public.orders o
        on o.id = oi.order_id
      where oi.id = new.source_purchase_order_item_id
        and oi.lot_id = new.lot_id
        and o.buyer_organization_id =
            new.seller_organization_id
        and o.status in (
          'PAID',
          'FULFILLMENT_IN_PROGRESS',
          'PARTIALLY_DELIVERED',
          'COMPLETED'
        )
    ) then
      raise exception
        'invalid_member_listing_purchase_source';
    end if;

  end if;


  select *
  into v_inventory
  from public.inventory_positions ip
  where ip.lot_id = new.lot_id
    and ip.owner_organization_id =
        new.seller_organization_id
    and ip.warehouse_id = new.warehouse_id
    and ip.warehouse_location_id
        is not distinct from new.warehouse_location_id
  order by ip.created_at
  limit 1
  for update;


  if v_inventory.id is null then
    raise exception 'seller_inventory_position_missing';
  end if;


  if (
    new.quantity_kg
    - new.filled_quantity_kg
    - new.reserved_quantity_kg
  ) >
  (
    v_inventory.available_quantity_kg
    - v_inventory.reserved_quantity_kg
  ) then
    raise exception 'listing_exceeds_tradable_inventory';
  end if;


  -- Provenance cannot be changed after draft.
  if tg_op = 'UPDATE'
     and old.status <> 'DRAFT'
     and (
       new.lot_id is distinct from old.lot_id
       or new.coffee_id is distinct from old.coffee_id
       or new.seller_organization_id
          is distinct from old.seller_organization_id
       or new.warehouse_id
          is distinct from old.warehouse_id
       or new.warehouse_location_id
          is distinct from old.warehouse_location_id
       or new.source_purchase_order_item_id
          is distinct from old.source_purchase_order_item_id
     )
  then
    raise exception 'listing_provenance_is_locked';
  end if;


  if tg_op = 'UPDATE'
     and new.status <> old.status
  then

    if new.status in (
      'APPROVED',
      'REJECTED',
      'PUBLISHED',
      'SUSPENDED'
    )
    and not public.is_compliance_operator()
    and not public.is_internal_transition()
    then
      raise exception 'compliance_required_for_listing_state';
    end if;


    if old.status = 'DRAFT'
       and new.status not in (
         'PENDING_REVIEW',
         'ARCHIVED'
       )
    then
      raise exception 'invalid_listing_transition';

    elsif old.status = 'PENDING_REVIEW'
       and new.status not in (
         'APPROVED',
         'REJECTED',
         'DRAFT'
       )
    then
      raise exception 'invalid_listing_transition';

    elsif old.status = 'APPROVED'
       and new.status not in (
         'PUBLISHED',
         'ARCHIVED'
       )
    then
      raise exception 'invalid_listing_transition';

    elsif old.status = 'PUBLISHED'
       and new.status not in (
         'PARTIALLY_FILLED',
         'SUSPENDED',
         'SOLD_OUT',
         'ARCHIVED'
       )
    then
      raise exception 'invalid_listing_transition';

    elsif old.status = 'PARTIALLY_FILLED'
       and new.status not in (
         'SUSPENDED',
         'SOLD_OUT',
         'ARCHIVED'
       )
    then
      raise exception 'invalid_listing_transition';

    elsif old.status = 'REJECTED'
       and new.status <> 'DRAFT'
    then
      raise exception 'invalid_listing_transition';

    end if;

  end if;


  -- Feature 007 DB blocker run (DB-OPEN-16): publication rule unchanged for every path EXCEPT the authoritative
  -- checkout reservation. The exemption needs BOTH (a) the transaction-local marker that only
  -- checkout_order() sets around its own reserved-mirror UPDATE (no client can set it: PostgREST
  -- exposes neither set_config nor custom GUCs), and (b) the reservation-only shape: status,
  -- quantity_kg and filled_quantity_kg unchanged, reserved_quantity_kg increased. A seller,
  -- compliance, admin or service-role direct UPDATE of the same shape stays refused. No status is
  -- changed here — reservation is not fill.
  if new.status in (
    'PUBLISHED',
    'PARTIALLY_FILLED'
  )
  and (
    new.quantity_kg
    - new.filled_quantity_kg
    - new.reserved_quantity_kg
  ) <= 0
  and not (
    tg_op = 'UPDATE'
    and coalesce(current_setting('app.checkout_reservation', true), 'false') = 'true'
    and new.status = old.status
    and new.quantity_kg = old.quantity_kg
    and new.filled_quantity_kg = old.filled_quantity_kg
    and new.reserved_quantity_kg > old.reserved_quantity_kg
  )
  then
    raise exception 'cannot_publish_empty_listing';
  end if;


  new.is_visible :=
    new.status in (
      'PUBLISHED',
      'PARTIALLY_FILLED'
    );


  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_order_item_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_offer public.coffee_offers%rowtype;
  v_order public.orders%rowtype;
  v_position public.inventory_positions%rowtype;

  v_product_name text;
  v_origin_name text;
  v_lot_code text;
begin

  select *
  into v_order
  from public.orders
  where id = new.order_id;


  if v_order.id is null
     or v_order.status <> 'DRAFT'
  then
    raise exception 'order_items_can_only_change_in_draft';
  end if;


  if not public.organization_can_buy(
    v_order.buyer_organization_id
  ) then
    raise exception 'buyer_not_authorized';
  end if;


  select *
  into v_offer
  from public.coffee_offers
  where id = new.offer_id
  for update;


  if v_offer.id is null
     or v_offer.status not in (
       'PUBLISHED',
       'PARTIALLY_FILLED'
     )
     or not v_offer.is_visible
  then
    raise exception 'listing_is_not_available';
  end if;


  if v_order.buyer_organization_id =
     v_offer.seller_organization_id
  then
    raise exception 'cannot_buy_own_listing';
  end if;


  if new.quantity_kg <= 0
     or new.quantity_kg >
        (
          v_offer.quantity_kg
          - v_offer.filled_quantity_kg
          - v_offer.reserved_quantity_kg
        )
  then
    raise exception 'requested_quantity_not_available';
  end if;


  select *
  into v_position
  from public.inventory_positions ip
  where ip.lot_id = v_offer.lot_id
    and ip.owner_organization_id =
        v_offer.seller_organization_id
    and ip.warehouse_id =
        v_offer.warehouse_id
    and ip.warehouse_location_id
        is not distinct from
        v_offer.warehouse_location_id
  order by ip.created_at
  limit 1
  for update;


  if v_position.id is null
     or (
       v_position.available_quantity_kg
       - v_position.reserved_quantity_kg
     ) < new.quantity_kg
  then
    raise exception 'inventory_quantity_not_available';
  end if;


  select
    c.name,
    o.name,
    cl.lot_code
  into
    v_product_name,
    v_origin_name,
    v_lot_code
  from public.coffee_lots cl
  join public.coffees c
    on c.id = cl.coffee_id
  left join public.origins o
    on o.id = c.origin_id
  where cl.id = v_offer.lot_id;


  new.lot_id := v_offer.lot_id;
  new.seller_organization_id :=
    v_offer.seller_organization_id;
  new.unit_price_per_kg :=
    v_offer.price_per_kg;
  new.seller_type_snapshot :=
    v_offer.seller_type;

  new.product_name_snapshot :=
    coalesce(v_product_name, new.product_name_snapshot);

  new.origin_name_snapshot :=
    coalesce(v_origin_name, new.origin_name_snapshot);

  new.lot_code_snapshot :=
    coalesce(v_lot_code, new.lot_code_snapshot);


  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_order_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  if new.commerce_flow is distinct from old.commerce_flow then
    if not (public.is_internal_transition() and old.commerce_flow = 'LEGACY' and new.commerce_flow = 'BANK_TRANSFER_V1'
            and old.status = 'DRAFT' and new.status = 'DRAFT') then
      raise exception 'order_commerce_flow_immutable';
    end if;
  end if;

  if (new.cancelled_at, new.cancelled_by, new.cancel_reason, new.has_manual_adjustment)
       is distinct from (old.cancelled_at, old.cancelled_by, old.cancel_reason, old.has_manual_adjustment)
     and not public.is_internal_transition() then
    raise exception 'order_field_not_client_writable';
  end if;

  if new.commerce_flow = 'LEGACY' then
    if new.status <> old.status then
      if not public.is_internal_transition() and not public.is_platform_admin() then
        if not (old.status = 'DRAFT' and new.status = 'CONFIRMED') then
          raise exception 'order_status_can_only_change_through_workflow';
        end if;
      end if;

      if old.status = 'DRAFT' and new.status not in ('CONFIRMED', 'VOID') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'CONFIRMED' and new.status not in ('HOLD', 'VOID') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'HOLD' and new.status not in ('PAYMENT_PROOF_SUBMITTED', 'EXPIRED', 'VOID') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'PAYMENT_PROOF_SUBMITTED' and new.status not in ('PAYMENT_UNDER_REVIEW', 'HOLD', 'EXPIRED') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'PAYMENT_UNDER_REVIEW' and new.status not in ('PAID', 'HOLD', 'VOID') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'PAID' and new.status not in ('FULFILLMENT_IN_PROGRESS', 'PARTIALLY_DELIVERED', 'COMPLETED', 'DISPUTED', 'VOID') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'FULFILLMENT_IN_PROGRESS' and new.status not in ('PARTIALLY_DELIVERED', 'COMPLETED') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'PARTIALLY_DELIVERED' and new.status <> 'COMPLETED' then raise exception 'invalid_order_transition'; end if;
      if old.status in ('COMPLETED', 'EXPIRED', 'VOID') then raise exception 'terminal_order_cannot_change'; end if;
      -- Feature 013 fence: the values M1 adds belong to the BANK_TRANSFER_V1 graph only.
      if new.status in ('PROFORMA_ISSUED', 'CANCELLED', 'PAYMENT_REJECTED') then raise exception 'invalid_order_transition'; end if;
    end if;

    if new.status = 'HOLD' then
      perform public.assert_order_checkout_ready(new.id);
      new.hold_started_at := coalesce(new.hold_started_at, now());
      new.hold_expires_at := coalesce(new.hold_expires_at, now() + interval '20 minutes');
    end if;
  else
    if new.status <> old.status then
      if not public.is_internal_transition()
         and not (new.status = 'DISPUTED' and public.is_platform_admin()) then
        raise exception 'order_status_can_only_change_through_workflow';
      end if;

      if old.status = 'DRAFT' and new.status not in ('HOLD', 'PROFORMA_ISSUED', 'CANCELLED', 'VOID') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'PROFORMA_ISSUED' and new.status not in ('HOLD', 'CANCELLED', 'VOID') then raise exception 'invalid_order_transition'; end if;
      -- Direct HOLD -> PAYMENT_UNDER_REVIEW is strictly forbidden. HOLD can only advance to PAYMENT_PROOF_SUBMITTED.
      if old.status = 'HOLD' and new.status not in ('PAYMENT_PROOF_SUBMITTED', 'EXPIRED', 'CANCELLED', 'VOID') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'PAYMENT_PROOF_SUBMITTED' and new.status not in ('PAYMENT_UNDER_REVIEW', 'PAID', 'PAYMENT_REJECTED', 'CANCELLED', 'VOID') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'PAYMENT_UNDER_REVIEW' and new.status not in ('PAID', 'PAYMENT_REJECTED', 'VOID') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'PAID' and new.status not in ('FULFILLMENT_IN_PROGRESS', 'PARTIALLY_DELIVERED', 'COMPLETED', 'DISPUTED') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'FULFILLMENT_IN_PROGRESS' and new.status not in ('PARTIALLY_DELIVERED', 'COMPLETED', 'DISPUTED') then raise exception 'invalid_order_transition'; end if;
      if old.status = 'PARTIALLY_DELIVERED' and new.status not in ('COMPLETED', 'DISPUTED') then raise exception 'invalid_order_transition'; end if;
      -- data-model §7.1 defines no exit from DISPUTED for v1 rows: fail closed until one is specified.
      if old.status = 'DISPUTED' then raise exception 'invalid_order_transition'; end if;
      if old.status = 'CONFIRMED' then raise exception 'invalid_order_transition'; end if;
      if old.status in ('COMPLETED', 'EXPIRED', 'CANCELLED', 'PAYMENT_REJECTED', 'VOID') then raise exception 'terminal_order_cannot_change'; end if;

      -- The hold window is the reservation's own (copied expires_at); never defaulted here.
      if new.status = 'HOLD' then
        if new.hold_expires_at is null then raise exception 'order_hold_window_required'; end if;
        new.hold_started_at := coalesce(new.hold_started_at, clock_timestamp());
      end if;
      if new.status = 'CANCELLED' then new.cancelled_at := coalesce(new.cancelled_at, clock_timestamp()); end if;
    end if;
  end if;

  if new.status = 'PAID' and new.paid_at is null then new.paid_at := now(); end if;
  if new.status = 'COMPLETED' and new.completed_at is null then new.completed_at := now(); end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_review_item_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  if not exists (
    select 1 from public.kyb_documents kd
    where kd.id = new.document_id
      and kd.application_id = new.application_id
  ) then
    raise exception 'review_item_document_application_mismatch';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_shipment_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_item_order_id uuid;
  v_shipment_order_id uuid;
  v_shipment_status text;
  v_shipment_settlement_verified_at timestamptz;
  v_order_status text;
  v_ordered_quantity numeric(14,3);
  v_other_planned numeric(14,3);
  v_newly_delivered numeric(14,3);
  v_buyer_organization_id uuid;
  v_lot_id uuid;
  v_alloc public.storage_allocations%rowtype;
  v_alloc_count int;
  v_position public.inventory_positions%rowtype;
  v_internal_reservation_mutation boolean := coalesce(current_setting('app.delivery_reservation_mutation', true), 'false') = 'true';
begin

  -- The only exception to the client-tamper reset is the exact guarded child mutation emitted by
  -- validate_shipment_transition() under its transaction-local SECURITY DEFINER marker.  It may
  -- alter reserved_quantity_kg only; all ordinary UPDATEs still discard client input here.
  if tg_op = 'INSERT' then
    new.reserved_quantity_kg := 0;
  elsif tg_op = 'UPDATE' then
    if v_internal_reservation_mutation then
      if new.order_item_id is distinct from old.order_item_id
         or new.shipment_id is distinct from old.shipment_id
         or new.planned_quantity_kg is distinct from old.planned_quantity_kg
         or new.delivered_quantity_kg is distinct from old.delivered_quantity_kg
      then
        raise exception 'delivery_reservation_ledger_inconsistent';
      end if;
    else
      new.reserved_quantity_kg := old.reserved_quantity_kg;
    end if;
  end if;

  select
    oi.order_id,
    oi.quantity_kg,
    oi.lot_id
  into
    v_item_order_id,
    v_ordered_quantity,
    v_lot_id
  from public.order_items oi
  where oi.id = new.order_item_id;


  select
    os.order_id,
    os.status,
    os.settlement_verified_at
  into
    v_shipment_order_id,
    v_shipment_status,
    v_shipment_settlement_verified_at
  from public.order_shipments os
  where os.id = new.shipment_id;


  if v_item_order_id is null
     or v_shipment_order_id is null
  then
    raise exception 'shipment_or_order_item_missing';
  end if;


  if v_item_order_id <> v_shipment_order_id then
    raise exception 'shipment_order_item_mismatch';
  end if;


  -- The triggering item UPDATE already owns the item lock.  Lock the parent order next, matching
  -- validate_shipment_transition's item -> order -> position protocol before making any custody
  -- reduction decision.
  select status
  into v_order_status
  from public.orders
  where id = v_item_order_id
  for update;


  if tg_op = 'INSERT' then

    if v_shipment_status <> 'DRAFT' then
      raise exception 'shipment_plan_is_closed';
    end if;

    if new.delivered_quantity_kg <> 0 then
      raise exception 'delivery_reservation_requires_settled_order';
    end if;

  elsif tg_op = 'UPDATE' then

    if new.planned_quantity_kg
       is distinct from old.planned_quantity_kg
       and v_shipment_status <> 'DRAFT'
    then
      raise exception 'shipment_plan_is_closed';
    end if;


    if new.delivered_quantity_kg
       is distinct from old.delivered_quantity_kg
    then

      if not public.is_warehouse_operator()
         and not public.is_internal_transition()
      then
        raise exception
          'only_warehouse_can_record_delivery';
      end if;

      if v_shipment_settlement_verified_at is null
         or v_order_status not in ('PAID', 'FULFILLMENT_IN_PROGRESS', 'PARTIALLY_DELIVERED', 'COMPLETED')
      then
        raise exception 'delivery_reservation_requires_settled_order';
      end if;

      if new.delivered_quantity_kg <
         old.delivered_quantity_kg
      then
        raise exception
          'delivered_quantity_cannot_decrease';
      end if;

      -- Feature 009 DB-BLOCK-07 (Issues 1/2/6/7/9, hardened) — release exactly the newly-delivered
      -- amount. Goods LEAVE custody entirely: both reserved_quantity_kg AND available_quantity_kg
      -- decrease together (see the migration file's own header for the proof this is the correct
      -- arithmetic). storage_allocations (Feature 005's OWN existing custody ledger) is updated in
      -- the same statement, never a second/competing model. Fails closed on a missing/ambiguous
      -- allocation/position or an inconsistent ledger.
      v_newly_delivered := new.delivered_quantity_kg - old.delivered_quantity_kg;

      if v_newly_delivered > 0 then

        if old.reserved_quantity_kg < v_newly_delivered then
          raise exception 'delivery_reservation_ledger_inconsistent';
        end if;

        select buyer_organization_id into v_buyer_organization_id from public.orders where id = v_item_order_id;

        select count(*) into v_alloc_count
        from public.storage_allocations
        where order_item_id = new.order_item_id
          and owner_organization_id = v_buyer_organization_id;

        if v_alloc_count = 0 then
          raise exception 'delivery_release_position_missing';
        elsif v_alloc_count > 1 then
          raise exception 'delivery_reservation_position_ambiguous';
        end if;

        select * into v_alloc
        from public.storage_allocations
        where order_item_id = new.order_item_id
          and owner_organization_id = v_buyer_organization_id
        limit 1;

        select * into v_position
        from public.inventory_positions ip
        where ip.lot_id = v_lot_id
          and ip.owner_organization_id = v_buyer_organization_id
          and ip.warehouse_id = v_alloc.warehouse_id
          and ip.warehouse_location_id is not distinct from v_alloc.warehouse_location_id
        for update;

        if v_position.id is null then
          raise exception 'delivery_release_position_missing';
        end if;

        if v_position.reserved_quantity_kg < v_newly_delivered
           or v_position.available_quantity_kg < v_newly_delivered
        then
          raise exception 'delivery_reservation_ledger_inconsistent';
        end if;

        update public.inventory_positions
        set available_quantity_kg = available_quantity_kg - v_newly_delivered,
            reserved_quantity_kg = reserved_quantity_kg - v_newly_delivered,
            updated_at = now()
        where id = v_position.id;

        update public.storage_allocations
        set released_quantity_kg = released_quantity_kg + v_newly_delivered,
            status = case when released_quantity_kg + v_newly_delivered >= quantity_kg then 'DELIVERED' else 'RELEASED' end
        where id = v_alloc.id;

        new.reserved_quantity_kg := old.reserved_quantity_kg - v_newly_delivered;

      end if;

    end if;

  end if;


  if new.delivered_quantity_kg >
     new.planned_quantity_kg
  then
    raise exception 'delivered_quantity_exceeds_plan';
  end if;


  select coalesce(
    sum(si.planned_quantity_kg),
    0
  )
  into v_other_planned
  from public.shipment_items si
  join public.order_shipments os
    on os.id = si.shipment_id
  where si.order_item_id =
        new.order_item_id
    and si.id <> new.id
    and os.status not in (
      'CANCELLED',
      'FAILED'
    );


  if v_other_planned +
     new.planned_quantity_kg >
     v_ordered_quantity
  then
    raise exception
      'shipment_plan_exceeds_order_item';
  end if;


  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_shipment_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_order public.orders%rowtype;
  v_item record;
  v_alloc_count int;
  v_settled boolean := false;
  v_newly_gated boolean := false;
  v_already_gated boolean := false;
  v_releasing boolean := false;
  v_item_count int := 0;
  v_unreserved_count int := 0;
  v_reserved_count int := 0;
  v_remaining_quantity numeric(14,3);
  v_rows int;
  v_trusted_settlement_mutation boolean := coalesce(current_setting('app.delivery_settlement_mutation', true), 'false') = 'true';
  v_alloc public.storage_allocations%rowtype;
  v_position public.inventory_positions%rowtype;
begin

  -- The baseline binding is UPDATE-only.  This draft replaces it with BEFORE INSERT OR UPDATE so a
  -- buyer's permitted DRAFT insert cannot pre-seed the diagnostic gate.  Operational insertion is
  -- deliberately fail-closed: a shipment must first exist as DRAFT with its plan before a later,
  -- separately validated transition can reserve inventory.
  if tg_op = 'INSERT' then
    new.settlement_verified_at := null;
    if new.status <> 'DRAFT' then
      raise exception 'shipment_must_start_draft';
    end if;
    return new;
  end if;

  -- UPDATE tamper protection: no caller may pre-populate or alter this trigger-owned value, EXCEPT
  -- the trusted settlement-time stamp issued by reserve_ready_deliveries_for_settlement() under its
  -- own transaction-local marker, which may ONLY change this one column — status and every locked
  -- detail field must stay byte-identical, or the write is rejected outright.
  if v_trusted_settlement_mutation then
    if new.status is distinct from old.status
       or new.delivery_method is distinct from old.delivery_method
       or new.country_code is distinct from old.country_code
       or new.city is distinct from old.city
       or new.address_line is distinct from old.address_line
       or new.contact_name is distinct from old.contact_name
       or new.contact_phone is distinct from old.contact_phone
       or new.shipping_fee is distinct from old.shipping_fee
    then
      raise exception 'delivery_reservation_ledger_inconsistent';
    end if;
  else
    new.settlement_verified_at := old.settlement_verified_at;
  end if;

  if new.status <> old.status then

    -- Buyer can only request/cancel draft.
    if not public.is_warehouse_operator()
       and not public.is_internal_transition()
       and not (
         old.status = 'DRAFT'
         and new.status in (
           'REQUESTED',
           'CANCELLED'
         )
       )
    then
      raise exception
        'warehouse_required_for_operational_shipment_status';
    end if;


    if old.status = 'DRAFT'
       and new.status not in (
         'REQUESTED',
         'READY',
         'CANCELLED'
       )
    then
      raise exception 'invalid_shipment_transition';

    elsif old.status = 'REQUESTED'
       and new.status not in (
         'CAPACITY_CONFIRMED',
         'READY',
         'CANCELLED',
         'FAILED',
         'DISPUTED'
       )
    then
      raise exception 'invalid_shipment_transition';

    elsif old.status = 'CAPACITY_CONFIRMED'
       and new.status not in (
         'RESERVED',
         'READY',
         'CANCELLED',
         'FAILED',
         'DISPUTED'
       )
    then
      raise exception 'invalid_shipment_transition';

    elsif old.status = 'READY'
       and new.status not in (
         'RESERVED',
         'BOOKED',
         'PICKING',
         'CANCELLED',
         'FAILED',
         'DISPUTED'
       )
    then
      raise exception 'invalid_shipment_transition';

    elsif old.status = 'RESERVED'
       and new.status not in (
         'PICKING',
         'BOOKED',
         'CANCELLED',
         'FAILED',
         'DISPUTED'
       )
    then
      raise exception 'invalid_shipment_transition';

    elsif old.status in (
      'PICKING',
      'BOOKED'
    )
    and new.status not in (
      'DISPATCHED',
      'CANCELLED',
      'FAILED',
      'DISPUTED'
    )
    then
      raise exception 'invalid_shipment_transition';

    elsif old.status = 'DISPATCHED'
       and new.status not in (
         'PARTIALLY_DELIVERED',
         'DELIVERED',
         'FAILED',
         'DISPUTED'
       )
    then
      raise exception 'invalid_shipment_transition';

    elsif old.status = 'PARTIALLY_DELIVERED'
       and new.status not in (
         'DELIVERED',
         'FAILED',
         'DISPUTED'
       )
    then
      raise exception 'invalid_shipment_transition';

    elsif old.status in (
      'DELIVERED',
      'CANCELLED'
    )
    then
      raise exception 'terminal_shipment_cannot_change';

    -- Recovery after failure/dispute needs an explicit future workflow.  A permissive re-entry
    -- would have to prove the remaining (not planned) quantity and custody invariants; this draft
    -- intentionally does neither silently.
    elsif old.status in ('FAILED', 'DISPUTED') then
      raise exception 'delivery_recovery_requires_dedicated_workflow';

    end if;


    -- Lock every child row before the order/position. The original shipment UPDATE has already
    -- locked order_shipments. A direct delivery UPDATE implicitly locks its item first and then
    -- takes the same item -> order -> position suffix below, preventing an order/item inversion.
    for v_item in
      select si.id, si.planned_quantity_kg, si.delivered_quantity_kg, si.reserved_quantity_kg
      from public.shipment_items si
      where si.shipment_id = new.id
      order by si.id
      for update
    loop
      v_item_count := v_item_count + 1;
      v_remaining_quantity := v_item.planned_quantity_kg - v_item.delivered_quantity_kg;
      if v_item.reserved_quantity_kg = 0 then
        v_unreserved_count := v_unreserved_count + 1;
      elsif v_item.reserved_quantity_kg = v_remaining_quantity then
        v_reserved_count := v_reserved_count + 1;
      else
        raise exception 'delivery_reservation_ledger_inconsistent';
      end if;
    end loop;

    -- Only after the fixed-id item lock set is held, lock the order. This same order lock is taken
    -- by direct delivered-quantity writes in validate_shipment_item(), preserving one protocol.
    select * into v_order from public.orders where id = new.order_id for update;
    v_settled := v_order.status in ('PAID', 'FULFILLMENT_IN_PROGRESS', 'PARTIALLY_DELIVERED', 'COMPLETED');
    v_already_gated := old.settlement_verified_at is not null;
    v_newly_gated :=
      (new.status in ('CAPACITY_CONFIRMED', 'RESERVED', 'PICKING', 'BOOKED', 'DISPATCHED', 'PARTIALLY_DELIVERED', 'DELIVERED')
       and old.status not in ('CAPACITY_CONFIRMED', 'RESERVED', 'PICKING', 'BOOKED', 'DISPATCHED', 'PARTIALLY_DELIVERED', 'DELIVERED'))
      or (new.status = 'READY' and old.status <> 'READY' and v_settled);

    if v_newly_gated then
      if not v_settled then
        raise exception 'delivery_reservation_requires_settled_order';
      end if;
      if v_item_count = 0 or (v_unreserved_count > 0 and v_reserved_count > 0) then
        raise exception 'delivery_reservation_ledger_inconsistent';
      end if;

      -- A READY re-entry or frozen reservation is ALREADY covered.  Do not repeat availability
      -- checks against its own earmark and do not attempt another reserve.
      if v_unreserved_count = v_item_count then
        for v_item in
          select si.id, si.order_item_id, si.planned_quantity_kg, oi.lot_id
          from public.shipment_items si
          join public.order_items oi on oi.id = si.order_item_id
          where si.shipment_id = new.id
          order by si.id
          for update of si
        loop
          perform public.apply_delivery_reservation(
            v_item.id, v_item.order_item_id, v_item.lot_id, v_order.buyer_organization_id, v_item.planned_quantity_kg
          );
        end loop;
      end if;
      new.settlement_verified_at := now();

    elsif v_already_gated
       and new.status <> old.status
       and new.status not in ('CANCELLED', 'FAILED', 'DISPUTED')
    then
      if not v_settled then
        raise exception 'delivery_reservation_requires_settled_order';
      end if;
    end if;

    -- Full cancel/fail release: after locking and proving the child guard first, subtract the exact
    -- same amount from the position.  Any mismatch aborts the statement; no clamp/silent skip exists.
    v_releasing := new.status in ('CANCELLED', 'FAILED') and v_already_gated;
    if v_releasing then
      for v_item in
        select si.id, si.order_item_id, si.reserved_quantity_kg, oi.lot_id
        from public.shipment_items si
        join public.order_items oi on oi.id = si.order_item_id
        where si.shipment_id = new.id and si.reserved_quantity_kg > 0
        order by si.id
        for update of si
      loop
        select count(*) into v_alloc_count from public.storage_allocations
        where order_item_id = v_item.order_item_id and owner_organization_id = v_order.buyer_organization_id;
        if v_alloc_count = 0 then
          raise exception 'delivery_release_position_missing';
        elsif v_alloc_count > 1 then
          raise exception 'delivery_reservation_position_ambiguous';
        end if;
        select * into v_alloc from public.storage_allocations
        where order_item_id = v_item.order_item_id and owner_organization_id = v_order.buyer_organization_id
        limit 1;
        select * into v_position from public.inventory_positions ip
        where ip.lot_id = v_item.lot_id
          and ip.owner_organization_id = v_order.buyer_organization_id
          and ip.warehouse_id = v_alloc.warehouse_id
          and ip.warehouse_location_id is not distinct from v_alloc.warehouse_location_id
        for update;
        if v_position.id is null then
          raise exception 'delivery_release_position_missing';
        end if;
        if v_position.reserved_quantity_kg < v_item.reserved_quantity_kg then
          raise exception 'delivery_reservation_ledger_inconsistent';
        end if;

        perform set_config('app.delivery_reservation_mutation', 'true', true);
        update public.shipment_items
        set reserved_quantity_kg = 0
        where id = v_item.id and reserved_quantity_kg = v_item.reserved_quantity_kg;
        perform set_config('app.delivery_reservation_mutation', 'false', true);
        get diagnostics v_rows = row_count;
        if v_rows <> 1 then
          raise exception 'delivery_reservation_ledger_inconsistent';
        end if;

        -- available_quantity_kg is NEVER incremented here: cancel/fail releases only an earmark.
        update public.inventory_positions
        set reserved_quantity_kg = reserved_quantity_kg - v_item.reserved_quantity_kg,
            updated_at = now()
        where id = v_position.id;
      end loop;
    end if;

  end if;


  if old.status <> 'DRAFT'
     and (
       new.delivery_method
         is distinct from old.delivery_method
       or new.country_code
         is distinct from old.country_code
       or new.city
         is distinct from old.city
       or new.address_line
         is distinct from old.address_line
       or new.contact_name
         is distinct from old.contact_name
       or new.contact_phone
         is distinct from old.contact_phone
       or new.shipping_fee
         is distinct from old.shipping_fee
     )
  then
    raise exception 'shipment_details_are_locked';
  end if;


  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_support_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_ticket public.support_tickets%rowtype;
begin
  if auth.uid() is null or public.is_blocked_user() then raise exception 'forbidden'; end if;
  if new.body is null or length(btrim(new.body)) not between 1 and 4000 then
    raise exception 'invalid_message_body';
  end if;
  new.body := btrim(new.body);
  select * into v_ticket from public.support_tickets where id = new.ticket_id for update;
  if not found or v_ticket.status = 'CLOSED' then raise exception 'ticket_unavailable'; end if;
  if not (public.is_platform_admin() or public.is_org_member(v_ticket.requester_organization_id)) then
    raise exception 'ticket_unavailable';
  end if;
  new.author_user_id := auth.uid();
  new.is_staff_reply := public.is_platform_admin();
  update public.support_tickets
  set status = case
      when v_ticket.status in ('RESOLVED', 'WAITING_FOR_CUSTOMER') and not new.is_staff_reply then 'IN_PROGRESS'
      when v_ticket.status = 'OPEN' and new.is_staff_reply then 'IN_PROGRESS'
      else v_ticket.status end,
    first_response_at = case
      when new.is_staff_reply then coalesce(first_response_at, clock_timestamp())
      else first_response_at end
  where id = v_ticket.id;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_support_ticket()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is null or public.is_blocked_user() then raise exception 'forbidden'; end if;
    if new.subject is null or length(btrim(new.subject)) not between 3 and 200 then
      raise exception 'invalid_ticket_subject';
    end if;
    new.subject := btrim(new.subject);
    new.requester_user_id := auth.uid();
    if new.requester_organization_id is null or not public.is_org_member(new.requester_organization_id)
       or not public.is_authorized_member() then
      raise exception 'ticket_organization_not_accessible';
    end if;
    new.status := 'OPEN';
    -- Authoritative server/database generation: override any supplied ticket_code
    new.ticket_code := public.next_support_ticket_code();

    if new.order_id is not null then
      if not public.can_view_order(new.order_id) and not public.is_platform_admin() then
        raise exception 'order_not_accessible';
      end if;
      select coalesce(new.requester_organization_id, o.buyer_organization_id), o.order_code
      into new.requester_organization_id, new.order_code_snapshot
      from public.orders o
      where o.id = new.order_id;
      if not found or not exists (
        select 1 from public.orders o where o.id = new.order_id
          and new.requester_organization_id in (o.buyer_organization_id, o.seller_organization_id)
      ) then raise exception 'order_not_accessible'; end if;
    else
      new.order_code_snapshot := null;
    end if;

    return new;
  elsif tg_op = 'UPDATE' then
    -- Immutability invariants
    if new.ticket_code is distinct from old.ticket_code then
      raise exception 'ticket_code_immutable';
    end if;

    if new.requester_user_id is distinct from old.requester_user_id then
      raise exception 'ticket_requester_user_immutable';
    end if;

    if new.requester_organization_id is distinct from old.requester_organization_id then
      raise exception 'ticket_requester_org_immutable';
    end if;

    if new.order_id is distinct from old.order_id then
      raise exception 'ticket_order_immutable';
    end if;

    new.updated_at := clock_timestamp();
    return new;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.write_audit_log_payment_accounts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_correlation_id uuid;
  v_old jsonb;
  v_new jsonb;
begin
  begin
    v_correlation_id := nullif(current_setting('app.correlation_id', true), '')::uuid;
  exception when others then
    v_correlation_id := null;
  end;

  -- Allow-list only: no full account number and no full IBAN is ever placed in a payload.
  if tg_op <> 'INSERT' then
    v_old := jsonb_build_object(
      'id', old.id,
      'account_name', old.account_name,
      'bank_name', old.bank_name,
      'swift_code', old.swift_code,
      'currency', old.currency,
      'is_active', old.is_active,
      'created_by', old.created_by,
      'created_at', old.created_at,
      'updated_at', old.updated_at,
      'account_number_last4', case when old.account_number is null then null when char_length(old.account_number) < 8 then '****' else '****' || right(old.account_number, 4) end,
      'iban_last4',           case when old.iban is null           then null when char_length(old.iban) < 8           then '****' else '****' || right(old.iban, 4) end
    );
  end if;
  if tg_op <> 'DELETE' then
    v_new := jsonb_build_object(
      'id', new.id,
      'account_name', new.account_name,
      'bank_name', new.bank_name,
      'swift_code', new.swift_code,
      'currency', new.currency,
      'is_active', new.is_active,
      'created_by', new.created_by,
      'created_at', new.created_at,
      'updated_at', new.updated_at,
      'account_number_last4', case when new.account_number is null then null when char_length(new.account_number) < 8 then '****' else '****' || right(new.account_number, 4) end,
      'iban_last4',           case when new.iban is null           then null when char_length(new.iban) < 8           then '****' else '****' || right(new.iban, 4) end
    );
    if tg_op = 'UPDATE' then
      v_new := v_new || jsonb_build_object(
        'account_number_changed', new.account_number is distinct from old.account_number,
        'iban_changed', new.iban is distinct from old.iban
      );
    end if;
  end if;

  insert into public.audit_logs (actor_user_id, entity_type, entity_id, action, old_data, new_data, metadata, correlation_id)
  values (
    auth.uid(),
    tg_table_name,
    case when tg_op = 'DELETE' then old.id else new.id end,
    tg_op,
    v_old,
    v_new,
    jsonb_build_object('redacted_fields', jsonb_build_array('account_number', 'iban'), 'redaction', 'last4_only'),
    coalesce(v_correlation_id, gen_random_uuid())
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

