CREATE OR REPLACE FUNCTION public.write_audit_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_correlation_id uuid;
begin

  begin
    v_correlation_id :=
      nullif(
        current_setting(
          'app.correlation_id',
          true
        ),
        ''
      )::uuid;
  exception
    when others then
      v_correlation_id := null;
  end;

  insert into public.audit_logs(
    actor_user_id,
    entity_type,
    entity_id,
    action,
    old_data,
    new_data,
    correlation_id
  )
  values (
    auth.uid(),
    tg_table_name,
    case
      when tg_op = 'DELETE'
      then old.id
      else new.id
    end,
    tg_op,
    case
      when tg_op = 'INSERT'
      then null
      else to_jsonb(old)
    end,
    case
      when tg_op = 'DELETE'
      then null
      else to_jsonb(new)
    end,
    coalesce(
      v_correlation_id,
      gen_random_uuid()
    )
  );

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
